const state=()=>window.state||{};
const snapshot=()=>state().snapshot||{};
function isoDate(offset){const d=new Date();d.setDate(d.getDate()+offset);return d.toISOString().slice(0,10);}
function isoTime(offsetDays,hour){const d=new Date();d.setDate(d.getDate()+offsetDays);d.setHours(hour,0,0,0);return d.toISOString();}
function mark(record,bid){return{'Business ID':bid,'Created Time':now(),'Updated Time':now(),'Record Version':1,...record,'Example Data':true,'Example Dataset ID':DATASET_ID,'Example Version':1};}
