  add('smsMessages','EX-SMS-MSG-SMITH',{'SMS Message ID':'EX-SMS-MSG-SMITH','SMS Thread ID':'EX-SMS-THREAD-SMITH','Customer ID':smith,'Job ID':job,'Direction':'Outbound Draft','Customer Number':'218-555-0142','Body':'Example draft: Your deck repair is scheduled. We will verify the stair dimensions before cutting.','Consent Status':'Consented','Status':'Draft — Not Sent'});
  add('portalThreads','EX-PORTAL-THREAD-SMITH',{'Portal Thread ID':'EX-PORTAL-THREAD-SMITH','Customer ID':smith,'Subject':'Deck repair update','Status':'Draft — Customer Release Required'});
