/* --- ./assistant-command-bus-input.js --- */
(function(){
'use strict';
const BUILD='20260824-assistant-command-input-2';
const text=v=>String(v==null?'':v).trim();
const routed=[];
let observedChat=null;
function render(){const chat=document.getElementById('paChat');if(!chat)return;chat.querySelectorAll('[data-h38-command-bus-chat]').forEach(node=>node.remove());for(const message of routed.slice(-12)){const bubble=document.createElement('div');bubble.className=`pa-bubble ${message.role}`;bubble.dataset.h38CommandBusChat='1';bubble.textContent=message.body;chat.appendChild(bubble);}chat.scrollTop=chat.scrollHeight;}
async function run(command){const bus=window.H38_ASSISTANT_COMMAND_BUS;if(!bus?.canHandle?.(command))return false;routed.push({role:'user',body:command});render();let answer='';try{answer=await bus.handle(command,{source:'personal-assistant'});}catch(error){answer=`I could not complete that command: ${text(error?.message||error)}`;}routed.push({role:'assistant',body:text(answer)||'I opened the relevant Office workflow.'});render();try{if('speechSynthesis'in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text(answer).slice(0,1200));window.speechSynthesis.speak(u);}}catch(_){}return true;}
document.addEventListener('submit',event=>{const form=event.target;if(!(form instanceof HTMLFormElement)||form.id!=='paCommandForm')return;const command=text(new FormData(form).get('command'));if(!window.H38_ASSISTANT_COMMAND_BUS?.canHandle?.(command))return;event.preventDefault();event.stopImmediatePropagation();form.reset();void run(command);},true);
function syncChatMount(){const chat=document.getElementById('paChat');if(chat===observedChat)return;observedChat=chat||null;if(chat)render();}
new MutationObserver(syncChatMount).observe(document.documentElement,{childList:true,subtree:true});
syncChatMount();
window.H38_ASSISTANT_COMMAND_INPUT=Object.freeze({enabled:true,build:BUILD,run,routedChat:true,specialistDispatch:true,nonRecursiveMountObserver:true});
})();
;

/* --- ./supabase-ai-fallback.js --- */
(function () {
  'use strict';

  const auth=window.H38_SUPABASE_AUTH;
  const Bridge=window.H38Bridge;
  if(!auth || auth.enabled!==true || !Bridge || !Bridge.prototype)return;

  const BUILD='20260812-2206';
  const ENDPOINT='h38-assistant-ai';
  const previousRequest=Bridge.prototype.request;
  const routedChat=[];
  let personalObserver=null;

  function text(value){return String(value==null?'':value);}
  function esc(value){return typeof window.esc==='function'?window.esc(value):text(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  function localAnswer(question,pageKey){
    const q=text(question).toLowerCase();
    const page=text(pageKey || 'today');
    if(/task|assign|crew|employee/.test(q)){
      return 'Open Work & Tasks. Choose the job, enter the task, select an active business user, set the due time, and save. The assignment stays internal and synchronizes to the active Supabase business.';
    }
    if(/photo|file|document|drive/.test(q)){
      return 'Use Documents & Photos or the photo button inside the job or quote. Private Office storage is the current file path. Client-owned Google Drive remains unavailable until separate business onboarding and acceptance are complete.';
    }
    if(/quote|price|estimate/.test(q)){
      return 'Open Quote Builder, select Generic Quote Customer or the correct customer, add scope and measurements, search the cached Price Book first, and save the draft. All prices and delivery remain owner-review required.';
    }
    if(/offline|sync|internet/.test(q)){
      return 'Work created without service remains in this user-scoped device queue. Reconnect, reopen the verified business, and press Sync. Nothing is sent, paid, approved, purchased, published, or filed automatically.';
    }
    if(/schedule|calendar|appointment/.test(q)){
      return 'Open Schedule, link the job, choose the assigned user, set start and end times, and save. This creates an internal schedule record only.';
    }
    return `Hank cloud service is unavailable right now. I can still guide the ${page} workflow from the installed app. Use the page forms to save internal work; every external action remains disabled or owner-controlled.`;
  }

  function safeContext(args){
    const supplied=args&&args.context&&typeof args.context==='object'?args.context:{};
    const state=window.state||{};
    const context={
      source:text(supplied.source||'h38-ai'),
      shell:text(supplied.shell||state.shell||'office'),
      pageKey:text(supplied.pageKey||args&&args.pageKey||state.page||'today'),
      pageLabel:text(supplied.pageLabel||''),
      businessName:text(supplied.businessName||state.snapshot?.business?.businessName||''),
      roleName:text(supplied.roleName||state.snapshot?.user?.roleName||''),
      quoteId:text(supplied.quoteId||''),
      projectTitle:text(supplied.projectTitle||''),
      scope:text(supplied.scope||''),
      measurementNotes:text(supplied.measurementNotes||''),
      conversationId:text(supplied.conversationId||args&&args.aiConversationId||''),
      experienceMode:text(supplied.experienceMode||''),
      receptionistProfile:text(supplied.experienceMode==='receptionist_test'?JSON.stringify(supplied.receptionistProfile||{}).slice(0,6000):'')
    };
    return context;
  }

  function howToQuestion(question){
    return /^(how|where|what|why|when|which|can you explain|could you explain|show me how|teach me|help me understand)\b/i.test(text(question).trim());
  }

  // Kit single-AI (Phase 1): route assistant Q&A to Kit via ai_handoff_tasks
  // before falling back to the OpenAI edge function. Read-only advisory only.
  function notify(message,bad){if(typeof window.toast==='function')window.toast(message,!!bad);else console[bad?'error':'log']('[Hank]',message);}
  function kitSafeContext(args){
    const c=safeContext(args||{});
    delete c.experienceMode;delete c.receptionistProfile; // receptionist test never goes to Kit
    return c;
  }
  function kitUnavailableError(e){
    const msg=text(e&&(e.message||e)||'');
    return (e&&e.code==='HANDOFF_NOT_DEPLOYED')||/timed out|(?:Kit|Hank) could not complete|handoff|disappeared|no answer/i.test(msg);
  }
  const KIT_SPECIALISTS=['general','quote','site_visit','jobs','schedule','money','documents','communications'];

  function controlledActionRequest(question){
    const q=text(question).trim();
    if(!q || howToQuestion(q))return false;
    return /^(please\s+)?(send|reply|email|text|message|approve|reject|buy|purchase|order|pay|refund|post|export|file|finalize|release|deliver|delete|invite|deploy|convert)\b/i.test(q)
      || /\b(approve and send|send it|pay it|buy it|purchase it|place the order|file the return|export payroll|post the accounting|change permissions|deploy this)\b/i.test(q);
  }

  function controlledActionAnswer(question){
    const q=text(question).toLowerCase();
    if(/send|reply|email|text|message|deliver|release/.test(q))return 'I can help prepare or review the message, but I will not send or release it. Open the existing communications or quote-delivery control, review the recipient and final content, then use its explicit owner action.';
    if(/approve|reject/.test(q))return 'I can summarize what needs review, but I will not approve or reject a business record. Open the source record and use its existing explicit approval control.';
    if(/buy|purchase|order/.test(q))return 'I can help identify what is needed, but I will not purchase or order anything. Review the item, quantity, vendor and price in the existing Office workflow before using its controlled purchase action.';
    if(/pay|refund/.test(q))return 'I can help review the amount and supporting records, but I will not move money. Use the existing Money workflow and its explicit payment control.';
    if(/post|export payroll|file|finalize/.test(q))return 'I can prepare a review summary, but accounting posting, payroll export, tax filing and finalization stay behind the existing owner-controlled workflow.';
    if(/deploy|permissions|invite|delete/.test(q))return 'That request changes system access or production state. The assistant will not execute it; use the dedicated administrative control after reviewing the exact target and impact.';
    return 'That request would create an external commitment or modify shared business state. I can explain or prepare the work, but execution must use the existing Business Office control.';
  }

  async function cloudAnswer(args,timeout){
    if(!navigator.onLine)throw new Error('Offline');
    const api=window.H38_SUPABASE_SHARED_CLIENT?.ensure?.();
    if(!api)throw new Error('Supabase client unavailable');
    const sessionResult=await api.auth.getSession();
    if(sessionResult.error)throw sessionResult.error;
    const session=sessionResult.data?.session;
    if(!session?.access_token)throw new Error('Sign in again before using Hank.');
    if(api.functions&&typeof api.functions.setAuth==='function')api.functions.setAuth(session.access_token);
    const businessId=text(args?.businessId||window.state?.businessId).trim();
    if(!businessId)throw new Error('Open an authorized business before using Hank.');
    const timeoutMs=Math.max(15000,Math.min(Number(timeout)||50000,65000));
    // Kit-first: try Kit via the handoff table; fall back to the OpenAI edge
    // function when Kit is unavailable. Receptionist test mode always uses the
    // edge function directly (it owns the TTS path). Controlled-action gating
    // already ran in ask(); Kit answers are read-only advisory.
    const rawCtx=args&&args.context&&typeof args.context==='object'?args.context:{};
    const isReceptionistTest=text(rawCtx.experienceMode)==='receptionist_test';
    if(!isReceptionistTest&&window.H38_AI_HANDOFF){
      notify('Hank is thinking…');
      try{
        const kit=await window.H38_AI_HANDOFF.runTask('assistant_qa',{
          businessId,
          question:text(args?.question).trim(),
          context:kitSafeContext(args||{}),
          role:text(window.state?.snapshot?.user?.roleName||'')
        },{timeoutMs:90000});
        if(!text(kit.answer).trim())throw new Error('Hank returned no answer.');
        return {status:'PASS',answer:text(kit.answer),
          specialist:KIT_SPECIALISTS.includes(kit.specialist)?kit.specialist:'general',
          recommendedPage:text(kit.recommendedPage),
          requiresExistingOfficeControl:kit.requiresExistingOfficeControl===true,
          reason:text(kit.reason),provider:'Hank AI handoff',externalActionOccurred:false};
      }catch(e){
        if(!kitUnavailableError(e))throw e; // real errors (auth, validation) surface
        notify('Hank is unavailable — using built-in AI instead.');
        // fall through to the OpenAI edge function below, unchanged
      }
    }
    let timer=null;
    try{
      const invoke=api.functions.invoke(ENDPOINT,{
        body:{businessId,question:text(args?.question).trim(),context:safeContext(args||{})},
        headers:{authorization:`Bearer ${session.access_token}`,'x-client-info':'h38-assistant-router-v1'}
      });
      const timed=new Promise((resolve,reject)=>{timer=setTimeout(()=>reject(new Error('Hank timed out.')),timeoutMs);});
      const result=await Promise.race([invoke,timed]);
      if(result?.error)throw new Error(text(result.error.message||result.error));
      const payload=result?.data||{};
      if(payload.status!=='PASS'||!text(payload.answer).trim())throw new Error(text(payload.message||'Hank did not return an answer.'));
      return payload;
    }finally{if(timer)clearTimeout(timer);}
  }

  async function ask(args,timeout){
    const question=text(args?.question).trim();
    if(!question)throw new Error('Ask a question first.');
    const conversationId=text(args?.aiConversationId)||`H38-AI-${Date.now()}`;
    if(controlledActionRequest(question)){
      return {
        status:'PASS',aiConversationId:conversationId,answer:controlledActionAnswer(question),provider:'H38 deterministic authority gate',
        specialist:'general',recommendedPage:'',requiresExistingOfficeControl:true,externalActionOccurred:false
      };
    }
    try{
      const cloud=await cloudAnswer(args||{},timeout);
      return {...cloud,aiConversationId:conversationId,externalActionOccurred:false};
    }catch(error){
      return {
        status:'PASS',aiConversationId:conversationId,answer:localAnswer(question,args?.pageKey),provider:'H38 local guidance',
        specialist:'general',recommendedPage:'',requiresExistingOfficeControl:false,externalActionOccurred:false,
        cloudFallbackReason:text(error?.message||error).slice(0,300)
      };
    }
  }

  Bridge.prototype.request=async function(action,args,timeout){
    if(action==='aiAsk')return ask(args||{},timeout);
    if(action==='aiBuildQuoteDraft'){
      return {
        status:'HOLD',
        message:'The Supabase operational app is ready, but a business AI provider is not connected yet. The quote was not changed, approved, or sent.',
        externalActionOccurred:false
      };
    }
    if(action==='aiMeasurePhoto'){
      return {
        status:'HOLD',
        message:'AI photo measuring needs a separately connected business AI provider. The photo and site notes remain available for manual measurement and verification.',
        externalActionOccurred:false
      };
    }
    return previousRequest.call(this,action,args,timeout);
  };

  function personalCommandStaysLocal(command){
    const q=text(command).toLowerCase().trim();
    return /^remind\s+me\b|^remember\b|^note\b|^add(?:\s+a)?\s+task\b|\bevery\s+(day|week|month)\b|\b(daily|weekly|monthly)\b/.test(q)
      || /what.*(today|need|do)|my day|what's next|whats next/.test(q)
      || /^(show|list|what are|do i have|my)\b.*\b(reminders?|personal tasks?)\b/.test(q)
      || /^(reminders?|personal tasks?)$/.test(q)
      || /blocked|stuck|needs attention|follow.?up/.test(q)
      || /^find\s+|^search\s+/.test(q)
      || /receipt|expense|mileage|schedule|calendar|appointment/.test(q);
  }

  function renderRoutedChat(){
    const chat=document.getElementById('paChat');
    if(!chat||!routedChat.length)return;
    const expected=Math.min(routedChat.length,10);
    const existing=chat.querySelectorAll('[data-h38-routed-chat]').length;
    if(existing===expected)return;
    chat.querySelectorAll('[data-h38-routed-chat]').forEach(node=>node.remove());
    routedChat.slice(-10).forEach(message=>{
      const bubble=document.createElement('div');
      bubble.className=`pa-bubble ${message.role}`;
      bubble.dataset.h38RoutedChat='1';
      bubble.innerHTML=esc(message.body).replace(/\n/g,'<br>');
      chat.appendChild(bubble);
    });
    chat.scrollTop=chat.scrollHeight;
  }

  async function routePersonalBusinessCommand(command){
    routedChat.push({role:'user',body:command});
    renderRoutedChat();
    const state=window.state||{};
    const result=await ask({
      businessId:state.businessId,
      question:command,
      pageKey:state.page,
      aiConversationId:'',
      context:{
        source:'personal-assistant',shell:state.shell,pageKey:state.page,
        businessName:state.snapshot?.business?.businessName||'',roleName:state.snapshot?.user?.roleName||''
      }
    },50000);
    routedChat.push({role:'assistant',body:text(result.answer)});
    renderRoutedChat();
    try{
      if('speechSynthesis'in window){window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text(result.answer).slice(0,1200));window.speechSynthesis.speak(utterance);}
    }catch(_){}
  }

  document.addEventListener('submit',event=>{
    const form=event.target;
    if(!(form instanceof HTMLFormElement)||form.id!=='paCommandForm')return;
    const command=text(new FormData(form).get('command')).trim();
    if(!command||personalCommandStaysLocal(command))return;
    event.preventDefault();
    event.stopImmediatePropagation();
    form.reset();
    routePersonalBusinessCommand(command).catch(error=>{
      routedChat.push({role:'assistant',body:`I could not answer that business question: ${text(error?.message||error)}`});
      renderRoutedChat();
    });
  },true);

  function installPersonalObserver(){
    if(personalObserver)return;
    const main=document.getElementById('mainContent');
    if(!main)return;
    personalObserver=new MutationObserver(()=>{if(document.getElementById('paChat'))renderRoutedChat();});
    personalObserver.observe(main,{childList:true,subtree:true});
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',installPersonalObserver,{once:true});else installPersonalObserver();

  window.H38_ASSISTANT_ROUTER=Object.freeze({
    enabled:true,build:BUILD,endpoint:ENDPOINT,readOnly:true,sharedBusinessGuidance:true,personalRecordsPrivate:true,
    specialistExecution:false,externalActionsEnabled:false,automaticApproval:false,automaticCustomerSending:false,
    automaticPurchasing:false,automaticPayment:false,ask
  });

  window.H38_SUPABASE_AI_FALLBACK={
    enabled:true,
    provider:'local-guidance',
    cloudProviderConnected:false,
    cloudAdvisoryEndpoint:ENDPOINT,
    externalActionsEnabled:false,
    readOnlyCloudAdvisory:true
  };
})();
;

/* --- ./supabase-storage-provider.js --- */
(function () {
  'use strict';

  const config=window.H38_BUSINESS_OFFICE_SUPABASE || {};
  const auth=window.H38_SUPABASE_AUTH;
  const Bridge=window.H38Bridge;
  if(!auth || auth.enabled!==true || !Bridge || !Bridge.prototype || !window.supabase)return;

  // This file ships both as an individual script and inlined in the Office
  // bundle, so it can execute twice in one page. The first execution wins for
  // the shared decorations below; the flag lives on the shared objects
  // themselves so the second copy sees it too.
  if(Bridge.prototype.__h38StorageProviderInstalled)return;
  Bridge.prototype.__h38StorageProviderInstalled=true;
  const previousRequest=Bridge.prototype.request;
  // Google Drive storage is STOOD DOWN (Rick, 2026-10-22): Drive is out of
  // the product — not reliable/fast enough for day-to-day files. Live files
  // live on H38's servers, period, and year data dumps are plain downloads.
  // With this flag off, every upload routes to Office (server) storage and
  // the Settings card presents server storage only — no Drive offer, no
  // Connect button, no dead ends. The Drive machinery below (routing,
  // connect flow, resolve/stream) stays in place, dormant and recoverable:
  // flipping this flag back on (with the server-side H38_DRIVE_LIVE_UPLOADS
  // gate) restores the 2026-10-21 own-it build exactly. Do not flip it
  // without Rick reversing the 2026-10-22 decision.
  const clientDriveAvailable=false;
  const settingsCache=new Map();
  let dbClient=null;

  function client(){
    if(dbClient)return dbClient;
    dbClient=window.supabase.createClient(config.url,config.publishableKey,{
      auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'},
      global:{headers:{'x-client-info':'highway-38-business-office-storage-provider'}}
    });
    return dbClient;
  }
  function text(value){return String(value==null?'':value);}
  function clean(value){
    if(Array.isArray(value))return value.map(clean);
    if(!value || typeof value!=='object')return value;
    const output={};
    Object.entries(value).forEach(([key,item])=>{
      if(key==='base64Data' || key==='__localPending' || key==='__h38Record')return;
      output[key]=clean(item);
    });
    return output;
  }
  async function sessionUser(){
    const {data,error}=await client().auth.getSession();
    if(error)throw error;
    if(!data.session || !data.session.user)throw new Error('Supabase Auth session is required.');
    return data.session.user;
  }
  async function setting(businessId,force=false){
    if(!businessId)throw new Error('A business is required for storage settings.');
    if(!force && settingsCache.has(businessId))return settingsCache.get(businessId);
    const {data,error}=await client().from('business_storage_settings').select('*').eq('business_id',businessId).maybeSingle();
    if(error)throw error;
    const resolved=data || {business_id:businessId,provider:'supabase',connection_status:'connected',config:{bucket:'business-office-files'}};
    settingsCache.set(businessId,resolved);
    return resolved;
  }
  async function saveDocumentRecord(businessId,recordKey,record){
    const actor=await sessionUser();
    const db=client();
    const {data:existing,error:readError}=await db.from('business_records').select('id')
      .eq('business_id',businessId).eq('collection','documents').eq('record_key',recordKey).maybeSingle();
    if(readError)throw readError;
    if(existing){
      const {error}=await db.from('business_records').update({payload:clean(record),record_status:'active',updated_by:actor.id}).eq('id',existing.id);
      if(error)throw error;
    }else{
      const {error}=await db.from('business_records').insert({business_id:businessId,collection:'documents',record_key:recordKey,payload:clean(record),record_status:'active',created_by:actor.id,updated_by:actor.id});
      if(error)throw error;
    }
  }
  async function proof(operation,details){
    try{
      const actor=await sessionUser();
      await client().from('business_proof_log').insert({
        business_id:operation.businessId,actor_user_id:actor.id,action_type:'SAVE_ATTACHMENT',entity_type:'Document',result:'PASS',
        details:Object.assign({operationId:operation.operationId || operation.id || '',externalActionOccurred:false},details || {}),
        external_action_occurred:false
      });
    }catch(error){console.warn('File Proof Log write failed:',error.message || error);}
  }
  async function failure(operation,error){
    try{
      const actor=await sessionUser();
      await client().from('business_error_log').insert({
        business_id:operation.businessId,actor_user_id:actor.id,source:'commercial-app/supabase-storage-provider.js',
        error_code:'FILE_PROVIDER_UPLOAD_FAILED',message:text(error && error.message || error).slice(0,4000),severity:'error',status:'open',
        context:{operationId:operation.operationId || operation.id || '',provider:'google_drive',fileName:operation.payload?.fileName || ''}
      });
    }catch(ignore){}
  }
  async function notifyStorageOwners(businessId,kind,title,body){
    // Existing owner-notification path: business_records collection
    // 'notifications' rendered by the Office topbar bell. Deterministic key
    // keeps this to one row per business/kind/day.
    try{
      const actor=await sessionUser();
      const day=new Date().toISOString().slice(0,10);
      const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(`${businessId}|${kind}|${day}`));
      const hash=Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,24).toUpperCase();
      const recordKey=`OWNERNOTIF-${hash}`;
      const payload={
        'Title':title,'Body':body,'Status':'Unread','Audience':'owners-admins',
        'Category':'Storage','Link Page':'settings','Source ID':recordKey,
        'Event Type':kind,'Business ID':businessId,'Customer ID':'','Customer Name':'',
        'Push Status':'off','Created Time':new Date().toISOString(),'Read By JSON':'[]',
        'Notification ID':recordKey,'Source Collection':'business_storage_settings',
        'Link Record ID':'','Record Version':1
      };
      await client().from('business_records').upsert({
        business_id:businessId,collection:'notifications',record_key:recordKey,
        payload,record_status:'active',created_by:actor.id,updated_by:actor.id
      },{onConflict:'business_id,collection,record_key',ignoreDuplicates:true});
    }catch(ignore){}
  }
  async function markLocalAttachment(operation,providerResult){
    try{
      const localId=operation.payload?.id || operation.payload?.attachmentId || operation.recordId;
      const local=await window.H38DB.get('attachments',localId);
      if(local)await window.H38DB.put('attachments',Object.assign({},local,{syncStatus:'SYNCED',storageProvider:'google_drive',providerFileId:providerResult.fileId || '',storagePath:providerResult.storagePath || '',base64Data:''}));
    }catch(ignore){}
  }
  // Returns {ok:true,data} or {ok:false,status,reason}. Never throws for a
  // business-level Drive problem: the caller falls back to Supabase storage
  // so a field file is never lost because Drive is unhappy.
  async function uploadToGoogleDrive(operation,storageSetting){
    const payload=operation.payload || {};
    if(storageSetting.connection_status!=='connected' || !storageSetting.root_folder_id){
      return {ok:false,status:'NOT_CONNECTED',reason:'This business Google Drive connection is not complete.'};
    }
    if(!payload.base64Data)return {ok:false,status:'FAIL',reason:'The queued file data is unavailable.'};
    const {data,error}=await client().functions.invoke('business-drive-upload',{
      body:{
        businessId:operation.businessId,
        attachmentId:payload.attachmentId || payload.id || operation.recordId,
        fileName:payload.fileName,
        mimeType:payload.mimeType || 'application/octet-stream',
        base64Data:payload.base64Data,
        relatedRecordType:payload.relatedRecordType || 'Business',
        relatedRecordId:payload.relatedRecordId || '',
        visibility:payload.visibility || 'Internal',
        captureTime:payload.captureTime || operation.localTimestamp || new Date().toISOString()
      }
    });
    if(error)return {ok:false,status:'FAIL',reason:text(error.message || error)};
    if(!data || data.status!=='PASS' || !data.fileId){
      return {ok:false,status:text(data?.status || 'FAIL'),reason:text(data?.error || data?.message || 'Google Drive did not confirm the upload.')};
    }
    return {ok:true,data};
  }
  async function saveDriveDocumentRecord(operation,storageSetting,data){
    const payload=operation.payload || {};
    const recordKey=text(payload.attachmentId || payload.id || operation.recordId);
    const record={
      'Document ID':recordKey,'Business ID':operation.businessId,'File Name':payload.fileName,
      'Mime Type':payload.mimeType,'File Size':payload.fileSize,'Source Type':payload.relatedRecordType,
      'Source ID':payload.relatedRecordId,'Access Classification':payload.visibility || 'Internal',
      'Storage Provider':'google_drive','Storage Location':'external',
      'Provider Account':storageSetting.provider_account_email || '',
      'Provider File ID':data.fileId,'Storage Path':data.storagePath || '',
      'Private View URL':data.webViewLink || '','Status':'Available — Private',
      'Created Time':payload.captureTime || operation.localTimestamp || new Date().toISOString(),
      'Updated Time':new Date().toISOString(),'Record Version':1
    };
    await saveDocumentRecord(operation.businessId,recordKey,record);
    await markLocalAttachment(operation,data);
    await proof(operation,{provider:'google_drive',recordKey,fileId:data.fileId,rootFolderId:storageSetting.root_folder_id});
    return {operationId:operation.operationId || operation.id,status:'SYNCED',recordType:'Document',recordId:recordKey};
  }
  async function stampFallbackRecord(operation,reason){
    // The file itself is already safe in Supabase storage via the normal
    // path; flag its document record so the fallback is visible, not silent.
    try{
      const payload=operation.payload || {};
      const recordKey=text(payload.attachmentId || payload.id || operation.recordId);
      if(!recordKey)return;
      const db=client();
      const {data:existing}=await db.from('business_records').select('id,payload')
        .eq('business_id',operation.businessId).eq('collection','documents').eq('record_key',recordKey).maybeSingle();
      if(!existing || !existing.payload)return;
      const actor=await sessionUser();
      const merged=Object.assign({},existing.payload,{
        'Storage Provider':'supabase','Storage Fallback':true,
        'Storage Fallback Reason':text(reason).slice(0,300),
        'Updated Time':new Date().toISOString()
      });
      await db.from('business_records').update({payload:clean(merged),updated_by:actor.id}).eq('id',existing.id);
    }catch(ignore){}
  }

  Bridge.prototype.request=async function(action,args,timeout){
    if(action==='fullStartupRefresh' || action==='completionBootstrap'){
      const snapshot=await previousRequest.call(this,action,args,timeout);
      const businessId=text(args && args.businessId || auth.getState().selectedBusinessId);
      if(!businessId)return snapshot;
      try{
        const storage=await setting(businessId,true);
        // Drive stood down (Rick, 2026-10-22): the snapshot presents server
        // storage as the provider whatever the dormant settings row says.
        const effectiveProvider=clientDriveAvailable?storage.provider:'supabase';
        snapshot.storageSettings={
          provider:effectiveProvider,
          connectionStatus:clientDriveAvailable?storage.connection_status:'connected',
          providerAccountEmail:clientDriveAvailable?(storage.provider_account_email || ''):'',
          rootFolderConfigured:clientDriveAvailable?!!storage.root_folder_id:false,
          config:storage.config || {}
        };
        const providers=Array.isArray(snapshot.providers)?snapshot.providers:[];
        snapshot.providers=providers.filter(row=>String(row['Provider Type'] || '').toLowerCase()!=='storage');
        const driveStatus=effectiveProvider==='google_drive'
          ? (storage.connection_status==='connected'?'Connected':storage.connection_status==='error'?'Needs attention':storage.connection_status==='connecting'?'Connecting':'Not Connected')
          : 'Connected';
        snapshot.providers.push({
          'Provider ID':'storage','Provider Type':'storage',
          'Provider Name':effectiveProvider==='google_drive'?'Client Google Drive':'Supabase private storage',
          'Connection Status':driveStatus
        });
      }catch(error){
        console.warn('Storage provider setting:',error.message || error);
      }
      return snapshot;
    }

    if(action!=='completionSync')return previousRequest.call(this,action,args,timeout);
    const operations=Array.isArray(args && args.operations)?args.operations:[];
    const attachments=operations.filter(operation=>operation.action==='SAVE_ATTACHMENT');
    if(!attachments.length)return previousRequest.call(this,action,args,timeout);

    const businessId=text(args && args.businessId || attachments[0]?.businessId || auth.getState().selectedBusinessId);
    const storage=await setting(businessId,true);
    if(!clientDriveAvailable || storage.provider!=='google_drive')return previousRequest.call(this,action,args,timeout);

    const remaining=operations.filter(operation=>operation.action!=='SAVE_ATTACHMENT');
    const results=[];
    const fallbackOps=[];
    for(const operation of attachments){
      const attempt=await uploadToGoogleDrive(operation,storage);
      if(attempt.ok){
        try{results.push(await saveDriveDocumentRecord(operation,storage,attempt.data));}
        catch(error){await failure(operation,error);fallbackOps.push({operation,reason:text(error && error.message || error)});}
      }else{
        await failure(operation,new Error(attempt.reason));
        fallbackOps.push({operation,reason:attempt.reason,status:attempt.status});
      }
    }
    const passthrough=remaining.concat(fallbackOps.map(item=>item.operation));
    if(passthrough.length){
      const response=await previousRequest.call(this,'completionSync',Object.assign({},args,{operations:passthrough}),timeout);
      results.push(...(response.results || []));
      for(const item of fallbackOps){
        await stampFallbackRecord(item.operation,item.reason);
        if(item.status==='FAIL'){
          await notifyStorageOwners(businessId,'drive_upload_fallback',
            'A file was saved to Office storage instead of Google Drive',
            'Google Drive did not accept a file, so it was saved safely to Office storage and flagged. Nothing was lost.');
        }
      }
    }
    return {status:'PASS',transport:'supabase-operational-app',results,externalActionOccurred:false};
  };

  // ---------------------------------------------------------------------------
  // Shared-client routing for DIRECT storage calls (walkthrough video, quote
  // photos, document scans and every other module that uploads through the
  // one shared Supabase client). The Bridge queue above covers queued
  // attachments; this covers the direct `storage.from(...).upload` calls at
  // the only layer they all share — the client itself.
  //   upload:         Drive-connected business -> business-drive-upload (raw
  //                   bytes); ANY failure -> original Supabase upload + flag.
  //   createSignedUrl: Drive files ('drive/<id>' paths and registered
  //                   virtual paths) resolve to a short-lived server stream
  //                   URL, so crew view files without the owner's login.
  //   business_records documents writes get their external markers stamped
  //   from the same session's routing results.
  // ---------------------------------------------------------------------------
  const drivePathInfo=new Map();      // virtual path -> {fileId, storagePath, accountEmail}
  const driveFallbackInfo=new Map();  // virtual path -> fallback reason
  const externalPathSets=new Map();   // businessId -> Set of registry paths (storage + virtual)
  const resolveCache=new Map();       // path -> {url, expires}
  const decoratedClients=new WeakSet();

  async function externalPaths(businessId){
    if(externalPathSets.has(businessId))return externalPathSets.get(businessId);
    const set=new Set();
    externalPathSets.set(businessId,set);
    try{
      const {data,error}=await client().from('business_external_files')
        .select('storage_path,virtual_path').eq('business_id',businessId).eq('status','available');
      if(!error && Array.isArray(data)){
        data.forEach(row=>{
          if(row.storage_path)set.add(text(row.storage_path));
          if(row.virtual_path)set.add(text(row.virtual_path));
        });
      }
    }catch(ignore){}
    return set;
  }
  async function resolveDriveUrl(path,businessIdHint){
    const cached=resolveCache.get(path);
    if(cached && cached.expires>Date.now())return {url:cached.url};
    const businessId=businessIdHint || text(auth.getState().selectedBusinessId);
    const body={action:'resolve',businessId,
      storagePath:path.startsWith('drive/')?path:'',
      virtualPath:path.startsWith('drive/')?'':path};
    const {data,error}=await client().functions.invoke('business-drive-connect',{body});
    if(error)throw error;
    if(data && data.url){
      resolveCache.set(path,{url:text(data.url),expires:Date.now()+480000});
      return {url:text(data.url)};
    }
    if(data && data.unavailable)return {unavailable:true,reason:text(data.reason || 'This file is unavailable.')};
    return {found:false};
  }
  async function driveAwareUpload(origUpload,bucket,path,body,options){
    const parts=String(path).split('/');
    const businessId=parts[0] || '';
    try{
      const sizeable=body instanceof Blob || body instanceof ArrayBuffer || ArrayBuffer.isView(body);
      if(!businessId || !sizeable || !navigator.onLine)return origUpload(path,body,options);
      const blob=body instanceof Blob?body:new Blob([body]);
      if(!blob.size || blob.size>100*1024*1024)return origUpload(path,body,options);
      if(!clientDriveAvailable)return origUpload(path,body,options);
      const st=await setting(businessId);
      if(!st || st.provider!=='google_drive' || st.connection_status!=='connected')return origUpload(path,body,options);
      const {data:sessionData}=await client().auth.getSession();
      const session=sessionData && sessionData.session;
      if(!session)return origUpload(path,body,options);
      const res=await fetch(`${config.url}/functions/v1/business-drive-upload`,{
        method:'POST',
        headers:{
          'Authorization':`Bearer ${session.access_token}`,
          'apikey':config.publishableKey,
          'Content-Type':blob.type || 'application/octet-stream',
          'x-h38-business-id':businessId,
          'x-h38-file-name':parts.slice(3).join('/') || 'file',
          'x-h38-mime-type':blob.type || 'application/octet-stream',
          'x-h38-source-type':parts[1] || '',
          'x-h38-source-id':parts[2] || '',
          'x-h38-virtual-path':path
        },
        body:blob
      });
      const data=await res.json().catch(()=>null);
      if(res.ok && data && data.status==='PASS' && data.fileId){
        drivePathInfo.set(path,{fileId:text(data.fileId),storagePath:text(data.storagePath),accountEmail:st.provider_account_email || ''});
        const set=await externalPaths(businessId);
        set.add(path);
        if(data.storagePath)set.add(text(data.storagePath));
        return {data:{path,fullPath:`${bucket}/${path}`,id:text(data.fileId)},error:null};
      }
      const reason=text((data && data.error) || `Drive upload failed (${res.status}).`);
      driveFallbackInfo.set(path,reason);
      if(data && data.status==='FAIL'){
        await notifyStorageOwners(businessId,'drive_upload_fallback',
          'A file was saved to Office storage instead of Google Drive',
          'Google Drive did not accept a file, so it was saved safely to Office storage and flagged. Nothing was lost.');
      }
      return origUpload(path,body,options);
    }catch(error){
      try{driveFallbackInfo.set(path,text(error && error.message || error));}catch(ignore){}
      return origUpload(path,body,options);
    }
  }
  async function driveAwareSignedUrl(origSigned,path,expiresIn,options){
    const p=text(path);
    try{
      if(p.startsWith('drive/')){
        const resolved=await resolveDriveUrl(p,'');
        if(resolved.url)return {data:{signedUrl:resolved.url},error:null};
        if(resolved.unavailable)return {data:null,error:new Error(resolved.reason)};
        return {data:null,error:new Error('This Drive file could not be loaded right now.')};
      }
      const businessId=p.split('/')[0] || '';
      if(businessId){
        const set=await externalPaths(businessId);
        if(set.has(p)){
          const resolved=await resolveDriveUrl(p,businessId);
          if(resolved.url)return {data:{signedUrl:resolved.url},error:null};
          if(resolved.unavailable)return {data:null,error:new Error(resolved.reason)};
        }
      }
    }catch(ignore){}
    return origSigned(path,expiresIn,options);
  }
  function stampDocumentRows(rows){
    const stampOne=row=>{
      if(!row || row.collection!=='documents' || !row.payload || typeof row.payload!=='object')return row;
      const path=text(row.payload['Storage Path']);
      if(!path)return row;
      if(drivePathInfo.has(path)){
        const info=drivePathInfo.get(path);
        return Object.assign({},row,{payload:Object.assign({},row.payload,{
          'Storage Provider':'google_drive','Storage Location':'external',
          'Provider File ID':info.fileId,
          'Provider Account':info.accountEmail || row.payload['Provider Account'] || ''
        })});
      }
      if(driveFallbackInfo.has(path)){
        return Object.assign({},row,{payload:Object.assign({},row.payload,{
          'Storage Fallback':true,'Storage Fallback Reason':driveFallbackInfo.get(path).slice(0,300)
        })});
      }
      return row;
    };
    return Array.isArray(rows)?rows.map(stampOne):stampOne(rows);
  }
  function decorateSharedClient(shared){
    if(!shared || decoratedClients.has(shared) || shared.__h38DriveRoutingV1)return;
    decoratedClients.add(shared);
    shared.__h38DriveRoutingV1=true;
    try{
      const origFrom=shared.from.bind(shared);
      shared.from=function(table){
        const builder=origFrom(table);
        if(table!=='business_records')return builder;
        const proxy=new Proxy(builder,{
          get(target,prop){
            if(prop==='insert' || prop==='upsert'){
              return (...args)=>{
                try{args[0]=stampDocumentRows(args[0]);}catch(ignore){}
                const out=target[prop](...args);
                return out===target?proxy:out;
              };
            }
            const value=Reflect.get(target,prop,target);
            return typeof value==='function'?value.bind(target):value;
          }
        });
        return proxy;
      };
    }catch(error){console.warn('Drive record stamping unavailable:',error.message || error);}
    try{
      const origStorageFrom=shared.storage.from.bind(shared.storage);
      shared.storage.from=function(bucket){
        const api=origStorageFrom(bucket);
        if(bucket!=='business-office-files')return api;
        const origUpload=api.upload.bind(api);
        const origSigned=api.createSignedUrl.bind(api);
        api.upload=(path,body,options)=>driveAwareUpload(origUpload,bucket,path,body,options);
        api.createSignedUrl=(path,expiresIn,options)=>driveAwareSignedUrl(origSigned,path,expiresIn,options);
        return api;
      };
    }catch(error){console.warn('Drive upload routing unavailable:',error.message || error);}
  }
  function installClientRouting(){
    try{
      const shared=window.H38_SUPABASE_SHARED_CLIENT && window.H38_SUPABASE_SHARED_CLIENT.ensure
        ? window.H38_SUPABASE_SHARED_CLIENT.ensure() : null;
      if(shared)decorateSharedClient(shared);
    }catch(ignore){}
  }
  installClientRouting();

  // ---------------------------------------------------------------------------
  // Settings card: File storage (own-it Google Drive).
  // ---------------------------------------------------------------------------
  let cardStatusCache={at:0,businessId:'',status:null};
  function fmtBytes(bytes){
    const n=Number(bytes || 0);
    if(!n)return '0 MB';
    if(n>=1073741824)return `${(n/1073741824).toFixed(2)} GB`;
    if(n>=1048576)return `${(n/1048576).toFixed(1)} MB`;
    return `${Math.max(1,Math.round(n/1024))} KB`;
  }
  function currentBusinessId(){
    return text(window.state?.businessId || auth.getState().selectedBusinessId);
  }
  async function fetchDriveStatus(businessId,force=false){
    if(!force && cardStatusCache.businessId===businessId && Date.now()-cardStatusCache.at<30000)return cardStatusCache.status;
    const {data,error}=await client().functions.invoke('business-drive-connect',{body:{action:'status',businessId}});
    if(error)throw error;
    cardStatusCache={at:Date.now(),businessId,status:data};
    return data;
  }
  function driveQueryNotice(){
    try{
      const params=new URLSearchParams(window.location.search);
      const drive=params.get('drive');
      if(!drive)return '';
      window.history.replaceState({},'',window.location.pathname+window.location.hash);
      if(drive==='connected')return '<div class="notice">Google Drive is connected. New files will be stored in your Drive.</div>';
      const reason=params.get('driveReason') || '';
      const copy={
        cancelled:'The Google sign-in was cancelled, so nothing changed.',
        state:'That connection link expired. Start the connection again.',
        role:'Only an owner or administrator can connect Drive for this business.',
        exchange:'Google did not complete the connection. Start again, or ask Highway 38 for help.'
      }[reason] || 'The connection did not complete. Start again, or ask Highway 38 for help.';
      return `<div class="notice">${copy}</div>`;
    }catch(ignore){return '';}
  }
  function renderStorageSettingsCard(){
    if(window.state?.page!=='settings')return false;
    const grid=document.querySelector('#mainContent .grid');
    if(!grid)return false;
    document.getElementById('businessStorageProviderCard')?.remove();
    const businessId=currentBusinessId();
    const snapshotStorage=window.state?.snapshot?.storageSettings || {provider:'supabase',connectionStatus:'connected'};
    const status=(cardStatusCache.businessId===businessId && cardStatusCache.status) || null;
    const provider=status?status.provider:snapshotStorage.provider;
    const connectionStatus=status?status.connectionStatus:snapshotStorage.connectionStatus;
    const configured=status?status.configured:true; // server re-checks on click; assume until status lands
    const email=status?(status.providerAccountEmail || ''):(snapshotStorage.providerAccountEmail || '');
    const drive=provider==='google_drive';
    const card=document.createElement('section');
    card.id='businessStorageProviderCard';card.className='card span6';
    if(!clientDriveAvailable){
      // Drive stood down (Rick, 2026-10-22): server storage is the one live
      // path and the only thing this card offers — no Drive offer, no
      // Connect button. Year dumps are plain downloads from Data & storage.
      card.innerHTML=`<h2>File storage</h2>
      <div class="row"><div><strong>Supabase private storage</strong><small>Private storage inside this business Office, on Highway 38's servers</small></div>${window.pill('Connected','good')}</div>
      <p class="muted">Your photos, videos and attachments are stored privately on Highway 38's own servers — fast, and under our control — and count toward your own 15 GB of included memory storage (see Data &amp; storage). Records and accounting always stay in the Office.</p>
      <p class="muted">Need a copy of a full year? Export it any time from the Data &amp; storage card — it downloads straight to you.</p>`;
      grid.appendChild(card);
      return true;
    }
    let inner=`<h2>File storage</h2>`;
    inner+=driveQueryNotice();
    if(!drive){
      inner+=`<div class="row"><div><strong>Supabase private storage</strong><small>Default private storage inside this business Office</small></div>${window.pill('Connected','good')}</div>
      <p class="muted">Your photos, videos and attachments are stored privately in Highway 38's storage and count toward your 15 GB of included server data. Records and accounting always stay in the Office either way.</p>`;
      if(configured){
        inner+=`<div class="notice">Own your storage: connect this business's Google Drive and new photos, walkthrough videos and attachments are stored in your Drive instead — they stop counting toward your 15 GB. Highway 38 sets this up with you; the connection itself is approved by the account owner here.</div>
        <div class="row"><button type="button" class="btn" data-drive-action="connect">Connect your Google Drive</button></div>`;
      }else{
        inner+=`<div class="notice">Own-it Drive storage is being finished by Highway 38 for this business. Ask us to complete the setup — your files keep using private Office storage meanwhile.</div>`;
      }
    }else if(connectionStatus==='connected'){
      const count=status?Number(status.externalFileCount || 0):0;
      const bytes=status?Number(status.externalBytes || 0):0;
      inner+=`<div class="row"><div><strong>Your Google Drive</strong><small>${email || 'Connected account'}</small></div>${window.pill('Connected','good')}</div>
      <p class="muted">${count} file${count===1?'':'s'} (${fmtBytes(bytes)}) stored in your Drive. Files in your Drive do not count toward your 15 GB of included server data. Records and accounting stay in the Office.</p>
      <div class="row"><button type="button" class="btn" data-drive-action="connect">Reconnect</button><button type="button" class="btn" data-drive-action="disconnect">Disconnect</button></div>
      <p class="muted">Disconnecting returns new files to Office storage. Files already in your Drive stay there and remain yours.</p>`;
    }else if(connectionStatus==='error'){
      inner+=`<div class="row"><div><strong>Your Google Drive</strong><small>${email || 'Connection needs attention'}</small></div>${window.pill('Needs attention','pending')}</div>
      <div class="notice">Your Drive connection needs attention, so new files are being saved safely to Office storage for now. Nothing is lost. Reconnect to resume Drive storage.</div>
      <div class="row"><button type="button" class="btn" data-drive-action="connect">Reconnect Google Drive</button><button type="button" class="btn" data-drive-action="disconnect">Disconnect</button></div>`;
    }else{
      inner+=`<div class="row"><div><strong>Your Google Drive</strong><small>Connection started but not finished</small></div>${window.pill('Setup required','pending')}</div>
      <div class="notice">Finish connecting the business's Google Drive so new files are stored there. Until then, files keep using private Office storage.</div>
      <div class="row"><button type="button" class="btn" data-drive-action="connect">Connect your Google Drive</button></div>`;
    }
    card.innerHTML=inner;
    grid.appendChild(card);
    card.querySelectorAll('[data-drive-action]').forEach(button=>{
      button.addEventListener('click',()=>driveCardAction(button.getAttribute('data-drive-action'),businessId,button));
    });
    // No status fetch on render: opening Settings must not perform automatic
    // function work. The card renders from the local snapshot; the server
    // status is checked only inside driveCardAction (user action).
    return true;
  }
  async function driveCardAction(action,businessId,button){
    if(!clientDriveAvailable || !businessId)return; // Drive stood down (Rick, 2026-10-22)
    const original=button.textContent;
    button.disabled=true;button.textContent='Working…';
    try{
      // User-triggered status refresh (never automatic on Settings open).
      try{await fetchDriveStatus(businessId,true);}catch(ignore){}
      if(action==='connect'){
        const {data,error}=await client().functions.invoke('business-drive-connect',{body:{action:'authorize-url',businessId}});
        if(error)throw error;
        if(data && data.configured===false){
          cardStatusCache={at:Date.now(),businessId,status:Object.assign({},cardStatusCache.status || {},{configured:false})};
          renderStorageSettingsCard();
          return;
        }
        if(data && data.url){window.location.href=data.url;return;}
        throw new Error('Google did not return a sign-in link.');
      }
      if(action==='disconnect'){
        if(!window.confirm('Disconnect Google Drive? New files will be stored in Office storage again. Files already in your Drive stay there.'))return;
        const {data,error}=await client().functions.invoke('business-drive-connect',{body:{action:'disconnect',businessId}});
        if(error)throw error;
        if(!data || data.status!=='PASS')throw new Error('Disconnect did not complete.');
        settingsCache.delete(businessId);
        externalPathSets.delete(businessId);
        cardStatusCache={at:0,businessId:'',status:null};
        try{await setting(businessId,true);}catch(ignore){}
        if(window.toast)window.toast('Google Drive disconnected. New files will use Office storage.');
        renderStorageSettingsCard();
      }
    }catch(error){
      if(window.toast)window.toast(text(error && error.message || error),true);
    }finally{
      button.disabled=false;button.textContent=original;
    }
  }
  function scheduleStorageSettingsCard(){queueMicrotask(()=>{try{renderStorageSettingsCard();}catch(error){console.warn('Storage Settings card:',error.message||error);}});}
  window.addEventListener('h38:office-page-rendered',event=>{if(event?.detail?.page==='settings')scheduleStorageSettingsCard();});
  window.addEventListener('h38:business-snapshot-updated',()=>{installClientRouting();if(window.state?.page==='settings')scheduleStorageSettingsCard();});

  window.H38_STORAGE_PROVIDER={
    get:businessId=>setting(businessId,true),
    supported:clientDriveAvailable?['supabase','google_drive']:['supabase'],
    defaultProvider:'supabase',
    clientDriveAvailable,
    renderSettingsCard:renderStorageSettingsCard,
    settingsRendererOwnership:false,
    safeguards:{credentialsInBrowser:false,crossTenantAccess:false,automaticCustomerRelease:false}
  };
})();

/* --- ./supabase-client-installer.js --- */
(function () {
  'use strict';

  const config=window.H38_BUSINESS_OFFICE_SUPABASE || {};
  const auth=window.H38_SUPABASE_AUTH;
  if(!auth || auth.enabled!==true || !window.supabase)return;

  const DEFAULT_MODULES=[
    'today','customers','jobs','tasks','quotes','measure','schedule','communications',
    'field','daily-logs','checklists','time','inventory','fleet','money','documents',
    'social','ai','settings','people','accounting','payroll-prep','tax-prep','controls',
    'reports','storage-providers'
  ];
  const NL_OWNER_LOGIN='https://highway38solutions.com/businesses/northern-lakes/owner-login.html';
  const CLIENT_TENANT_REFRESH_TIMEOUT_MS=8000;
  let installerClient=null;
  let installerState=null;
  let loading=false;
  let loadedOnce=false;
  let refreshPromise=null;

  function client(){
    if(installerClient)return installerClient;
    installerClient=window.supabase.createClient(config.url,config.publishableKey,{
      auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'},
      global:{headers:{'x-client-info':'h38-client-tenant-installer'}}
    });
    return installerClient;
  }
  function text(value){return String(value==null?'':value);}
  function escape(value){return window.esc?window.esc(value):text(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));}
  function statusPill(value){
    const status=text(value || 'unknown');
    const kind=status==='active'?'good':status==='suspended'||status==='closed'?'bad':'pending';
    return window.pill?window.pill(status,kind):`<span class="pill ${kind}">${escape(status)}</span>`;
  }
  function isPlatformOwner(){
    return window.state?.snapshot?.business?.businessKey==='highway38' && window.state?.snapshot?.user?.owner===true;
  }
  function settingsVisible(){return window.state?.page==='settings' && !!document.querySelector('#mainContent .grid');}
  function tenantUrl(businessKey){
    const url=new URL('./',location.href);
    url.searchParams.set('businessKey',businessKey);
    return url.toString();
  }
  function installerRows(){
    return Array.isArray(installerState?.businesses)?installerState.businesses:[];
  }
  function withTimeout(promise,ms){
    let timer=0;
    const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('Client tenant status check timed out. Settings remains usable; retry when ready.')),ms);});
    return Promise.race([promise,timeout]).finally(()=>clearTimeout(timer));
  }

  async function refreshState(){
    if(!isPlatformOwner())return null;
    if(refreshPromise)return refreshPromise;
    loading=true;
    refreshPromise=(async()=>{
      try{
        const {data,error}=await withTimeout(client().rpc('client_tenant_installer_state'),CLIENT_TENANT_REFRESH_TIMEOUT_MS);
        if(error)throw error;
        if(!data || data.status!=='PASS')throw new Error('Client tenant installer state failed closed.');
        installerState=data;
        loadedOnce=true;
        return data;
      }finally{
        loading=false;
        refreshPromise=null;
      }
    })();
    return refreshPromise;
  }

  async function provision(payload){
    const {data,error}=await client().rpc('provision_client_business',payload);
    if(error)throw error;
    if(!data || data.status!=='PASS')throw new Error('Client tenant provisioning did not return PASS.');
    return data;
  }
  async function activate(businessId){
    const {data,error}=await client().rpc('activate_client_business',{p_business_id:businessId});
    if(error)throw error;
    if(!data || data.status!=='PASS')throw new Error('Client tenant activation did not return PASS.');
    return data;
  }
  async function suspend(businessId,reason){
    const {data,error}=await client().rpc('suspend_client_business',{p_business_id:businessId,p_reason:reason});
    if(error)throw error;
    if(!data || data.status!=='PASS')throw new Error('Client tenant suspension did not return PASS.');
    return data;
  }

  function rowHtml(row){
    const ownerClaimed=!!row.ownerAuthUserId;
    const ownerStatus=ownerClaimed?'claimed':text(row.ownerMembershipStatus || 'missing');
    const openUrl=tenantUrl(row.businessKey);
    const activationUrl=row.businessKey==='northern-lakes'?NL_OWNER_LOGIN:'';
    return `<div class="row" data-client-business="${escape(row.businessId)}">
      <div class="row-top"><div><strong>${escape(row.displayName)}</strong><small>${escape(row.businessKey)} · ${escape(row.packageId || 'standard')}</small></div>${statusPill(row.businessStatus)}</div>
      <small>Owner: ${escape(row.ownerEmail)} · ${escape(ownerStatus)} · Storage: ${escape(row.storageProvider || 'not set')} (${escape(row.storageConnectionStatus || 'unknown')}) · ${Number(row.enabledModuleCount || 0)} modules · ${Number(row.recordCount || 0)} records</small>
      <div class="row-actions">
        <a class="secondary" href="${escape(openUrl)}" target="_self">Open tenant</a>
        ${activationUrl?`<a class="secondary" href="${escape(activationUrl)}" target="_blank" rel="noopener">Owner activation page</a>`:''}
        ${row.businessStatus!=='active'?`<button data-activate-client="${escape(row.businessId)}">Activate closed beta</button>`:''}
        ${row.businessStatus==='active'?`<button class="danger" data-suspend-client="${escape(row.businessId)}">Suspend access</button>`:''}
      </div>
    </div>`;
  }

  function listHtml(){
    if(loading)return '<div class="empty">Loading client tenants… Settings remains available.</div>';
    if(!loadedOnce)return '<div class="empty">Client tenant status is not loaded automatically. Use Load client tenants when you need installer controls.</div>';
    const rows=installerRows();
    return rows.length?rows.map(rowHtml).join(''):'<div class="empty">No client tenants have been provisioned.</div>';
  }

  function renderCard(){
    if(!isPlatformOwner() || !settingsVisible())return false;
    const grid=document.querySelector('#mainContent .grid');
    if(!grid)return false;
    if(document.getElementById('clientTenantInstallerCard'))return true;

    const card=document.createElement('section');
    card.id='clientTenantInstallerCard';
    card.className='card';
    card.innerHTML=`<h2>Client tenant installer</h2>
      <p class="muted">Create an isolated Supabase business, prepare its owner invitation, select private storage, and activate it only after acceptance. This never imports Google records or changes an Apps Script deployment.</p>
      <div class="notice warn"><strong>Explicit controls:</strong> provisioning does not send an email or activate the business. The invited user requests the secure email from the branded owner-login page. Customer sending, payments, purchases, payroll, tax filing, publishing and advertising stay disabled.</div>
      <div class="actions"><button id="refreshClientTenants" type="button" class="secondary" ${loading?'disabled':''}>${loading?'Loading…':loadedOnce?'Refresh client tenants':'Load client tenants'}</button></div>
      <div id="clientTenantList" class="list">${listHtml()}</div>
      <details id="clientTenantCreatePanel" style="margin-top:14px">
        <summary><strong>Provision or refresh a client tenant</strong></summary>
        <form id="clientTenantForm">
          <div class="two"><div><label>Business key</label><input name="businessKey" required pattern="[a-z0-9][a-z0-9\\-]{1,62}" value="northern-lakes"></div><div><label>Package ID</label><input name="packageId" required value="northern-lakes-closed-beta"></div></div>
          <label>Legal name</label><input name="legalName" required value="Northern Lakes Property Maintenance LLC">
          <label>Display name</label><input name="displayName" required value="Northern Lakes Property Maintenance LLC">
          <div class="two"><div><label>Owner email</label><input name="ownerEmail" type="email" required value="northernlakesproperty@gmail.com"></div><div><label>Timezone</label><input name="timezone" required value="America/Chicago"></div></div>
          <div class="two"><div><label>Primary color</label><input name="primaryColor" value="#113b2e"></div><div><label>Accent color</label><input name="accentColor" value="#9a632f"></div></div>
          <label>Logo URL</label><input name="logoUrl" value="https://highway38solutions.com/businesses/northern-lakes/assets/diamond-logo.png?v=rendered-photo-pass-20260726">
          <label>Additional customer-visible H38 support email</label><input name="supportEmail" type="email" value="mandakw55@gmail.com">
          <div class="actions"><button type="submit">Provision or refresh</button></div>
        </form>
      </details>`;
    grid.appendChild(card);

    const refresh=document.getElementById('refreshClientTenants');
    if(refresh)refresh.onclick=()=>refreshAndRender();

    const form=document.getElementById('clientTenantForm');
    form.onsubmit=async event=>{
      event.preventDefault();
      const data=new FormData(form);
      const submit=form.querySelector('button[type="submit"]');
      try{
        submit.disabled=true;
        const businessKey=text(data.get('businessKey')).trim().toLowerCase();
        const result=await provision({
          p_business_key:businessKey,
          p_legal_name:text(data.get('legalName')).trim(),
          p_display_name:text(data.get('displayName')).trim(),
          p_owner_email:text(data.get('ownerEmail')).trim().toLowerCase(),
          p_timezone:text(data.get('timezone')).trim(),
          p_brand_config:{currency:'USD',industryPack:businessKey==='northern-lakes'?'property-maintenance':'service-business',logoUrl:text(data.get('logoUrl')).trim(),primaryColor:text(data.get('primaryColor')).trim(),accentColor:text(data.get('accentColor')).trim(),secondaryColor:businessKey==='northern-lakes'?'#f4efe5':'#eef3f7'},
          p_module_keys:DEFAULT_MODULES,
          p_package_id:text(data.get('packageId')).trim().toLowerCase(),
          p_support_email:text(data.get('supportEmail')).trim().toLowerCase() || null
        });
        window.toast?.(`${result.businessKey} is provisioned. Activation and invitation email remain separate.`);
        await refreshAndRender();
      }catch(error){window.toast?.(text(error && error.message || error),true);}
      finally{submit.disabled=false;}
    };

    bindActions(card);
    return true;
  }

  function bindActions(card){
    card.querySelectorAll('[data-activate-client]').forEach(button=>{
      button.onclick=async()=>{
        const businessId=button.dataset.activateClient;
        if(!confirm('Activate this client for the closed beta? This allows active members to open its isolated Supabase data. External actions remain disabled.'))return;
        try{button.disabled=true;await activate(businessId);window.toast?.('Client closed beta activated.');await refreshAndRender();}
        catch(error){window.toast?.(text(error && error.message || error),true);button.disabled=false;}
      };
    });
    card.querySelectorAll('[data-suspend-client]').forEach(button=>{
      button.onclick=async()=>{
        const businessId=button.dataset.suspendClient;
        if(!confirm('Suspend this client Business Office now? Cached data cannot override an online suspension.'))return;
        try{button.disabled=true;await suspend(businessId,'Suspended by Highway 38 Owner from Client Tenant Installer.');window.toast?.('Client access suspended.');await refreshAndRender();}
        catch(error){window.toast?.(text(error && error.message || error),true);button.disabled=false;}
      };
    });
  }

  async function refreshAndRender(){
    if(!isPlatformOwner())return null;
    const promise=refreshState();
    if(settingsVisible()){document.getElementById('clientTenantInstallerCard')?.remove();renderCard();}
    try{return await promise;}
    catch(error){window.toast?.(text(error && error.message || error),true);return null;}
    finally{if(settingsVisible()){document.getElementById('clientTenantInstallerCard')?.remove();renderCard();}}
  }

  function scheduleCard(){queueMicrotask(()=>{try{renderCard();}catch(error){console.warn('Client tenant Settings card:',error.message||error);}});}
  window.addEventListener('h38:office-page-rendered',event=>{if(event?.detail?.page==='settings')scheduleCard();});
  window.addEventListener('h38:business-snapshot-updated',()=>{if(settingsVisible())scheduleCard();});

  window.H38_CLIENT_TENANT_INSTALLER={
    enabled:true,
    systemOfRecord:'supabase',
    automaticActivation:false,
    automaticInvitationEmail:false,
    automaticSettingsRefresh:false,
    explicitRefreshOnly:true,
    refreshTimeoutMs:CLIENT_TENANT_REFRESH_TIMEOUT_MS,
    googleDataImport:false,
    appsScriptMutation:false,
    settingsRendererOwnership:false,
    renderCard,
    refresh:refreshState
  };
})();
;

/* --- ./supabase-portal-hydration.js --- */
(function () {
  'use strict';

  const config=window.H38_BUSINESS_OFFICE_SUPABASE || {};
  const auth=window.H38_SUPABASE_AUTH;
  const Bridge=window.H38Bridge;
  if(!auth || auth.enabled!==true || !Bridge || !Bridge.prototype || !window.supabase)return;

  const previousRequest=Bridge.prototype.request;
  let dbClient=null;

  function client(){
    if(dbClient)return dbClient;
    dbClient=window.supabase.createClient(config.url,config.publishableKey,{
      auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,flowType:'pkce'},
      global:{headers:{'x-client-info':'highway-38-business-office-portal-hydration'}}
    });
    return dbClient;
  }
  function text(value){return String(value==null?'':value);}
  function number(value){const parsed=Number(value || 0);return Number.isFinite(parsed)?parsed:0;}
  function merge(existing,incoming,idKey){
    const map=new Map();
    (incoming || []).forEach(row=>map.set(text(row[idKey]),row));
    (existing || []).forEach(row=>map.set(text(row[idKey]),row));
    return Array.from(map.values());
  }
  async function optional(promise){
    try{const response=await promise;if(response.error)throw response.error;return response.data || [];}
    catch(error){console.warn('Supabase portal hydration:',error.message || error);return [];}
  }

  async function hydrate(snapshot,businessId){
    const db=client();
    const [customers,businessRecordCustomers,jobs,quotes,quoteItems,invoices,messages,files]=await Promise.all([
      optional(db.from('customer_accounts').select('id,customer_code,display_name,email,status,portal_enabled,created_at,updated_at').eq('business_id',businessId).order('updated_at',{ascending:false}).limit(1000)),
      optional(db.from('business_records').select('record_key,payload,created_at,updated_at').eq('business_id',businessId).eq('collection','customers').eq('record_status','active').order('updated_at',{ascending:false}).limit(5000)),
      optional(db.from('customer_jobs').select('id,customer_id,job_number,title,status,next_action,due_date,progress_percent,expected_update_date,created_at,updated_at').eq('business_id',businessId).order('updated_at',{ascending:false}).limit(1000)),
      optional(db.from('customer_quotes').select('id,customer_id,job_id,quote_number,title,amount,status,version,customer_decision,decision_at,deliverables,timing,revision_allowance,exclusions,approval_consequence,created_at,updated_at').eq('business_id',businessId).order('updated_at',{ascending:false}).limit(1000)),
      optional(db.from('quote_items').select('id,quote_id,line_number,work_package,item_type,description,quantity,unit,unit_price,amount,pricing_source,owner_review_required,approved,created_at,updated_at').eq('business_id',businessId).order('quote_id').order('line_number').limit(5000)),
      optional(db.from('customer_invoices').select('id,customer_id,invoice_number,total,balance_due,status,due_date,created_at,updated_at').eq('business_id',businessId).order('updated_at',{ascending:false}).limit(1000)),
      optional(db.from('customer_messages').select('id,customer_id,job_id,body,direction,status,created_by,created_at').eq('business_id',businessId).order('created_at',{ascending:true}).limit(2000)),
      optional(db.from('customer_files').select('id,customer_id,job_id,file_name,storage_path,status,available_to_customer,created_at,updated_at').eq('business_id',businessId).order('updated_at',{ascending:false}).limit(2000))
    ]);

    const customerRows=customers.map(row=>({
      'Customer ID':row.id,'Business ID':businessId,'Customer Code':row.customer_code,
      'Customer Name':row.display_name,'Email':row.email,'Phone':'',
      'Status':row.status==='active'?'Active':row.status,
      'Portal Enabled':row.portal_enabled===true,'Created Time':row.created_at,
      'Updated Time':row.updated_at,'Record Version':1,'Supabase Portal Record':true
    }));
    const businessRecordCustomerRows=businessRecordCustomers
      .filter(row=>text(row.record_key)!=='GENERIC-QUOTE-CUSTOMER')
      .map(row=>{
        const payload=row.payload && typeof row.payload==='object' && !Array.isArray(row.payload)?row.payload:{};
        return {
          ...payload,
          'Customer ID':text(payload['Customer ID'] || row.record_key),
          'Business ID':businessId,
          'Status':text(payload['Status'] || 'Active'),
          'Created Time':payload['Created Time'] || row.created_at,
          'Updated Time':payload['Updated Time'] || row.updated_at,
          'Record Version':payload['Record Version'] || 1,
          'Supabase Business Record':true
        };
      });
    const jobRows=jobs.map(row=>({
      'Job ID':row.id,'Business ID':businessId,'Customer ID':row.customer_id,
      'Job Number':row.job_number,'Project Title':row.title,'Status':row.status,
      'Next Action':row.next_action || '','Due Date':row.due_date || '',
      'Expected Update Date':row.expected_update_date || '',
      'Progress Percent':number(row.progress_percent),'Created Time':row.created_at,
      'Updated Time':row.updated_at,'Record Version':1,'Supabase Portal Record':true
    }));
    const linesByQuote=new Map();
    quoteItems.forEach(row=>{
      const list=linesByQuote.get(row.quote_id) || [];
      list.push({
        'Quote Line ID':row.id,'Line Number':row.line_number,'Work Package':row.work_package || '',
        'Item Type':row.item_type,'Description':row.description,'Quantity':number(row.quantity),
        'Unit':row.unit,'Unit Price':number(row.unit_price),'Amount':number(row.amount),
        'Pricing Source':row.pricing_source,'Owner Review Required':row.owner_review_required===true,
        'Approved':row.approved===true
      });
      linesByQuote.set(row.quote_id,list);
    });
    const quoteRows=quotes.map(row=>({
      'Quote ID':row.id,'Business ID':businessId,'Customer ID':row.customer_id,
      'Job ID':row.job_id || '','Quote Number':row.quote_number,'Project Title':row.title,
      'Status':row.status,'Revision':number(row.version),'Subtotal':number(row.amount),
      'Tax':0,'Total':number(row.amount),'Customer Decision':row.customer_decision || '',
      'Decision Time':row.decision_at || '','Deliverables':row.deliverables || '',
      'Timing':row.timing || '','Revision Allowance':row.revision_allowance || '',
      'Exclusions':row.exclusions || '','Approval Consequence':row.approval_consequence || '',
      'Created Time':row.created_at,'Updated Time':row.updated_at,'Record Version':1,
      'Supabase Portal Record':true,lines:linesByQuote.get(row.id) || []
    }));
    const invoiceRows=invoices.map(row=>({
      'Invoice ID':row.id,'Business ID':businessId,'Customer ID':row.customer_id,
      'Invoice Number':row.invoice_number,'Status':row.status,'Due Date':row.due_date || '',
      'Subtotal':number(row.total),'Tax':0,'Total':number(row.total),'Balance':number(row.balance_due),
      'Created Time':row.created_at,'Updated Time':row.updated_at,'Record Version':1,
      'Supabase Portal Record':true
    }));

    const threadMap=new Map();
    const portalMessageRows=messages.map(row=>{
      const threadId=`PORTAL-CUSTOMER-${row.customer_id}`;
      if(!threadMap.has(threadId))threadMap.set(threadId,{
        'Portal Thread ID':threadId,'Business ID':businessId,'Customer ID':row.customer_id,
        'Subject':'Customer portal conversation','Status':'Active','Created Time':row.created_at,
        'Updated Time':row.created_at,'Record Version':1,'Supabase Portal Record':true
      });
      return {
        'Portal Message ID':row.id,'Business ID':businessId,'Portal Thread ID':threadId,
        'Customer ID':row.customer_id,'Job ID':row.job_id || '','Body':row.body,
        'Direction':row.direction,'Status':row.status,'Created By':row.created_by,
        'Created Time':row.created_at,'Record Version':1,'Supabase Portal Record':true
      };
    });
    const documentRows=files.map(row=>({
      'Document ID':row.id,'Business ID':businessId,'Customer ID':row.customer_id,
      'Job ID':row.job_id || '','File Name':row.file_name,'Mime Type':'',
      'File Size':0,'Source Type':row.job_id?'Job':'Customer','Source ID':row.job_id || row.customer_id,
      'Access Classification':row.available_to_customer?'Customer Available':'Internal',
      'Storage Provider':'supabase','Storage Path':row.storage_path,'Status':row.status,
      'Created Time':row.created_at,'Updated Time':row.updated_at,'Record Version':1,
      'Supabase Portal Record':true
    }));

    const allCustomerRows=merge(customerRows,businessRecordCustomerRows,'Customer ID');
    snapshot.customers=merge(snapshot.customers,allCustomerRows,'Customer ID');
    if(text(snapshot?.business?.businessKey)==='northern-lakes'){
      snapshot.customers=(snapshot.customers || []).filter(row=>text(row['Customer ID'])!=='GENERIC-QUOTE-CUSTOMER');
    }
    snapshot.jobs=merge(snapshot.jobs,jobRows,'Job ID');
    snapshot.quotes=merge(snapshot.quotes,quoteRows,'Quote ID');
    snapshot.invoices=merge(snapshot.invoices,invoiceRows,'Invoice ID');
    snapshot.portalThreads=merge(snapshot.portalThreads,Array.from(threadMap.values()),'Portal Thread ID');
    snapshot.portalMessages=merge(snapshot.portalMessages,portalMessageRows,'Portal Message ID');
    snapshot.documents=merge(snapshot.documents,documentRows,'Document ID');
    snapshot.portalFoundationConnected=true;
    return snapshot;
  }

  Bridge.prototype.request=async function(action,args,timeout){
    const result=await previousRequest.call(this,action,args,timeout);
    if(action!=='fullStartupRefresh' && action!=='completionBootstrap')return result;
    const businessId=text(args && args.businessId || auth.getState().selectedBusinessId);
    return businessId?hydrate(result,businessId):result;
  };

  window.H38_SUPABASE_PORTAL_HYDRATION={enabled:true,readOnly:true,googleRecordsImported:false,businessRecordsHydrated:true};
})();
;

/* --- ./startup-fix.js --- */
'use strict';
const H38_STARTUP_BUILD='20260803-1700';
const H38_LOCAL_STARTUP_TIMEOUT=3000;
let h38StartupWatchdog=0;
state.canSwitchBusinesses=false;

function setBusinessSwitcherVisible(visible){
  const select=$('businessSelect'),button=$('loadBusinessButton');
  if(select){select.hidden=!visible;select.disabled=!visible;}
  if(button){button.hidden=!visible;button.disabled=!visible;}
}
function setFastBusinessId(businessId){
  state.businessId=businessId||'';
  try{if(state.businessId)localStorage.setItem('h38-selected-business',state.businessId);else localStorage.removeItem('h38-selected-business');}catch(error){}
}
function withStartupTimeout(promise,label,timeout=H38_LOCAL_STARTUP_TIMEOUT){
  return new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error(`${label} timed out.`)),timeout);Promise.resolve(promise).then(value=>{clearTimeout(timer);resolve(value);},error=>{clearTimeout(timer);reject(error);});});
}
function armStartupWatchdog(){
  clearTimeout(h38StartupWatchdog);
  h38StartupWatchdog=setTimeout(()=>{if(!state.snapshot)renderWelcome('unavailable');},12000);
}
async function retireLegacyOfflineShell(){
  try{
    if('serviceWorker' in navigator){const registrations=await navigator.serviceWorker.getRegistrations();await Promise.all(registrations.filter(registration=>registration.scope.includes('/commercial-app/')).map(registration=>registration.unregister()));}
    if('caches' in window){const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('h38-business-office-')).map(key=>caches.delete(key)));}
  }catch(error){console.warn(error.message||String(error));}
}
function secureOfficeUrl(){return `/open-business-office.html?officeBuild=${encodeURIComponent(H38_STARTUP_BUILD)}`;}
window.h38Authorize=()=>{location.assign(secureOfficeUrl());return true;};
function persistBusinessSelection(businessId){withStartupTimeout(put('meta',{id:'selectedBusiness',businessId}),'saving selected business').catch(error=>console.warn(error.message));}
function saveStartupSnapshot(snapshot,businessId){
  if(!snapshot||!snapshot.business||!snapshot.user)throw new Error('Secure startup returned an incomplete business pack.');
  const id=businessId||snapshot.business.businessId;snapshot.id=`business:${id}`;snapshot.cachedAt=now();setFastBusinessId(id);state.snapshot=snapshot;
  withStartupTimeout(Promise.all([put('snapshots',snapshot),put('meta',{id:'selectedBusiness',businessId:id})]),'caching startup snapshot',5000).catch(error=>console.warn(error.message));
  return snapshot;
}
function bindStartupControls(){
  const earlySignIn=$('earlySecureSignInButton'),earlyRetry=$('earlyRetryButton');
  if(earlySignIn)earlySignIn.onclick=event=>{event.preventDefault();window.h38Authorize();};
  if(earlyRetry)earlyRetry.onclick=()=>state.bridge?.connect();
}
async function hydrateLocalStartup(requestedBusinessId){
  try{const settings=await withStartupTimeout(get('meta','settings'),'loading local settings');if(settings)state.drivingMode=!!settings.drivingMode;}catch(error){console.warn(error.message);}
  // URL businessKey wins: ignore cached selection when the URL names a business.
  let urlBusinessKey='';
  try{urlBusinessKey=String(new URLSearchParams(location.search).get('businessKey')||'').trim();}catch(e){}
  if(requestedBusinessId)persistBusinessSelection(requestedBusinessId);
  else if(!urlBusinessKey){
    try{const selected=await withStartupTimeout(get('meta','selectedBusiness'),'loading saved business');const cachedBusinessId=selected?.businessId||'';if(cachedBusinessId&&!state.businessId)setFastBusinessId(cachedBusinessId);}catch(error){console.warn(error.message);}
  }
  try{
    if(!state.snapshot)await withStartupTimeout(loadCached(),'loading saved business pack',4000);
    if(state.snapshot){$('businessStatus').textContent=state.bridgeReady?`${state.snapshot.business.businessName} · secure gateway connected`:`${state.snapshot.business.businessName} · saved offline business pack`;openPage(state.page,false);}
  }catch(error){console.warn(error.message);}
  withStartupTimeout(updatePending(),'counting saved work',4000).catch(error=>console.warn(error.message));
  if(!state.snapshot&&!state.bridgeReady)renderWelcome('unavailable');
}
async function init(){
  setBusinessSwitcherVisible(false);retireLegacyOfflineShell();
  const query=new URLSearchParams(location.search);state.shell=SHELL_PAGES[query.get('shell')]?query.get('shell'):'office';$('shellLabel').textContent=SHELL_LABELS[state.shell];
  const requestedBusinessId=(query.get('businessId')||'').trim();let fastBusinessId=requestedBusinessId;
  // URL businessKey wins over any stale localStorage selection — never read the
  // cached business when the URL names one (prevents cross-tenant data leaks).
  const urlBusinessKey=(query.get('businessKey')||'').trim();
  if(!fastBusinessId&&!urlBusinessKey){try{fastBusinessId=localStorage.getItem('h38-selected-business')||'';}catch(error){}}
  setFastBusinessId(fastBusinessId);
  state.bridge=new H38Bridge($('bridgeFrame'),' ',handleBridgeStatus,handleStartupBootstrap,handleFullSnapshot,handleBridgeError);window.H38_ACTIVE_BRIDGE=state.bridge;
  bindGlobal();bindStartupControls();renderNav();network();if(state.snapshot)openPage(state.page,false);else renderWelcome('connecting');
  state.bridge.connect();addEventListener('online',network);addEventListener('offline',network);armStartupWatchdog();
  hydrateLocalStartup(requestedBusinessId).catch(error=>console.warn(error.message||String(error)));
}
function handleBridgeStatus(status){
  state.bridgeReady=['connected','bootstrapped'].includes(status)||!!state.bridge?.ready;
  if(status==='connected'){$('businessStatus').textContent='Secure gateway connected · opening Office…';return;}
  if(status==='bootstrapped'){clearTimeout(h38StartupWatchdog);return;}
  if(status==='auth-expired'){
    state.bridgeReady=false;$('businessStatus').textContent=state.snapshot?'Office open offline · secure session expired.':'Secure session expired.';
    if(!state.snapshot)renderWelcome('unavailable','Sign in again to reopen the secure Office.');else toast('Secure session expired. Your work remains saved on this device.',true);return;
  }
  if(status==='sign-in-required'){
    state.bridgeReady=false;$('businessStatus').textContent=state.snapshot?'Offline business pack · sign in to refresh.':'Sign in required.';
    if(!state.snapshot)renderWelcome('unavailable');return;
  }
}
async function handleStartupBootstrap(startup){
  try{
    const businesses=Array.isArray(startup?.businesses)?startup.businesses:[];if(!businesses.length)throw new Error('No active business is assigned to this account.');
    state.canSwitchBusinesses=startup.canSwitchBusinesses===true;setBusinessSwitcherVisible(state.canSwitchBusinesses);populateBusinessSelector(businesses);
    if(startup.selectedBusinessId)setFastBusinessId(startup.selectedBusinessId);
    if(startup.snapshot){
      saveStartupSnapshot(startup.snapshot,state.businessId);
      $('businessStatus').textContent=`${startup.snapshot.business.businessName} · ${startup.snapshot.user.roleName} · Office open · refreshing latest records…`;
      openPage(state.page,false);updatePending().catch(()=>{});
      state.bridge.request('fullStartupRefresh',{businessId:state.businessId},120000).then(snapshot=>handleFullSnapshot(snapshot,state.businessId)).catch(error=>handleBridgeError('refresh',error.message||String(error)));
      return;
    }
    if(state.canSwitchBusinesses){$('businessStatus').textContent='Choose a business to open.';renderWelcome('choose');return;}
    throw new Error('Your assigned business could not be selected.');
  }catch(error){handleBridgeError('startup',error.message||String(error));}
}
async function handleFullSnapshot(snapshot,businessId){
  try{
    const id=businessId||snapshot?.business?.businessId;if(!id||id!==state.businessId)return;
    saveStartupSnapshot(snapshot,id);$('businessStatus').textContent=`${snapshot.business.businessName} · ${snapshot.user.roleName} · latest records loaded ${new Date().toLocaleTimeString()}`;
    openPage(state.page,false);updatePending().catch(()=>{});sync(false).catch(()=>{});toast('Latest business records loaded.');
  }catch(error){handleBridgeError('refresh',error.message||String(error));}
}
function handleBridgeError(stage,message){
  const text=message||'Secure connection failed.';
  if(['refresh','request'].includes(stage)&&state.snapshot){$('businessStatus').textContent='Office open · showing saved records — refresh failed.';toast(text,true);return;}
  if(stage==='authorization'&&state.snapshot){state.bridgeReady=false;$('businessStatus').textContent='Office open offline · sign in to reconnect.';toast(text,true);return;}
  state.bridgeReady=false;$('businessStatus').textContent='Business Office connection failed.';toast(text,true);if(!state.snapshot)renderWelcome('error',text);
}
function populateBusinessSelector(businesses){
  const select=$('businessSelect');select.innerHTML='<option value="">Select business</option>'+businesses.map(b=>`<option value="${esc(b.businessId)}">${esc(b.businessName)}</option>`).join('');select.value=state.businessId||'';
}
function bindGlobal(){
  $('loadBusinessButton').onclick=()=>{if(!state.canSwitchBusinesses)return;const businessId=$('businessSelect').value;if(!businessId){toast('Choose a business first.',true);return;}setFastBusinessId(businessId);persistBusinessSelection(businessId);state.bridge.request('fullStartupRefresh',{businessId},120000).then(snapshot=>handleFullSnapshot(snapshot,businessId)).catch(error=>handleBridgeError('refresh',error.message));};
  $('syncButton').onclick=()=>state.bridgeReady?sync(true):window.h38Authorize();$('voiceButton').onclick=toggleVoice;
}
function renderWelcome(mode='connecting',detailOverride=''){
  if(state.snapshot)return;
  const unavailable=['unavailable','error'].includes(mode),choose=mode==='choose';
  const title=unavailable?'Open Business Office securely':choose?'Choose a business':'Opening Business Office…';
  const detail=detailOverride||(unavailable?'Sign in with Google in this tab. Highway 38 returns here through the secure gateway; no second window stays open.':choose?'Use the owner-only business selector above.':'Reading the secure gateway handoff.');
  const actions=choose?'':`<div class="welcome-actions"><button id="retryConnectionButton" class="primary" type="button">Open secure Office</button></div>`;
  $('mainContent').innerHTML=`<section class="welcome"><h1>${esc(title)}</h1><p>${esc(detail)}</p>${actions}<div class="notice">Nothing is sent, paid, purchased, approved, or published automatically.</div></section>`;
  if(!choose)$('retryConnectionButton').onclick=window.h38Authorize;
}
async function loadBusiness(businessId,quiet=false){
  if(!businessId)return false;setFastBusinessId(businessId);persistBusinessSelection(businessId);
  try{const snapshot=await state.bridge.request('fullStartupRefresh',{businessId},120000);await handleFullSnapshot(snapshot,businessId);if(!quiet)toast('Business refreshed.');return true;}
  catch(error){withStartupTimeout(loadCached(),'loading saved business',4000).then(()=>{if(state.snapshot){openPage(state.page,false);if(!quiet)toast(`${error.message} Using the most recent offline business pack.`,true);}}).catch(()=>handleBridgeError('refresh',error.message||String(error)));return false;}
}
;

/* --- ./supabase-startup.js --- */
'use strict';

const H38_SUPABASE_STARTUP_BUILD='20260918-post-login-operational-authority-1';
const h38LegacyInit=init;
const h38LegacySetFastBusinessId=setFastBusinessId;
const h38LegacyPersistBusinessSelection=persistBusinessSelection;
const h38LegacySaveStartupSnapshot=saveStartupSnapshot;
const h38LegacyHydrateLocalStartup=hydrateLocalStartup;
const h38LegacyHandleBridgeStatus=handleBridgeStatus;
const h38LegacyHandleStartupBootstrap=handleStartupBootstrap;
const h38LegacyHandleFullSnapshot=handleFullSnapshot;
const h38LegacyHandleBridgeError=handleBridgeError;
const h38LegacyRenderWelcome=renderWelcome;
const h38LegacyLoadBusiness=loadBusiness;
const h38LegacyBindGlobal=bindGlobal;

function h38SupabaseAuthEnabled(){return window.H38_SUPABASE_AUTH?.enabled===true;}
function h38AuthUserId(){return window.H38DB?.getUserScope?.()||'';}
function h38SnapshotAuthoritative(snapshot){
  return !!snapshot?.user&&!!snapshot?.business&&snapshot.fullRefreshPending!==true&&snapshot.startupMode!=='SUPABASE_AUTH_FOUNDATION';
}
function h38MarkAuthoritativeStartupReady(source){
  if(!h38SnapshotAuthoritative(state?.snapshot))return false;
  const root=document?.documentElement;
  if(root){
    root.dataset.h38AuthoritativeStartup='ready';
    root.dataset.h38AuthoritativeStartupSource=String(source||'snapshot');
  }
  window.dispatchEvent?.(new CustomEvent('h38:authoritative-startup-ready',{detail:{source:String(source||'snapshot'),build:H38_SUPABASE_STARTUP_BUILD}}));
  return true;
}
function h38ClearAuthoritativeStartupReady(){
  const root=document?.documentElement;
  if(!root)return;
  delete root.dataset.h38AuthoritativeStartup;
  delete root.dataset.h38AuthoritativeStartupSource;
}
function h38ScopedBusinessStorageKey(){const userId=h38AuthUserId();return userId?`h38-selected-business:${userId}`:'';}
function h38RegisterOfficeServiceWorker(){
  if(!('serviceWorker' in navigator))return;
  navigator.serviceWorker.register('./service-worker.js',{updateViaCache:'none'}).catch(error=>console.warn('Business Office service worker:',error.message||String(error)));
}
function h38SetAuthorizedChrome(authorized){
  const allowed=authorized===true&&!!state.snapshot;
  document.body?.classList.toggle('h38-auth-locked',!allowed);
  document.body?.classList.toggle('h38-auth-authorized',allowed);
  const nav=$('mainNav');
  if(nav&&!allowed)nav.innerHTML='';
  ['globalAiButton','voiceButton'].forEach(id=>{const node=$(id);if(node)node.disabled=!allowed;});
  const sync=$('syncButton');if(sync)sync.disabled=!allowed&&!state.bridge;
}

setFastBusinessId=function(businessId){
  if(!h38SupabaseAuthEnabled())return h38LegacySetFastBusinessId(businessId);
  state.businessId=String(businessId||'');
  const key=h38ScopedBusinessStorageKey();
  if(!key)return;
  try{if(state.businessId)localStorage.setItem(key,state.businessId);else localStorage.removeItem(key);}catch(error){}
};

persistBusinessSelection=function(businessId){
  if(!h38SupabaseAuthEnabled())return h38LegacyPersistBusinessSelection(businessId);
  if(!h38AuthUserId())return;
  withStartupTimeout(put('meta',{id:'selectedBusiness',businessId:String(businessId||'')}),'saving selected business').catch(error=>console.warn(error.message));
};

saveStartupSnapshot=function(snapshot,businessId){
  if(!h38SupabaseAuthEnabled())return h38LegacySaveStartupSnapshot(snapshot,businessId);
  const userId=h38AuthUserId();
  if(!userId||!snapshot?.business||!snapshot?.user)throw new Error('Secure startup returned an incomplete Auth-scoped business pack.');
  if(!h38SnapshotAuthoritative(snapshot))throw new Error('Secure startup is still an Auth foundation snapshot and cannot paint business records.');
  if(snapshot.user.userId!==userId||snapshot.authUserId!==userId)throw new Error('Startup snapshot belongs to a different authenticated user.');
  const id=String(businessId||snapshot.business.businessId||'');
  if(!id||snapshot.business.businessId!==id||snapshot.authorizationStatus!=='active')throw new Error('Startup snapshot does not contain an active selected business.');
  snapshot.id=`business:${id}`;
  snapshot.cachedAt=now();
  snapshot.authorizationCheckedAt=snapshot.authorizationCheckedAt||snapshot.cachedAt;
  setFastBusinessId(id);
  state.snapshot=snapshot;
  window.dispatchEvent(new CustomEvent('h38:business-snapshot-updated'));
  h38SetAuthorizedChrome(true);
  withStartupTimeout(Promise.all([
    put('snapshots',snapshot),
    put('meta',{id:'selectedBusiness',businessId:id})
  ]),'caching user-scoped startup snapshot',5000).catch(error=>console.warn(error.message));
  return snapshot;
};

hydrateLocalStartup=async function(options={}){
  if(!h38SupabaseAuthEnabled())return h38LegacyHydrateLocalStartup.apply(this,arguments);
  const allowOnline=options?.allowOnline===true;
  if(!h38AuthUserId()||(navigator.onLine&&!allowOnline))return false;
  try{const settings=await withStartupTimeout(get('meta','settings'),'loading local settings');if(settings)state.drivingMode=!!settings.drivingMode;}catch(error){console.warn(error.message);}
  // URL businessKey is authoritative: never adopt a cached business selection
  // when the URL names a business — the auth bridge resolves it fresh.
  let urlBusinessKey='';
  try{urlBusinessKey=String(new URLSearchParams(location.search).get('businessKey')||'').trim();}catch(e){}
  if(!urlBusinessKey){
    try{
      const selected=await withStartupTimeout(get('meta','selectedBusiness'),'loading user-scoped business');
      setFastBusinessId(selected?.businessId||'');
    }catch(error){console.warn(error.message);}
  }
  // Online startup may use cached preferences/selection, but never paints cached business records.
  // Keep the startup cover up until the secure gateway returns the authoritative snapshot.
  if(navigator.onLine&&allowOnline)return false;
  try{
    if(!state.snapshot)await withStartupTimeout(loadCached({allowOnline}),'loading verified business pack',4000);
    if(state.snapshot){
      h38SetAuthorizedChrome(true);
      $('businessStatus').textContent=`${state.snapshot.business.businessName} · Offline · verified device cache`;
      openPage(state.page,false);
      await updatePending().catch(()=>{});
      h38MarkAuthoritativeStartupReady('offline-cache');
      return true;
    }
  }catch(error){console.warn(error.message);}
  if(navigator.onLine)return false;
  state.snapshot=null;
  h38SetAuthorizedChrome(false);
  renderWelcome('unavailable','No recent user-scoped authorization is available for offline startup. Reconnect to verify this membership.');
  return false;
};

window.h38Authorize=()=>{
  if(h38SupabaseAuthEnabled()&&state.bridge?.authorize)return state.bridge.authorize();
  location.assign(secureOfficeUrl());
  return true;
};

bindGlobal=function(){
  if(!h38SupabaseAuthEnabled())return h38LegacyBindGlobal();
  $('loadBusinessButton').onclick=()=>{
    if(!state.canSwitchBusinesses)return;
    const businessId=$('businessSelect').value;
    if(!businessId){toast('Choose a business first.',true);return;}
    loadBusiness(businessId,false);
  };
  $('syncButton').onclick=()=>state.bridgeReady&&state.businessId?loadBusiness(state.businessId,false):window.h38Authorize();
  $('voiceButton').onclick=toggleVoice;
  $('globalAiButton').onclick=openGlobalAi;
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&navigator.onLine&&!state.bridgeReady)state.bridge?.connect();});
};

init=async function(){
  if(!h38SupabaseAuthEnabled())return h38LegacyInit();
  setBusinessSwitcherVisible(false);
  h38RegisterOfficeServiceWorker();
  const query=new URLSearchParams(location.search);
  state.shell=SHELL_PAGES[query.get('shell')]?query.get('shell'):'office';
  $('shellLabel').textContent=SHELL_LABELS[state.shell];
  state.requestedBusinessId=String(query.get('businessId')||'').trim();
  state.businessId='';
  state.snapshot=null;
  h38ClearAuthoritativeStartupReady();
  state.bridge=new H38Bridge($('bridgeFrame'),' ',handleBridgeStatus,handleStartupBootstrap,handleFullSnapshot,handleBridgeError);
  window.H38_ACTIVE_BRIDGE=state.bridge;
  bindGlobal();
  bindStartupControls();
  h38SetAuthorizedChrome(false);
  network();
  renderWelcome('connecting');
  state.bridge.connect();
  addEventListener('online',()=>{network();state.bridge?.connect();});
  addEventListener('offline',()=>{network();hydrateLocalStartup().catch(()=>{});});
  addEventListener('h38:auth-cleared',()=>h38SetAuthorizedChrome(false));
  armStartupWatchdog();
};

handleBridgeStatus=function(status){
  if(!h38SupabaseAuthEnabled())return h38LegacyHandleBridgeStatus(status);
  state.bridgeReady=['connected','bootstrapped'].includes(status)&&!!state.bridge?.ready;
  if(status==='connected'){
    $('businessStatus').textContent='Secure session found · opening Office…';
    hydrateLocalStartup({allowOnline:true}).catch(error=>console.warn(error.message||String(error)));
    return;
  }
  if(status==='bootstrapped'){clearTimeout(h38StartupWatchdog);return;}
  if(status==='offline-authenticated'){
    state.bridgeReady=false;
    $('businessStatus').textContent='Offline · opening verified device cache…';
    hydrateLocalStartup().catch(error=>renderWelcome('unavailable',error.message));
    return;
  }
  if(['membership-suspended','membership-revoked','membership-invited','no-membership'].includes(status)){
    clearTimeout(h38StartupWatchdog);
    state.bridgeReady=false;
    state.snapshot=null;
    state.businessId='';
    state.canSwitchBusinesses=false;
    h38SetAuthorizedChrome(false);
    setBusinessSwitcherVisible(false);
    $('businessStatus').textContent={
      'membership-suspended':'Membership suspended',
      'membership-revoked':'Membership revoked',
      'membership-invited':'Membership pending',
      'no-membership':'No active membership'
    }[status];
    renderWelcome(status);
    return;
  }
  if(status==='auth-expired'){
    state.bridgeReady=false;state.snapshot=null;state.businessId='';h38SetAuthorizedChrome(false);setBusinessSwitcherVisible(false);
    $('businessStatus').textContent='Supabase Auth session expired.';renderWelcome('auth-expired');return;
  }
  if(status==='sign-in-required'){
    state.bridgeReady=false;state.snapshot=null;state.businessId='';h38SetAuthorizedChrome(false);setBusinessSwitcherVisible(false);
    $('businessStatus').textContent='Supabase Auth sign-in required.';renderWelcome('unavailable');return;
  }
};

handleStartupBootstrap=async function(startup){
  if(!h38SupabaseAuthEnabled())return h38LegacyHandleStartupBootstrap(startup);
  try{
    const userId=h38AuthUserId();
    if(!userId||startup?.user?.id!==userId)throw new Error('Authenticated startup user does not match the user-scoped cache.');
    const businesses=Array.isArray(startup?.businesses)?startup.businesses:[];
    if(!businesses.length)throw new Error('No active business is assigned to this account.');
    state.authUserId=userId;
    state.canSwitchBusinesses=startup.canSwitchBusinesses===true;
    setBusinessSwitcherVisible(state.canSwitchBusinesses);
    populateBusinessSelector(businesses);
    if(startup.selectedBusinessId)setFastBusinessId(startup.selectedBusinessId);
    if(startup.snapshot&&h38SnapshotAuthoritative(startup.snapshot)){
      saveStartupSnapshot(startup.snapshot,state.businessId);
      $('businessStatus').textContent=`${startup.snapshot.business.businessName} · ${startup.snapshot.user.roleName} · Office online`;
      openPage(state.page,false);
      await updatePending().catch(()=>{});
      h38MarkAuthoritativeStartupReady('bootstrap-snapshot');
      return;
    }
    h38ClearAuthoritativeStartupReady();
    h38SetAuthorizedChrome(false);
    if(startup.snapshot)$('businessStatus').textContent='Secure membership verified · loading complete business data…';
    const authorizedIds=new Set(businesses.map(b=>String(b.businessId||'')));
    let preferredId=String(startup.selectedBusinessId||state.requestedBusinessId||state.businessId||'').trim();
    if(!authorizedIds.has(preferredId))preferredId='';
    if(!preferredId){
      const highway38=businesses.find(b=>/highway\s*38/i.test(String(b.businessName||b.displayName||'')));
      preferredId=String(highway38?.businessId||businesses[0]?.businessId||'').trim();
    }
    if(preferredId&&authorizedIds.has(preferredId)){
      $('businessStatus').textContent='Opening authorized business…';
      await loadBusiness(preferredId,true);
      return;
    }
    throw new Error('The active business could not be selected.');
  }catch(error){handleBridgeError('authorization',error.message||String(error));}
};

handleFullSnapshot=async function(snapshot,businessId){
  if(!h38SupabaseAuthEnabled())return h38LegacyHandleFullSnapshot(snapshot,businessId);
  try{
    if(!h38SnapshotAuthoritative(snapshot))throw new Error('Operational business hydration did not complete; refusing to paint an Auth-only snapshot.');
    const id=String(businessId||snapshot?.business?.businessId||'');
    if(!id||id!==state.businessId)return;
    const firstAuthoritativeOpen=!state.snapshot;
    saveStartupSnapshot(snapshot,id);
    $('businessStatus').textContent=`${snapshot.business.businessName} · ${snapshot.user.roleName} · Office online`;
    openPage(state.page,false);
    await updatePending().catch(()=>{});
    h38MarkAuthoritativeStartupReady('full-snapshot');
    // Polish (2026-10-11): removed noisy "Office refreshed." toast on every
    // background data refresh — users don't need to know about syncs, and the
    // toast was blocking buttons. Only errors get toasts now.
  }catch(error){handleBridgeError('refresh',error.message||String(error));}
};

handleBridgeError=function(stage,message){
  if(!h38SupabaseAuthEnabled())return h38LegacyHandleBridgeError(stage,message);
  const text=String(message||'Secure Supabase connection failed.');
  state.bridgeReady=false;
  if(!navigator.onLine){hydrateLocalStartup().catch(()=>renderWelcome('unavailable',text));return;}
  if(['authorization','refresh','request'].includes(stage)&&state.snapshot){
    $('businessStatus').textContent='Office open · showing saved records — refresh failed.';
    toast(text,true);
    return;
  }
  state.snapshot=null;
  state.businessId='';
  h38ClearAuthoritativeStartupReady();
  h38SetAuthorizedChrome(false);
  setBusinessSwitcherVisible(false);
  $('businessStatus').textContent='Supabase Auth verification failed.';
  toast(text,true);
  renderWelcome('error',text);
};

function h38BrandSplashNorthernRequested(){try{return String(new URLSearchParams(location.search).get('businessKey')||'').toLowerCase()==='northern-lakes';}catch(_){return false;}}
function h38BrandSplashHtml(status,notice){
  return '<section class="welcome welcome--brand"><img class="welcome-brand-logo" src="../assets/highway38-logo-256.webp?v=20261013-exact-ac2498e6" alt="Highway 38 Solutions" width="118" height="118"><h1>Business Office</h1><p class="welcome-brand-tagline">Replace your software. <strong>Get an office worker.</strong></p><p class="welcome-brand-status">'+status+'</p>'+(notice?'<div class="notice">'+notice+'</div>':'')+'</section>';
}

renderWelcome=function(mode='connecting',detailOverride=''){
  if(!h38SupabaseAuthEnabled())return h38LegacyRenderWelcome(mode,detailOverride);
  if(state.snapshot)return;
  h38SetAuthorizedChrome(false);
  if(['unavailable','error','auth-expired','membership-suspended','membership-revoked','membership-invited','no-membership'].includes(mode)){
    const mapped=mode==='unavailable'||mode==='error'?'signin':mode;
    window.H38_SUPABASE_AUTH.render(mapped,detailOverride);
    return;
  }
  if(mode==='choose'){
    $('mainContent').innerHTML=h38BrandSplashNorthernRequested()?'<section class="welcome"><h1>Business Office</h1><p>Resolving your authorized business.</p></section>':h38BrandSplashHtml('Resolving your authorized business.','');
    return;
  }
  $('mainContent').innerHTML=h38BrandSplashNorthernRequested()?'<section class="welcome"><h1>Business Office</h1><p>Opening your current verified business records.</p><div class="notice">Nothing is sent, paid, purchased, approved, published, or executed automatically.</div></section>':h38BrandSplashHtml('Opening your current verified business records.','Nothing is sent, paid, purchased, approved, published, or executed automatically.');
};

loadBusiness=async function(businessId,quiet=false){
  if(!h38SupabaseAuthEnabled())return h38LegacyLoadBusiness(businessId,quiet);
  if(!businessId)return false;
  const switching=!!state.snapshot && state.snapshot.business?.businessId!==businessId;
  if(switching){
    state.snapshot=null;
    state.quote=null;
    h38ClearAuthoritativeStartupReady();
    h38SetAuthorizedChrome(false);
    window.dispatchEvent(new CustomEvent('h38:business-snapshot-updated'));
    renderWelcome('connecting');
  }
  setFastBusinessId(businessId);
  persistBusinessSelection(businessId);
  try{
    const snapshot=await state.bridge.request('fullStartupRefresh',{businessId},30000);
    await handleFullSnapshot(snapshot,businessId);
    if(!quiet)toast('Business membership verified.');
    return true;
  }catch(error){
    handleBridgeError('refresh',error.message||String(error));
    return false;
  }
};

window.H38_OFFICE_STARTUP=Object.freeze({
  enabled:true,
  build:H38_SUPABASE_STARTUP_BUILD,
  onlineWarmOpen:true,
  onlineCachePaint:false,
  authoritativeOnlineFirstPaint:true,
  initialRefreshToastSuppressed:true,
  offlineVerifiedCache:true,
  serviceWorkerEnabled:true,
  membershipRevalidation:true,
  deniedMembershipClosesCache:true,
  authoritativeStartupReadyEvent:true,
  nativeRevealWaitsForAuthoritativeSnapshot:true,
  authFoundationNeverPaints:true,
  operationalSnapshotRequired:true,
  postLoginHydrationSinglePaint:true
});
;

/* --- ./payroll-workflow.js --- */
/* H38 Payroll Workflow — tax estimates, pay stubs, exports.
 * All tax figures are ESTIMATES for planning only. The Office never files
 * returns or moves funds. Consult an accountant or payroll service for filings.
 */

'use strict';

/* ---------- Download helper ---------- */
function h38DownloadFile(filename, content, mimeType){
  const blob=new Blob([content],{type:mimeType||'text/plain'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;document.body.appendChild(a);a.click();
  setTimeout(()=>{document.body.removeChild(a);URL.revokeObjectURL(url);},500);
}

/* ---------- Tax tables (2026 estimates) ---------- */
const H38_TAX = {
  // Standard deduction (annual, estimate)
  standardDeduction:{single:15000, married:30000, head:22500},
  // Value of one classic W-4 allowance (annual)
  allowanceValue: 4400,
  // Federal brackets 2026 estimate [top, rate] — single filer baseline
  federalBrackets:[
    [11925,0.10],[48475,0.12],[103350,0.22],[197300,0.24],[250525,0.32],[626350,0.35],[Infinity,0.37]
  ],
  federalBracketsMarried:[
    [23850,0.10],[96950,0.12],[206700,0.22],[394600,0.24],[501050,0.32],[751600,0.35],[Infinity,0.37]
  ],
  // FICA
  ssRate:0.062, ssWageBase:184500,
  medicareRate:0.0145, medicareExtraRate:0.009, medicareExtraThreshold:200000,
  // Minnesota 2026 estimate — single brackets [top, rate]
  mnBrackets:[
    [31690,0.0535],[104090,0.068],[193240,0.0785],[Infinity,0.0985]
  ],
  // Employer
  futaRate:0.006, futaWageBase:7000,
  sutaRate:0.02, sutaWageBase:43000 // MN 2026 approx; configurable per business
};

function h38BracketTax(taxable, brackets){
  let tax=0, prev=0;
  for(const [top,rate] of brackets){
    if(taxable<=prev)break;
    tax+=(Math.min(taxable,top)-prev)*rate;
    prev=top;
  }
  return tax;
}

/* Estimate federal withholding for one pay period.
 * method: annualize gross -> subtract standard deduction + allowances -> bracket -> divide by periods */
function h38EstimateFederal(grossPay, employee, periodsPerYear){
  const filing=String(v(employee,'Filing Status')||'Single').toLowerCase();
  const married=filing.includes('married');
  const annual=grossPay*periodsPerYear;
  const deduction=(married?H38_TAX.standardDeduction.married:H38_TAX.standardDeduction.single)
    + num(v(employee,'Withholding Allowances'))*H38_TAX.allowanceValue;
  const taxable=Math.max(0, annual-deduction);
  const brackets=married?H38_TAX.federalBracketsMarried:H38_TAX.federalBrackets;
  const annualTax=h38BracketTax(taxable,brackets);
  return Math.max(0, annualTax/periodsPerYear + num(v(employee,'Extra Withholding')));
}

function h38EstimateFICA(grossPay, ytdGross){
  const ssTaxable=Math.max(0, Math.min(grossPay, H38_TAX.ssWageBase-Math.max(0,ytdGross)));
  const ss=ssTaxable*H38_TAX.ssRate;
  const medBase=grossPay*H38_TAX.medicareRate;
  const extraBase=Math.max(0, (ytdGross+grossPay)-H38_TAX.medicareExtraThreshold);
  const extraAlready=Math.max(0, ytdGross-H38_TAX.medicareExtraThreshold);
  const medExtra=Math.max(0,extraBase-extraAlready)*H38_TAX.medicareExtraRate;
  return {ss:Math.round(ss*100)/100, medicare:Math.round((medBase+medExtra)*100)/100};
}

function h38EstimateMNState(grossPay, employee, periodsPerYear){
  const annual=grossPay*periodsPerYear;
  const deduction=H38_TAX.standardDeduction.single
    + num(v(employee,'Withholding Allowances'))*H38_TAX.allowanceValue;
  const taxable=Math.max(0, annual-deduction);
  const annualTax=h38BracketTax(taxable,H38_TAX.mnBrackets);
  return Math.max(0, annualTax/periodsPerYear);
}

function h38PayFrequencyPeriods(freq){
  const f=String(freq||'Biweekly').toLowerCase();
  if(f.includes('week')&&!f.includes('bi'))return 52;
  if(f.includes('biweek'))return 26;
  if(f.includes('semimonth'))return 24;
  if(f.includes('month'))return 12;
  return 26;
}

/* Full per-employee payroll calculation. Returns a line object. */
function h38CalculatePaycheck(employee, regularHours, overtimeHours, ytd){
  const rate=num(v(employee,'Hourly Rate'));
  const salary=String(v(employee,'Pay Type')).toLowerCase()==='salary'?num(v(employee,'Salary Rate')):0;
  const otMult=num(v(employee,'Overtime Multiplier'))||1.5;
  const regularPay=Math.round(regularHours*rate*100)/100;
  const overtimePay=Math.round(overtimeHours*rate*otMult*100)/100;
  const grossPay=Math.round((regularPay+overtimePay+salary)*100)/100;
  const periods=h38PayFrequencyPeriods(v(employee,'Pay Frequency'));
  const ytdGross=num(ytd&&ytd.gross)||0;

  const federal=Math.round(h38EstimateFederal(grossPay,employee,periods)*100)/100;
  const fica=h38EstimateFICA(grossPay,ytdGross);
  const state=Math.round(h38EstimateMNState(grossPay,employee,periods)*100)/100;
  const totalDeductions=Math.round((federal+fica.ss+fica.medicare+state)*100)/100;
  const netPay=Math.round((grossPay-totalDeductions)*100)/100;

  // Employer cost
  const empSS=Math.round(Math.min(grossPay,Math.max(0,H38_TAX.ssWageBase-ytdGross))*H38_TAX.ssRate*100)/100;
  const empMed=Math.round(grossPay*H38_TAX.medicareRate*100)/100;
  const futaTaxable=Math.max(0,Math.min(grossPay,H38_TAX.futaWageBase-ytdGross));
  const futa=Math.round(futaTaxable*H38_TAX.futaRate*100)/100;
  const sutaTaxable=Math.max(0,Math.min(grossPay,H38_TAX.sutaWageBase-ytdGross));
  const suta=Math.round(sutaTaxable*H38_TAX.sutaRate*100)/100;
  const employerTax=Math.round((empSS+empMed+futa+suta)*100)/100;
  const employerCost=Math.round((grossPay+employerTax)*100)/100;

  return {
    regularHours:Math.round(regularHours*100)/100, overtimeHours:Math.round(overtimeHours*100)/100,
    hourlyRate:rate, regularPay, overtimePay, salaryPay:Math.round(salary*100)/100,
    grossPay, federalWithholding:federal, socialSecurity:fica.ss, medicare:fica.medicare,
    stateWithholding:state, totalDeductions, netPay,
    employerSS:empSS, employerMedicare:empMed, futa, suta,
    employerTax, employerCost,
    ytdGross:ytdGross+grossPay,
    ytdFederal:Math.round(((ytd&&ytd.federal)||0)+federal*100)/100,
    ytdSS:Math.round(((ytd&&ytd.ss)||0)+fica.ss*100)/100,
    ytdMedicare:Math.round(((ytd&&ytd.medicare)||0)+fica.medicare*100)/100,
    ytdState:Math.round(((ytd&&ytd.state)||0)+state*100)/100,
    ytdNet:Math.round(((ytd&&ytd.net)||0)+netPay*100)/100
  };
}

/* Group time entries by ISO week (Mon-Sun) for overtime calc */
function h38WeekKey(dateStr){
  const d=new Date(String(dateStr).slice(0,10)+'T12:00:00');
  const day=(d.getDay()+6)%7; // Monday=0
  d.setDate(d.getDate()-day);
  return d.toISOString().slice(0,10);
}

/* ---------- Pay stub HTML (print-friendly) ---------- */
function h38PayStubHTML(business, employee, period, line){
  const empName=esc(v(employee,'Display Name')||'Employee');
  const bizName=esc(v(business,'businessName','name','Name')||'Highway 38 Business Office');
  const periodLabel=`${esc(dateOnly(v(period,'Period Start')))} – ${esc(dateOnly(v(period,'Period End')))}`;
  const row=(label,cur,ytd)=>`<tr><td>${label}</td><td class="r">${money(cur)}</td><td class="r">${money(ytd)}</td></tr>`;
  return `<div class="paystub">
    <div class="paystub-head"><div><h2>${bizName}</h2><p class="muted">Pay Stub — ESTIMATE. Not an official tax document.</p></div>
    <div class="r"><strong>Pay Date</strong><br>${esc(dateOnly(v(period,'Pay Date')))}</div></div>
    <div class="paystub-meta"><div><strong>Employee:</strong> ${empName}<br><strong>Filing status:</strong> ${esc(v(employee,'Filing Status')||'Single')}</div>
    <div><strong>Pay period:</strong> ${periodLabel}<br><strong>Pay type:</strong> ${esc(v(employee,'Pay Type')||'Hourly')}</div></div>
    <table class="paystub-table"><thead><tr><th>Earnings</th><th class="r">Current</th><th class="r">YTD</th></tr></thead><tbody>
    ${row(`Regular (${num(v(line,'Regular Hours')).toFixed(2)} hrs @ ${money(v(line,'Hourly Rate'))})`,v(line,'Regular Pay'),'') }
    ${num(v(line,'Overtime Hours'))>0?row(`Overtime (${num(v(line,'Overtime Hours')).toFixed(2)} hrs)`,v(line,'Overtime Pay'),'') :''}
    ${num(v(line,'Salary Pay'))>0?row('Salary',v(line,'Salary Pay'),'') :''}
    <tr class="total"><td><strong>Gross Pay</strong></td><td class="r"><strong>${money(v(line,'Gross Pay'))}</strong></td><td class="r"><strong>${money(v(line,'YTD Gross'))}</strong></td></tr>
    </tbody></table>
    <table class="paystub-table"><thead><tr><th>Deductions (estimated)</th><th class="r">Current</th><th class="r">YTD</th></tr></thead><tbody>
    ${row('Federal income tax',v(line,'Federal Withholding'),v(line,'YTD Federal'))}
    ${row('Social Security (6.2%)',v(line,'Social Security'),v(line,'YTD SS'))}
    ${row('Medicare (1.45%)',v(line,'Medicare'),v(line,'YTD Medicare'))}
    ${row('MN state tax',v(line,'State Withholding'),v(line,'YTD State'))}
    <tr class="total"><td><strong>Total Deductions</strong></td><td class="r"><strong>${money(v(line,'Total Deductions'))}</strong></td><td class="r"></td></tr>
    </tbody></table>
    <div class="paystub-net"><span><strong>Net Pay</strong></span><span><strong>${money(v(line,'Net Pay'))}</strong></span></div>
    <p class="muted small paystub-disc">Tax figures are estimates for planning only and are not a substitute for a payroll tax service. Consult your accountant before filing.</p>
  </div>`;
}

/* ---------- Amount in words (check face) ---------- */
function h38AmountToWords(amount){
  const ones=['Zero','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  const tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  const scales=['','Thousand','Million','Billion'];
  const totalCents=Math.round(Math.abs(num(amount))*100);
  let dollars=Math.floor(totalCents/100);
  const centPart=totalCents%100;
  function threeDigits(n){
    const parts=[];
    const hundreds=Math.floor(n/100), rest=n%100;
    if(hundreds)parts.push(ones[hundreds]+' Hundred');
    if(rest>=20){parts.push(tens[Math.floor(rest/10)]+(rest%10?' '+ones[rest%10]:''));}
    else if(rest>0){parts.push(ones[rest]);}
    return parts.join(' ');
  }
  let words='';
  if(dollars===0)words='Zero';
  else{
    const chunks=[];
    let d=dollars,scale=0;
    while(d>0){chunks.push({n:d%1000,scale});d=Math.floor(d/1000);scale++;}
    words=chunks.reverse().map(c=>c.n?threeDigits(c.n)+(scales[c.scale]?' '+scales[c.scale]:''):'').filter(Boolean).join(' ');
  }
  return `${words} and ${String(centPart).padStart(2,'0')}/100 Dollars`;
}

/* ---------- Paycheck sheet: check face (for bank-supplied check-on-top
 * stock) + earnings stub below. The Office prints ONLY the variable fields.
 * The MICR line, bank name, routing and account numbers are pre-printed on
 * the business's bank stock — the Office never prints them. ---------- */
function h38PaycheckSheetHTML(business, employee, period, line, check){
  const empName=esc(v(employee,'Display Name')||v(check,'Payee Name')||'Employee');
  const payDate=esc(dateOnly(v(period,'Pay Date')||v(check,'Check Date')));
  const amount=num(v(line,'Net Pay'));
  const amountFig='$'+amount.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  const amountWords=esc(h38AmountToWords(amount))+' ****';
  const memo=esc(`Payroll ${dateOnly(v(period,'Period Start'))} – ${dateOnly(v(period,'Period End'))}`);
  const ox=Number(v(check,'Offset X Mm'))||0, oy=Number(v(check,'Offset Y Mm'))||0;
  const stub=h38PayStubHTML(business,employee,period,line);
  return `<section class="paycheck-sheet">
    <div class="paycheck-face"><div class="paycheck-cal" style="transform:translate(${ox}mm,${oy}mm)">
      <div class="paycheck-date"><span class="paycheck-flabel">Date</span> ${payDate}</div>
      <div class="paycheck-payee">${empName}</div>
      <div class="paycheck-amount"><strong>${amountFig}</strong></div>
      <div class="paycheck-words">${amountWords}</div>
      <div class="paycheck-memo"><span class="paycheck-flabel">Memo</span> ${memo}</div>
      <div class="paycheck-sig"><div class="paycheck-sigline"></div><span class="paycheck-flabel">Authorized signature — sign by hand</span></div>
    </div></div>
    <div class="paycheck-stubhead"><span><strong>Pay stub</strong> · Check #${esc(v(check,'Check Number'))} · Pay date ${payDate}</span><span>Keep for your records</span></div>
    ${stub}
  </section>`;
}

/* ---------- CSV export (for bank / accountant) ---------- */
function h38PayrollCSV(period, lines, employees){
  const head='Employee,Employee ID,Regular Hours,Overtime Hours,Gross Pay,Federal WH,Social Security,Medicare,State WH,Total Deductions,Net Pay,Pay Date';
  const rows=lines.map(line=>{
    const emp=employees.find(e=>rowId(e,'Employee ID')===v(line,'Employee ID'));
    const name=(v(emp,'Display Name')||v(line,'Employee ID')||'').replace(/,/g,' ');
    return [name,v(line,'Employee ID'),v(line,'Regular Hours'),v(line,'Overtime Hours'),v(line,'Gross Pay'),v(line,'Federal Withholding'),v(line,'Social Security'),v(line,'Medicare'),v(line,'State Withholding'),v(line,'Total Deductions'),v(line,'Net Pay'),v(period,'Pay Date')].join(',');
  });
  return head+'\n'+rows.join('\n');
}

/* ---------- NACHA export (PPD direct deposit) ---------- */
function h38Pad(str,len,padChar,left){
  str=String(str==null?'':str).slice(0,len);
  while(str.length<len)str=left?padChar+str:str+padChar;
  return str;
}
function h38NachaDate(dateStr){
  const d=dateStr?String(dateStr).slice(0,10):new Date().toISOString().slice(0,10);
  return d.replace(/-/g,'').slice(2); // YYMMDD
}
/* Generate a NACHA PPD file for direct deposit credits.
 * employee bank fields: 'Bank Routing', 'Bank Account', 'Account Type' (checking/savings) */
function h38PayrollNACHA(business, period, lines, employees){
  const L=[];
  const bizName=h38Pad(v(business,'businessName','name','Name')||'H38 Business',16,' ',false).toUpperCase();
  const bizName23=h38Pad(v(business,'businessName','name','Name')||'H38 Business',23,' ',false).toUpperCase();
  const bizId=h38Pad(String(v(business,'ein','EIN')||'123456789').replace(/\D/g,''),9,'0',true);
  const effDate=h38NachaDate(v(period,'Pay Date'));
  const nowD=new Date();
  const yy=String(nowD.getFullYear()).slice(2);
  const fileDate=yy+h38Pad(nowD.getMonth()+1,2,'0',true)+h38Pad(nowD.getDate(),2,'0',true);
  const fileTime=h38Pad(nowD.getHours(),2,'0',true)+h38Pad(nowD.getMinutes(),2,'0',true);
  const destDfi='121042882'; // placeholder — replace with bank's routing
  const originDfi=h38Pad(destDfi.slice(0,8),8,'0',true);
  // File Header Record (1) — 94 chars
  L.push('1'+'01'+h38Pad(destDfi,9,' ',false)+h38Pad(originDfi+'0',9,' ',false)
    +fileDate+fileTime+'A'+'094'+'10'+'1'
    +h38Pad('H38 PAYROLL',23,' ',false)+bizName23+' '.repeat(8)+'  ');
  // Batch Header Record (5) — 94 chars
  const batchNum='0000001';
  L.push('5'+'225'+bizName+' '.repeat(20)+h38Pad(bizId,10,' ',false)+'PPD'
    +h38Pad('PAYROLL',10,' ',false)+' '.repeat(6)+effDate+'   '+'1'+originDfi+batchNum);
  let entryCount=0,totalDebit=0,totalCredit=0,entryHash=0;
  const traceBase=Number(String(Date.now()).slice(-7));
  lines.forEach((line,idx)=>{
    const emp=employees.find(e=>rowId(e,'Employee ID')===v(line,'Employee ID'))||{};
    const routing=String(v(emp,'Bank Routing')||'').replace(/\D/g,'');
    const account=h38Pad(v(emp,'Bank Account')||'',17,' ',false);
    if(!routing||routing.length!==9)return; // skip without valid routing
    const acctType=String(v(emp,'Account Type')||'checking').toLowerCase().startsWith('s')?'32':'22';
    const amountCents=Math.round(num(v(line,'Net Pay'))*100);
    if(amountCents<=0)return;
    const empName=h38Pad(v(emp,'Display Name')||'Employee',22,' ',false).toUpperCase();
    const empId=h38Pad(v(emp,'Employee ID')||'',15,' ',false);
    entryCount++;totalCredit+=amountCents;entryHash+=Number(routing.slice(0,8));
    const trace=originDfi+h38Pad(traceBase+idx,7,'0',true);
    // Entry Detail Record (6) — 94 chars
    L.push('6'+acctType+routing.slice(0,8)+routing.slice(8,9)+account
      +h38Pad(amountCents,10,'0',true)+empId+empName+'  '+'1'+trace);
    // Addenda Record (7) — 94 chars
    L.push('7'+'05'+h38Pad('PAYROLL '+effDate,80,' ',false)+'0001'+h38Pad(traceBase+idx,7,'0',true));
  });
  entryHash=entryHash%10000000000;
  const addendaCount=entryCount; // one addenda per entry
  const totalRecords=entryCount+addendaCount;
  // Batch Control Record (8) — 94 chars
  L.push('8'+'225'+h38Pad(totalRecords,6,'0',true)+h38Pad(entryHash,10,'0',true)
    +h38Pad(totalDebit,12,'0',true)+h38Pad(totalCredit,12,'0',true)
    +h38Pad(bizId,10,' ',false)+' '.repeat(19)+' '.repeat(6)+originDfi+batchNum);
  // File Control Record (9) — 94 chars
  const blockCount=Math.ceil((L.length+1)/10);
  L.push('9'+h38Pad(1,6,'0',true)+h38Pad(blockCount,6,'0',true)+h38Pad(totalRecords,8,'0',true)
    +h38Pad(entryHash,10,'0',true)+h38Pad(totalDebit,12,'0',true)+h38Pad(totalCredit,12,'0',true)+' '.repeat(39));
  // Block fill to multiple of 10
  while(L.length%10!==0)L.push('9'.repeat(94));
  return L.join('\n');
}
;

/* --- ./tax-packet.js --- */
/* H38 Office — Accountant Tax Packet (v2.0)
 * Generates professional, print-ready tax documents for the accountant:
 * P&L, expense summary with receipts, IRS mileage log, 1099-NEC summary,
 * home office calculation, and a one-click year-end packet.
 * Manual-first, no AI. Per-tenant (business_id scoped). The Office never files a return.
 */

function taxPacketYear(){return state.taxPacketYear||new Date().getFullYear();}

/* 1099-NEC reporting threshold (IRS): $2,000 for payments made in 2026 and
 * later (One Big Beautiful Bill Act), $600 for payments made in 2025. */
function tax1099Threshold(year){return year>=2026?2000:600;}

function taxYearRange(year){return [`${year}-01-01`,`${year}-12-31`];}

function taxPacketData(year){
  const [start,end]=taxYearRange(year);
  const inYear=(row,...keys)=>within(v(row,...keys),start,end);
  const invoices=records('invoices').filter(row=>inYear(row,'Invoice Date','Created Time')&&String(v(row,'Status')).toUpperCase()!=='VOIDED');
  const expenses=records('expenses').filter(row=>inYear(row,'Expense Date','Created Time'));
  const mileage=records('mileageEntries').filter(row=>inYear(row,'Trip Date','Created Time'));
  const subPayments=records('subcontractorPayments').filter(row=>inYear(row,'Payment Date','Created Time'));
  const settings=(records('taxSettings')||[]).find(row=>String(v(row,'Tax Year'))===String(year))||{};
  return {year,start,end,invoices,expenses,mileage,subPayments,settings};
}

function taxPL(data){
  const revenue={};
  data.invoices.forEach(row=>{
    const cat=v(row,'Category')||'Contract Revenue';
    revenue[cat]=num(revenue[cat])+num(v(row,'Total'));
  });
  const exp={};
  data.expenses.forEach(row=>{
    const cat=v(row,'Category')||'Uncategorized';
    exp[cat]=num(exp[cat])+num(v(row,'Amount'))+num(v(row,'Tax'));
  });
  const totalRevenue=Object.values(revenue).reduce((a,b)=>a+b,0);
  const totalExpenses=Object.values(exp).reduce((a,b)=>a+b,0);
  return {revenue,expenses:exp,totalRevenue,totalExpenses,netProfit:totalRevenue-totalExpenses};
}

function taxMileageTotals(data){
  const miles=data.mileage.reduce((s,row)=>s+num(v(row,'Miles')),0);
  return {trips:data.mileage.length,miles};
}

function tax1099(data){
  const bySub={};
  data.subPayments.forEach(row=>{
    const name=v(row,'Subcontractor Name')||'Unknown';
    if(!bySub[name])bySub[name]={name,total:0,payments:0,tin:v(row,'TIN')||''};
    bySub[name].total+=num(v(row,'Amount'));
    bySub[name].payments+=1;
  });
  return Object.values(bySub).sort((a,b)=>b.total-a.total);
}

function taxHomeOffice(settings){
  const officeSqft=num(v(settings,'Office Sq Ft')),homeSqft=num(v(settings,'Home Sq Ft')),method=v(settings,'Method')||'Simplified';
  let deduction=0,detail='';
  if(method==='Simplified'){
    const capped=Math.min(officeSqft,300);
    deduction=capped*5;
    detail=`Simplified method: ${capped} sq ft (capped at 300) × $5 = $${deduction.toFixed(2)}`;
  }else{
    const pct=homeSqft>0?(officeSqft/homeSqft*100):0;
    deduction=num(v(settings,'Actual Home Expenses'))*pct/100;
    detail=`Actual method: ${officeSqft} of ${homeSqft} sq ft (${pct.toFixed(1)}%) × $${num(v(settings,'Actual Home Expenses')).toFixed(2)} home expenses = $${deduction.toFixed(2)}`;
  }
  return {officeSqft,homeSqft,method,deduction,detail};
}

function taxPacketSection(){
  const year=taxPacketYear(),data=taxPacketData(year),pl=taxPL(data),m=taxMileageTotals(data),subs=tax1099(data),ho=taxHomeOffice(data.settings);
  const bizName=esc(state.snapshot?.business?.businessName||'');
  const years=[];for(let y=new Date().getFullYear();y>=2023;y--)years.push(y);
  const threshold1099=tax1099Threshold(year);
  const need1099=subs.filter(s=>s.total>=threshold1099);
  return `<section class="card span12" id="h38-tax-packet"><h2>Accountant Tax Packet — ${year}</h2>
  <p class="muted small">Professional year-end documents for your accountant to verify and file. The Office prepares — it never files a return.</p>
  <div class="two"><div><label>Tax year</label><select id="taxPacketYear">${years.map(y=>`<option value="${y}"${y===year?' selected':''}>${y}</option>`).join('')}</select></div>
  <div><label>&nbsp;</label><div class="actions"><button type="button" class="primary" id="downloadTaxPacketBtn">Download Tax Packet (PDF)</button><button type="button" class="secondary" id="printTaxPacketBtn">Print Tax Packet</button></div></div></div>
  <div class="stats">
    <div class="stat"><strong>${money(pl.totalRevenue)}</strong><span>Revenue</span></div>
    <div class="stat"><strong>${money(pl.totalExpenses)}</strong><span>Expenses</span></div>
    <div class="stat"><strong>${money(pl.netProfit)}</strong><span>Net profit</span></div>
    <div class="stat"><strong>${m.miles.toFixed(1)}</strong><span>Business miles (${m.trips} trips)</span></div>
    <div class="stat"><strong>${need1099.length}</strong><span>1099-NEC required</span></div>
    <div class="stat"><strong>${money(ho.deduction)}</strong><span>Home office deduction</span></div>
  </div>
  <h3>Profit &amp; Loss — ${year}</h3>
  ${pl.totalRevenue||pl.totalExpenses?`<div class="two"><div><h4>Revenue</h4><div class="list">${Object.entries(pl.revenue).map(([c,a])=>`<div class="row"><strong>${esc(c)}</strong><small>${money(a)}</small></div>`).join('')}</div><div class="row-top"><strong>Total revenue</strong><strong>${money(pl.totalRevenue)}</strong></div></div>
  <div><h4>Expenses</h4><div class="list">${Object.entries(pl.expenses).map(([c,a])=>`<div class="row"><strong>${esc(c)}</strong><small>${money(a)}</small></div>`).join('')}</div><div class="row-top"><strong>Total expenses</strong><strong>${money(pl.totalExpenses)}</strong></div></div></div>
  <div class="row-top" style="margin-top:8px"><strong>Net profit (loss)</strong><strong>${money(pl.netProfit)}</strong></div>`
  :empty('No revenue or expenses recorded for '+year+'. Add invoices and expenses in Money, then return here.')}
  <h3>Expense detail</h3>
  <div class="list">${data.expenses.length?data.expenses.slice(0,100).map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Description')||'Expense')}</strong><span>${money(num(v(row,'Amount'))+num(v(row,'Tax')))}</span></div><small>${esc(v(row,'Category')||'Uncategorized')} · ${dateOnly(v(row,'Expense Date'))}</small></div>`).join(''):empty('No expenses for '+year+'.')}</div>
  <h3>Mileage log — ${year} <span class="muted small">(IRS: date, miles, business purpose required)</span></h3>
  <form id="mileageEntryForm"><div class="two"><div><label>Date</label><input name="tripDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></div><div><label>Miles</label><input name="miles" type="number" min="0" step="0.1" required></div></div>
  <div class="two"><div><label>From</label><input name="origin" placeholder="Home / shop"></div><div><label>To</label><input name="destination" placeholder="Job site"></div></div>
  <label>Business purpose</label><input name="purpose" required placeholder="Site visit, material pickup…">
  <div class="actions"><button>Add mileage entry</button></div></form>
  <div class="list">${data.mileage.length?data.mileage.slice(0,100).map(row=>`<div class="row"><div class="row-top"><strong>${esc(v(row,'Purpose'))}</strong><span>${num(v(row,'Miles')).toFixed(1)} mi</span></div><small>${dateOnly(v(row,'Trip Date'))} · ${esc(v(row,'Origin')||'')} → ${esc(v(row,'Destination')||'')}</small></div>`).join(''):empty('No mileage entries for '+year+'. Log trips above or in Field → Receipt & mileage.')}</div>
  <h3>1099-NEC summary — ${year}</h3>
  <p class="muted small">Subcontractors paid $${threshold1099.toLocaleString()} or more in ${year} need a 1099-NEC. (IRS threshold: $600 for 2025 payments, $2,000 for 2026 and later.) Give this list to your accountant.</p>
  <form id="subPaymentForm"><div class="two"><div><label>Subcontractor name</label><input name="subName" required></div><div><label>TIN (optional)</label><input name="tin" placeholder="XX-XXXXXXX"></div></div>
  <div class="two"><div><label>Amount</label><input name="amount" type="number" min="0" step="0.01" required></div><div><label>Payment date</label><input name="paymentDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></div></div>
  <label>Notes</label><input name="notes" placeholder="Job or invoice reference">
  <div class="actions"><button>Record subcontractor payment</button></div></form>
  <div class="list">${subs.length?subs.map(s=>`<div class="row"><div class="row-top"><strong>${esc(s.name)}</strong>${s.total>=threshold1099?pill('1099 required'):pill('under $'+threshold1099.toLocaleString())}</div><small>${money(s.total)} across ${s.payments} payment${s.payments===1?'':'s'}${s.tin?` · TIN on file`:''}</small></div>`).join(''):empty('No subcontractor payments recorded for '+year+'.')}</div>
  <h3>Home office deduction — ${year}</h3>
  <form id="homeOfficeForm"><div class="two"><div><label>Office sq ft</label><input name="officeSqft" type="number" min="0" step="1" value="${esc(v(data.settings,'Office Sq Ft')||'')}"></div><div><label>Total home sq ft</label><input name="homeSqft" type="number" min="0" step="1" value="${esc(v(data.settings,'Home Sq Ft')||'')}"></div></div>
  <div class="two"><div><label>Method</label><select name="method"><option${(v(data.settings,'Method')||'Simplified')==='Simplified'?' selected':''}>Simplified</option><option${v(data.settings,'Method')==='Actual'?' selected':''}>Actual</option></select></div><div><label>Total home expenses (actual method)</label><input name="actualExpenses" type="number" min="0" step="0.01" value="${esc(v(data.settings,'Actual Home Expenses')||'')}"></div></div>
  <div class="actions"><button>Save home office info</button></div></form>
  <p class="small">${esc(ho.detail||'Enter your office and home square footage above.')}</p>
  <div class="notice">Bring the printed packet to your accountant for verification and filing. Nothing here is filed automatically.</div>
  </section>`;
}

function bindTaxPacket(){
  const yearSel=$('taxPacketYear');
  if(yearSel)yearSel.onchange=e=>{state.taxPacketYear=num(e.target.value);renderTaxPrep();};
  const printBtn=$('printTaxPacketBtn');
  if(printBtn)printBtn.onclick=()=>printTaxPacket(taxPacketYear());
  const downloadBtn=$('downloadTaxPacketBtn');
  if(downloadBtn)downloadBtn.onclick=()=>downloadTaxPacketPdf(taxPacketYear());
  bindForm('mileageEntryForm',async(data,form)=>{
    const id=newId('MILEAGE'),record={'Mileage ID':id,'Business ID':state.businessId,'Trip Date':requireValue(data.tripDate,'Date is required.'),'Miles':num(data.miles),'Purpose':requireValue(data.purpose,'Business purpose is required.'),'Origin':data.origin,'Destination':data.destination,'Status':'Recorded','Created Time':now(),'Updated Time':now(),'Record Version':1};
    await queueOperation('SAVE_ENTITY','Mileage',id,{entity:'mileageEntries',record},{collection:'mileageEntries',record,idKeys:['Mileage ID']});
    form.reset();toast('Mileage entry saved.');renderTaxPrep();
  });
  bindForm('subPaymentForm',async(data,form)=>{
    const id=newId('SUBPAY'),record={'Subcontractor Payment ID':id,'Business ID':state.businessId,'Subcontractor Name':requireValue(data.subName,'Name is required.'),'TIN':data.tin,'Amount':num(data.amount),'Payment Date':requireValue(data.paymentDate,'Date is required.'),'Notes':data.notes,'Tax Year':String(data.paymentDate).slice(0,4),'Created Time':now(),'Updated Time':now(),'Record Version':1};
    await queueOperation('SAVE_ENTITY','Subcontractor Payment',id,{entity:'subcontractorPayments',record},{collection:'subcontractorPayments',record,idKeys:['Subcontractor Payment ID']});
    form.reset();toast('Subcontractor payment recorded.');renderTaxPrep();
  });
  bindForm('homeOfficeForm',async(data,form)=>{
    const id='TAXSET-'+taxPacketYear(),record={'Tax Settings ID':id,'Business ID':state.businessId,'Tax Year':String(taxPacketYear()),'Office Sq Ft':num(data.officeSqft),'Home Sq Ft':num(data.homeSqft),'Method':data.method,'Actual Home Expenses':num(data.actualExpenses),'Updated Time':now(),'Record Version':1};
    await queueOperation('SAVE_ENTITY','Tax Settings',id,{entity:'taxSettings',record},{collection:'taxSettings',record,idKeys:['Tax Settings ID']});
    toast('Home office info saved.');renderTaxPrep();
  });
}

/* ---------- Print packet ---------- */

function taxPacketPrintCss(){return `<style>
  @media print{body{margin:0}.no-print{display:none!important}}
  body{font-family:Georgia,'Times New Roman',serif;color:#111;max-width:760px;margin:0 auto;padding:24px;font-size:12pt;line-height:1.5}
  h1{font-size:20pt;border-bottom:2px solid #111;padding-bottom:8px;margin-bottom:4px}
  h2{font-size:15pt;margin-top:28px;border-bottom:1px solid #999;padding-bottom:4px;page-break-after:avoid}
  h3{font-size:12pt;margin:14px 0 6px}
  table{width:100%;border-collapse:collapse;margin:8px 0}
  th,td{text-align:left;padding:6px 8px;border-bottom:1px solid #ccc;font-size:11pt}
  th{background:#f2f2f2}
  td.n,th.n{text-align:right}
  .totals td{font-weight:bold;border-top:2px solid #111}
  .meta{color:#444;font-size:10pt;margin-bottom:16px}
  .sig{margin-top:32px;display:flex;gap:40px}
  .sig div{flex:1;border-top:1px solid #111;padding-top:4px;font-size:10pt;color:#444}
  .warn{background:#fff8e1;border:1px solid #e0c36a;padding:10px 14px;font-size:10pt;margin:16px 0}
  .pagebreak{page-break-before:always}
</style>`;}

function taxPacketPrintHtml(year){
  const data=taxPacketData(year),pl=taxPL(data),m=taxMileageTotals(data),subs=tax1099(data),ho=taxHomeOffice(data.settings);
  const threshold1099=tax1099Threshold(year);
  const biz=esc(state.snapshot?.business?.businessName||'Business');
  const prepared=new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
  const catRows=obj=>Object.entries(obj).sort((a,b)=>b[1]-a[1]).map(([c,a])=>`<tr><td>${esc(c)}</td><td class="n">$${a.toFixed(2)}</td></tr>`).join('');
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>Tax Packet ${year} — ${biz}</title>${taxPacketPrintCss()}</head><body>
  <div class="no-print" style="margin-bottom:16px"><button onclick="window.print()" style="font-size:14pt;padding:10px 24px">Print / Save as PDF</button></div>
  <h1>${biz} — Tax Preparation Packet</h1>
  <div class="meta">Tax year ${year} · Prepared ${prepared} from H38 Business Office records · For accountant verification and filing. This packet is informational only — no return has been filed.</div>

  <h2>1. Profit &amp; Loss Statement — ${year}</h2>
  <h3>Revenue</h3>
  <table><tr><th>Category</th><th class="n">Amount</th></tr>${catRows(pl.revenue)||'<tr><td colspan="2">No revenue recorded.</td></tr>'}<tr class="totals"><td>Total revenue</td><td class="n">$${pl.totalRevenue.toFixed(2)}</td></tr></table>
  <h3>Expenses</h3>
  <table><tr><th>Category</th><th class="n">Amount</th></tr>${catRows(pl.expenses)||'<tr><td colspan="2">No expenses recorded.</td></tr>'}<tr class="totals"><td>Total expenses</td><td class="n">$${pl.totalExpenses.toFixed(2)}</td></tr></table>
  <table><tr class="totals"><td>Net profit (loss)</td><td class="n">$${pl.netProfit.toFixed(2)}</td></tr></table>

  <h2 class="pagebreak">2. Expense Detail — ${year}</h2>
  <table><tr><th>Date</th><th>Description</th><th>Category</th><th class="n">Amount</th></tr>
  ${data.expenses.length?data.expenses.map(r=>`<tr><td>${esc(dateOnly(v(r,'Expense Date')))}</td><td>${esc(v(r,'Description')||'—')}</td><td>${esc(v(r,'Category')||'Uncategorized')}</td><td class="n">$${(num(v(r,'Amount'))+num(v(r,'Tax'))).toFixed(2)}</td></tr>`).join(''):'<tr><td colspan="4">No expenses recorded.</td></tr>'}
  </table>
  <div class="warn">Receipt images are stored with each expense in the H38 Office (Money → Expenses). Attach or bring them for any expense your accountant flags.</div>

  <h2 class="pagebreak">3. Business Mileage Log — ${year}</h2>
  <div class="meta">IRS requires: date, miles driven, and business purpose for each trip. Total: ${m.miles.toFixed(1)} miles across ${m.trips} trips.</div>
  <table><tr><th>Date</th><th>From → To</th><th>Purpose</th><th class="n">Miles</th></tr>
  ${data.mileage.length?data.mileage.map(r=>`<tr><td>${esc(dateOnly(v(r,'Trip Date')))}</td><td>${esc(v(r,'Origin')||'—')} → ${esc(v(r,'Destination')||'—')}</td><td>${esc(v(r,'Purpose')||'—')}</td><td class="n">${num(v(r,'Miles')).toFixed(1)}</td></tr>`).join(''):'<tr><td colspan="4">No mileage entries recorded.</td></tr>'}
  <tr class="totals"><td colspan="3">Total business miles</td><td class="n">${m.miles.toFixed(1)}</td></tr></table>

  <h2 class="pagebreak">4. 1099-NEC Summary — ${year}</h2>
  <div class="meta">Subcontractors paid $${threshold1099.toLocaleString()} or more in ${year} generally require a Form 1099-NEC. (IRS threshold: $600 for 2025 payments, $2,000 for 2026 and later.) Confirm thresholds and filing with your accountant.</div>
  <table><tr><th>Subcontractor</th><th class="n">Payments</th><th class="n">Total paid</th><th>1099 needed</th></tr>
  ${subs.length?subs.map(s=>`<tr><td>${esc(s.name)}${s.tin?` (TIN on file)`:''}</td><td class="n">${s.payments}</td><td class="n">$${s.total.toFixed(2)}</td><td>${s.total>=threshold1099?'<strong>YES</strong>':'No'}</td></tr>`).join(''):'<tr><td colspan="4">No subcontractor payments recorded.</td></tr>'}
  </table>

  <h2>5. Home Office Deduction — ${year}</h2>
  <table><tr><th>Item</th><th>Value</th></tr>
  <tr><td>Method</td><td>${esc(ho.method)}</td></tr>
  <tr><td>Office area</td><td>${ho.officeSqft} sq ft</td></tr>
  <tr><td>Total home area</td><td>${ho.homeSqft} sq ft</td></tr>
  <tr class="totals"><td>Calculated deduction</td><td>$${ho.deduction.toFixed(2)}</td></tr></table>
  <div class="meta">${esc(ho.detail||'No home office information entered.')}</div>

  <h2 class="pagebreak">6. Accountant Review</h2>
  <div class="warn">Prepared from H38 Business Office records on ${prepared}. Figures are drafts for professional verification — confirm categorization, depreciation, inventory, and payroll tax filings with your accountant before filing.</div>
  <div class="sig"><div>Owner signature / date</div><div>Accountant signature / date</div></div>
  </body></html>`;
}

function printTaxPacket(year){
  const w=window.open('','_blank','width=900,height=700');
  if(!w){toast('Popup blocked — allow popups to print the tax packet.',true);return;}
  w.document.write(taxPacketPrintHtml(year));
  w.document.close();
}
window.printTaxPacket=printTaxPacket;

/* ---------- Direct PDF export (no print dialog, no external library) ---------- */

function taxPdfClean(value){
  return String(value===undefined||value===null?'':value)
    .replace(/\u2192/g,'->').replace(/\u2014/g,'-').replace(/\u2013/g,'-')
    .replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D]/g,'"').replace(/\u00B7/g,'-')
    .replace(/[^\x20-\x7E\xA0-\xFF]/g,'');
}
function taxPdfEscape(text){return taxPdfClean(text).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');}
function taxPdfPad(text,width){const t=taxPdfClean(text);return t.length>width?t.slice(0,width):t+Array(width-t.length+1).join(' ');}
function taxPdfRight(text,width){const t=taxPdfClean(text);return t.length>width?t.slice(0,width):Array(width-t.length+1).join(' ')+t;}
function taxPdfWrap(text,width){
  const words=taxPdfClean(text).split(/\s+/).filter(Boolean),lines=[];let line='';
  for(const word of words){const next=line?line+' '+word:word;if(next.length>width&&line){lines.push(line);line=word;}else line=next;}
  if(line)lines.push(line);return lines;
}

function taxPacketPdfLines(year){
  const data=taxPacketData(year),pl=taxPL(data),m=taxMileageTotals(data),subs=tax1099(data),ho=taxHomeOffice(data.settings);
  const threshold1099=tax1099Threshold(year);
  const biz=state.snapshot&&state.snapshot.business?String(state.snapshot.business.businessName||'Business'):'Business';
  const prepared=new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
  const usd=n=>'$'+Number(n||0).toFixed(2);
  const L=[];
  const title=t=>L.push({t,font:'H',size:16,bold:1,gap:6});
  const head=t=>L.push({t,font:'H',size:12.5,bold:1,gap:14});
  const sub=t=>L.push({t,font:'H',size:10.5,bold:1,gap:9});
  const body=t=>L.push({t,font:'H',size:9.5,gap:5});
  const row=t=>L.push({t,font:'C',size:8.8,gap:5});
  const rowB=t=>L.push({t,font:'C',size:8.8,bold:1,gap:5});
  title(biz+' - Tax Preparation Packet');
  body('Tax year '+year+' - Prepared '+prepared+' from H38 Business Office records');
  body('For accountant verification and filing. Informational only - no return has been filed.');
  head('1. Profit & Loss Statement - '+year);
  sub('Revenue');
  const cats=obj=>Object.entries(obj).sort((a,b)=>b[1]-a[1]);
  if(cats(pl.revenue).length)cats(pl.revenue).forEach(([c,a])=>row(taxPdfPad(c,58)+taxPdfRight(usd(a),16)));
  else row('  No revenue recorded.');
  rowB(taxPdfPad('Total revenue',58)+taxPdfRight(usd(pl.totalRevenue),16));
  sub('Expenses');
  if(cats(pl.expenses).length)cats(pl.expenses).forEach(([c,a])=>row(taxPdfPad(c,58)+taxPdfRight(usd(a),16)));
  else row('  No expenses recorded.');
  rowB(taxPdfPad('Total expenses',58)+taxPdfRight(usd(pl.totalExpenses),16));
  rowB(taxPdfPad('Net profit (loss)',58)+taxPdfRight(usd(pl.netProfit),16));
  head('2. Expense Detail - '+year);
  if(data.expenses.length)data.expenses.slice(0,100).forEach(r=>row(taxPdfPad(dateOnly(v(r,'Expense Date')),11)+taxPdfPad(v(r,'Description')||'Expense',30)+taxPdfPad(v(r,'Category')||'Uncategorized',22)+taxPdfRight(usd(num(v(r,'Amount'))+num(v(r,'Tax'))),11)));
  else row('  No expenses recorded for '+year+'.');
  body('Receipt images are stored with each expense in the H38 Office (Money - Expenses).');
  head('3. Business Mileage Log - '+year);
  body('IRS requires date, miles, and business purpose for each trip. Total: '+m.miles.toFixed(1)+' miles across '+m.trips+' trips.');
  if(data.mileage.length)data.mileage.slice(0,100).forEach(r=>row(taxPdfPad(dateOnly(v(r,'Trip Date')),11)+taxPdfPad((v(r,'Origin')||'-')+' -> '+(v(r,'Destination')||'-'),30)+taxPdfPad(v(r,'Purpose')||'-',22)+taxPdfRight(num(v(r,'Miles')).toFixed(1),11)));
  else row('  No mileage entries recorded.');
  head('4. 1099-NEC Summary - '+year);
  taxPdfWrap('Subcontractors paid $'+threshold1099.toLocaleString()+' or more in '+year+' generally require a Form 1099-NEC. (IRS threshold: $600 for 2025 payments, $2,000 for 2026 and later.) Confirm with your accountant.',100).forEach(t=>body(t));
  if(subs.length)subs.forEach(x=>row(taxPdfPad(x.name+(x.tin?' (TIN on file)':''),44)+taxPdfRight(String(x.payments),6)+taxPdfRight(usd(x.total),14)+taxPdfRight(x.total>=threshold1099?'YES':'No',6)));
  else row('  No subcontractor payments recorded.');
  head('5. Home Office Deduction - '+year);
  row(taxPdfPad('Method',40)+taxPdfClean(ho.method));
  row(taxPdfPad('Office area',40)+ho.officeSqft+' sq ft');
  row(taxPdfPad('Total home area',40)+ho.homeSqft+' sq ft');
  rowB(taxPdfPad('Calculated deduction',40)+usd(ho.deduction));
  if(ho.detail)taxPdfWrap(ho.detail,100).forEach(t=>body(t));
  head('6. Accountant Review');
  taxPdfWrap('Prepared from H38 Business Office records on '+prepared+'. Figures are drafts for professional verification - confirm categorization, depreciation, inventory, and payroll tax filings with your accountant before filing. The Office prepares; it never files a return.',100).forEach(t=>body(t));
  L.push({t:'',font:'H',size:9.5,gap:16});
  row(taxPdfPad('Owner signature / date',37)+'   '+taxPdfPad('Accountant signature / date',37));
  row(taxPdfPad('__________________________',37)+'   '+taxPdfPad('__________________________',37));
  return {lines:L,biz,year};
}

function taxPacketPdfString(year){
  const {lines,biz}=taxPacketPdfLines(year);
  const pageW=612,pageH=792,margin=54,topY=726,bottomY=60;
  const heights=l=>Math.round(l.size*1.5)+(l.gap||0);
  const pages=[[]];let y=topY;
  for(const line of lines){const h=heights(line);if(y-h<bottomY&&pages[pages.length-1].length){pages.push([]);y=topY;}pages[pages.length-1].push({line,y});y-=h;}
  const fontFor=l=>(l.font==='C'?(l.bold?'/F4':'/F3'):(l.bold?'/F2':'/F1'));
  const contents=pages.map((items,idx)=>{
    const ops=['0.4 g', 'BT /F1 7.5 Tf '+margin+' 36 Td ('+taxPdfEscape('H38 Business Office - Tax Preparation Packet '+year+' - Page '+(idx+1)+' of '+pages.length)+') Tj ET','0 g'];
    for(const {line,y:ly} of items){if(!line.t)continue;ops.push('BT '+fontFor(line)+' '+line.size+' Tf '+margin+' '+ly+' Td ('+taxPdfEscape(line.t)+') Tj ET');}
    return ops.join('\n');
  });
  const objects=[];
  objects[1]='<< /Type /Catalog /Pages 2 0 R >>';
  const kids=contents.map((_,i)=>String(7+i*2)+' 0 R').join(' ');
  objects[2]='<< /Type /Pages /Kids ['+kids+'] /Count '+contents.length+' >>';
  objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';
  objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';
  objects[5]='<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>';
  objects[6]='<< /Type /Font /Subtype /Type1 /BaseFont /Courier-Bold >>';
  contents.forEach((content,i)=>{
    objects[7+i*2]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+pageW+' '+pageH+'] /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R /F4 6 0 R >> >> /Contents '+(8+i*2)+' 0 R >>';
    objects[8+i*2]='<< /Length '+content.length+' >>\nstream\n'+content+'\nendstream';
  });
  let pdf='%PDF-1.4\n';const offsets=[0];
  for(let n=1;n<objects.length;n++){offsets[n]=pdf.length;pdf+=n+' 0 obj\n'+objects[n]+'\nendobj\n';}
  const xrefPos=pdf.length;
  pdf+='xref\n0 '+objects.length+'\n0000000000 65535 f \n';
  for(let n=1;n<objects.length;n++)pdf+=String(offsets[n]).padStart(10,'0')+' 00000 n \n';
  pdf+='trailer\n<< /Size '+objects.length+' /Root 1 0 R >>\nstartxref\n'+xrefPos+'\n%%EOF';
  return pdf;
}

function downloadTaxPacketPdf(year){
  try{
    const text=taxPacketPdfString(year);
    const bytes=new Uint8Array(text.length);
    for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i)&0xff;
    const blob=new Blob([bytes],{type:'application/pdf'});
    const url=URL.createObjectURL(blob);
    const anchor=document.createElement('a');
    anchor.href=url;anchor.download='H38-Tax-Packet-'+year+'.pdf';
    document.body.appendChild(anchor);anchor.click();anchor.remove();
    setTimeout(()=>URL.revokeObjectURL(url),4000);
    toast('Tax packet PDF downloaded. Bring it to your accountant for verification and filing.');
  }catch(error){
    toast('PDF export failed: '+(error&&error.message?error.message:String(error)),true);
  }
}
window.downloadTaxPacketPdf=downloadTaxPacketPdf;
;

/* --- ./cpa-package.js --- */
/* H38 Office — One-Click CPA Package (v1.0)
 * Generates a complete, organized year-end PDF package for the accountant:
 * cover sheet, P&L, balance sheet, cash flow, expense detail, mileage log,
 * home office (both methods), 1099-NEC summary, sales tax summary, and a
 * missing-documents checklist at the back.
 * Manual-first, no AI. Per-tenant (business_id scoped). The Office never files a return.
 * Reuses tax-packet.js data functions (taxPacketData, taxPL, taxMileageTotals,
 * tax1099, taxHomeOffice, tax1099Threshold) and its hand-rolled PDF helpers
 * (taxPdfClean/Escape/Pad/Right/Wrap) — this file loads after tax-packet.js.
 */

function cpaPackageYear(){return typeof taxPacketYear==='function'?taxPacketYear():(state.taxPacketYear||new Date().getFullYear());}

/* ---------- Data assembly (builds on tax-packet.js) ---------- */

function cpaPackageData(year){
  const base=taxPacketData(year); // invoices, expenses, mileage, subPayments, settings, year, start, end
  const inYear=(row,...keys)=>within(v(row,...keys),base.start,base.end);
  const notVoided=row=>String(v(row,'Status')).toUpperCase().indexOf('VOID')<0;
  const payments=records('payments').filter(row=>inYear(row,'Created Time')&&notVoided(row));
  const vendorPayments=records('vendorPayments').filter(row=>inYear(row,'Payment Date','Created Time')&&notVoided(row));
  const checks=records('checks').filter(row=>inYear(row,'Payment Date','Created Time')&&!/VOID|CANCEL/i.test(String(v(row,'Status'))));
  const vendorBills=records('vendorBills').filter(row=>!/VOID|CANCEL/i.test(String(v(row,'Status'))));
  const bankAccounts=records('bankAccounts');
  const reconciliations=records('reconciliations');
  const payrollPeriods=records('payrollPeriods').filter(row=>inYear(row,'Pay Date','Period End','Created Time'));
  const inventoryTxns=records('inventoryTransactions');
  const priceBook=records('priceBook');
  const loans=records('loans');
  const loanPayments=records('loanPayments');
  const taxPeriods=records('taxPeriods').filter(row=>inYear(row,'Period Start','Period End','Created Time'));
  const missing=records('missingDocuments');
  const expensesNeedingReceipt=base.expenses.filter(row=>String(v(row,'Receipt Required')).toLowerCase()==='yes'&&!String(v(row,'Receipt ID')||'').trim());
  return {...base,payments,vendorPayments,checks,vendorBills,bankAccounts,reconciliations,payrollPeriods,inventoryTxns,priceBook,loans,loanPayments,taxPeriods,missing,expensesNeedingReceipt};
}

/* ---------- Balance sheet (NEW) ----------
 * Compiled from Office business records. Balances are current as of the run
 * date (the Office does not keep dated snapshots), so the PDF carries a note
 * telling the CPA to verify year-end adjustments. */

function cpaBalanceSheet(data){
  const cash=data.bankAccounts.reduce((s,r)=>s+num(v(r,'Available Balance','Ledger Balance','Balance')),0);
  const receivables=data.invoices.reduce((s,r)=>s+Math.max(0,num(v(r,'Balance'))),0);
  const stock=new Map();
  data.inventoryTxns.forEach(row=>{
    const id=v(row,'Item ID'),qty=Math.abs(num(v(row,'Quantity'))),dir=String(v(row,'Direction')).toUpperCase();
    stock.set(id,(stock.get(id)||0)+(dir==='OUT'?-qty:qty));
  });
  let inventory=0,inventoryItems=0;
  data.priceBook.forEach(row=>{
    const onHand=stock.get(v(row,'Item ID'))||0;
    if(onHand>0){inventory+=onHand*num(v(row,'Purchase Cost'));inventoryItems++;}
  });
  const payables=data.vendorBills.reduce((s,r)=>s+Math.max(0,num(v(r,'Open Balance','Balance','Amount Due','Total'))),0);
  const loanBal=data.loans.reduce((s,r)=>s+Math.max(0,num(v(r,'Balance','Remaining Balance','Outstanding Balance','Principal Balance'))),0);
  const totalAssets=cash+receivables+inventory;
  const totalLiabilities=payables+loanBal;
  return {
    cash,cashAccounts:data.bankAccounts.length,
    receivables,
    inventory,inventoryItems,
    payables,loanBal,loanCount:data.loans.length,
    totalAssets,totalLiabilities,
    equity:totalAssets-totalLiabilities
  };
}

/* ---------- Cash flow statement (NEW) — simplified direct method ---------- */

function cpaCashFlow(data){
  const inYear=(row,...keys)=>within(v(row,...keys),data.start,data.end);
  const receipts=data.payments.reduce((s,r)=>s+num(v(r,'Amount')),0);
  const vendorPaid=data.expenses.reduce((s,r)=>s+num(v(r,'Amount'))+num(v(r,'Tax')),0)
    +data.vendorPayments.reduce((s,r)=>s+num(v(r,'Amount','Total')),0)
    +data.checks.reduce((s,r)=>s+num(v(r,'Amount')),0);
  const payroll=data.payrollPeriods
    .filter(row=>/PAID|COMPLETE|CLOSED|FINAL|EXPORTED/i.test(String(v(row,'Status'))))
    .reduce((s,r)=>s+num(v(r,'Net Pay','Prepared Net Amount','Total Cost')),0);
  const subPay=data.subPayments.reduce((s,r)=>s+num(v(r,'Amount')),0);
  const operatingNet=receipts-vendorPaid-payroll-subPay;
  // Investing: equipment / fixed-asset purchases recorded in year (candidate collections)
  const invItems=[];
  ['fixedAssets','assetPurchases','equipmentPurchases'].forEach(name=>{
    records(name).forEach(r=>{
      if(!inYear(r,'Purchase Date','Date','Created Time'))return;
      const amount=num(v(r,'Cost','Purchase Price','Amount','Total'));
      if(amount>0)invItems.push({name:v(r,'Description','Asset Name','Name')||name,amount});
    });
  });
  const investingOut=invItems.reduce((s,i)=>s+i.amount,0);
  // Financing: loan proceeds received in year; loan payments made in year
  const loanProceeds=data.loans.filter(r=>inYear(r,'Disbursement Date','Loan Date','Start Date','Created Time'))
    .reduce((s,r)=>s+num(v(r,'Principal','Loan Amount','Original Amount')),0);
  const loanPaid=data.loanPayments.filter(r=>inYear(r,'Payment Date','Date','Created Time'))
    .reduce((s,r)=>s+num(v(r,'Amount','Principal','Total')),0);
  const financingNet=loanProceeds-loanPaid;
  return {receipts,vendorPaid,payroll,subPay,operatingNet,invItems,investingOut,loanProceeds,loanPaid,financingNet,netChange:operatingNet-investingOut+financingNet};
}

/* ---------- Home office — both methods side by side ---------- */

function cpaHomeOfficeBoth(data){
  const settings=data.settings;
  const officeSqft=num(v(settings,'Office Sq Ft')),homeSqft=num(v(settings,'Home Sq Ft'));
  const method=v(settings,'Method')||'Simplified';
  const simpCapped=Math.min(officeSqft,300);
  const simplified={capped:simpCapped,deduction:simpCapped*5};
  const pct=homeSqft>0?(officeSqft/homeSqft*100):0;
  const actual={pct,expenses:num(v(settings,'Actual Home Expenses')),deduction:num(v(settings,'Actual Home Expenses'))*pct/100};
  return {officeSqft,homeSqft,method,simplified,actual,entered:officeSqft>0&&homeSqft>0};
}

/* ---------- Sales tax summary (NEW) ---------- */

function cpaSalesTax(data){
  const byJur={};
  data.invoices.forEach(row=>{
    if(num(v(row,'Tax','Tax Amount'))<=0)return;
    const jur=v(row,'Tax Jurisdiction','Jurisdiction','Sales Tax Jurisdiction')||'Unassigned jurisdiction';
    if(!byJur[jur])byJur[jur]={jurisdiction:jur,taxable:0,collected:0,invoices:0};
    byJur[jur].taxable+=num(v(row,'Subtotal'));
    byJur[jur].collected+=num(v(row,'Tax','Tax Amount'));
    byJur[jur].invoices++;
  });
  return Object.values(byJur).sort((a,b)=>b.collected-a.collected);
}

/* ---------- Missing documents checklist (NEW) — gap scan ---------- */

function cpaMissingDocs(data){
  const items=[];
  const push=(area,item)=>items.push({area,item});
  // 1. Bank statements / reconciliations
  data.bankAccounts.forEach(acct=>{
    const acctId=String(v(acct,'Bank Account ID','Account ID','id')||'');
    const name=v(acct,'Account Name')||'bank account';
    const recs=data.reconciliations.filter(r=>{
      const rid=String(v(r,'Bank Account ID','Account ID','Account')||'');
      if(rid&&acctId&&rid!==acctId)return false;
      return within(v(r,'Statement Date','Created Time'),data.start,data.end);
    });
    if(!recs.length)push('Banking','Bank statement / reconciliation for "'+name+'" ('+data.year+')');
  });
  // 2. Required receipt images not attached
  data.expensesNeedingReceipt.forEach(r=>push('Receipts','Receipt image for '+(v(r,'Description')||'expense')+' — '+money(num(v(r,'Amount'))+num(v(r,'Tax')))+' on '+dateOnly(v(r,'Expense Date'))));
  // 3. Missing TIN/W-9 for subs who need a 1099
  const thr=tax1099Threshold(data.year);
  tax1099(data).filter(s=>s.total>=thr&&!String(s.tin||'').trim())
    .forEach(s=>push('1099-NEC','TIN / W-9 for '+s.name+' ('+money(s.total)+' paid — 1099-NEC required)'));
  // 4. Sales tax periods with no payment recorded
  data.taxPeriods
    .filter(row=>String(v(row,'Tax Type')).toLowerCase().indexOf('sales')>=0&&num(v(row,'Payment Recorded'))<=0)
    .forEach(row=>push('Sales tax','Sales tax payment not recorded: '+(v(row,'Jurisdiction')||'jurisdiction')+' '+dateOnly(v(row,'Period Start'))+' to '+dateOnly(v(row,'Period End'))+' (estimated liability '+money(v(row,'Estimated Liability'))+')'));
  // 5. Items already tracked as missing in the Office
  data.missing.filter(row=>!/CLOSED|RESOLVED|DONE/i.test(String(v(row,'Status'))))
    .forEach(row=>push(v(row,'Area')||'General','Already tracked: '+(v(row,'Document Type')||'document')+(v(row,'Due Date')?' — due '+dateOnly(v(row,'Due Date')):'')+(v(row,'Description')?' — '+v(row,'Description'):'')));
  // 6. Home office info never entered
  if(!num(v(data.settings,'Office Sq Ft'))&&!num(v(data.settings,'Home Sq Ft')))
    push('Home office','Home office square footage for '+data.year+' (enter it in the Tax Center, Accountant Tax Packet section)');
  return items;
}

/* ---------- Tax Center section (injected into the Tax / Tax Center page) ---------- */

function cpaPackageSection(){
  const year=cpaPackageYear();
  let stats='';
  try{
    const data=cpaPackageData(year),pl=taxPL(data),bs=cpaBalanceSheet(data),miss=cpaMissingDocs(data);
    stats=`<div class="stats">
      <div class="stat"><strong>${money(pl.netProfit)}</strong><span>Net profit</span></div>
      <div class="stat"><strong>${money(bs.totalAssets)}</strong><span>Assets (business records)</span></div>
      <div class="stat"><strong>${money(bs.totalLiabilities)}</strong><span>Liabilities</span></div>
      <div class="stat"><strong>${money(bs.equity)}</strong><span>Equity (plug)</span></div>
      <div class="stat"><strong>${miss.length}</strong><span>Missing document items</span></div>
    </div>`;
  }catch(e){stats=`<div class="notice warn">Package preview unavailable: ${typeof esc==='function'?esc(e.message||e):String(e.message||e)}</div>`;}
  return `<section class="card span12" id="h38-cpa-package"><h2>One-Click CPA Package — ${year}</h2>
  <p class="muted small">A complete, organized year-end package for your accountant: cover sheet, P&amp;L, balance sheet, cash flow, expense detail, mileage log, home office (both methods), 1099-NEC summary, sales tax summary, and a missing-documents checklist. The Office prepares — it never files a return.</p>
  ${stats}
  <div class="actions"><button type="button" class="primary" id="downloadCpaPackageBtn">Generate CPA Package (PDF)</button></div>
  <div class="notice">Give the downloaded package to your accountant for verification and filing. Balance-sheet balances are current Office balances as of the run date — your CPA should confirm year-end adjustments (depreciation, accruals, payroll tax filings).</div>
  </section>`;
}

function bindCpaPackage(){
  const btn=document.getElementById('downloadCpaPackageBtn');
  if(btn&&!btn.dataset.h38CpaBound){btn.dataset.h38CpaBound='1';btn.onclick=()=>downloadCpaPackagePdf(cpaPackageYear());}
}

/* ---------- PDF lines (10 sections, same line conventions as tax-packet.js) ---------- */

function cpaPdfLines(year){
  const data=cpaPackageData(year);
  const pl=taxPL(data),bs=cpaBalanceSheet(data),cf=cpaCashFlow(data);
  const m=taxMileageTotals(data),subs=tax1099(data),ho=cpaHomeOfficeBoth(data);
  const st=cpaSalesTax(data),miss=cpaMissingDocs(data);
  const threshold1099=tax1099Threshold(year);
  const biz=state.snapshot&&state.snapshot.business?String(state.snapshot.business.businessName||'Business'):'Business';
  const prepared=new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});
  const usd=n=>'$'+Number(n||0).toFixed(2);
  const L=[];
  const title=t=>L.push({t,font:'H',size:16,bold:1,gap:6});
  const head=t=>L.push({t,font:'H',size:12.5,bold:1,gap:14});
  const sub=t=>L.push({t,font:'H',size:10.5,bold:1,gap:9});
  const body=t=>L.push({t,font:'H',size:9.5,gap:5});
  const row=t=>L.push({t,font:'C',size:8.8,gap:5});
  const rowB=t=>L.push({t,font:'C',size:8.8,bold:1,gap:5});
  const cats=obj=>Object.entries(obj).sort((a,b)=>b[1]-a[1]);

  /* 1. Cover sheet */
  title('CPA Package');
  title(biz+' - Tax Year '+year);
  L.push({t:'',font:'H',size:9.5,gap:10});
  body('Prepared: '+prepared);
  body('Prepared from H38 Business Office records.');
  body('This package is informational only - no tax return has been filed.');
  L.push({t:'',font:'H',size:9.5,gap:6});
  body('Contents:');
  body('  2. Profit & Loss Statement');
  body('  3. Balance Sheet');
  body('  4. Cash Flow Statement');
  body('  5. Expense Detail with Receipts');
  body('  6. Business Mileage Log');
  body('  7. Home Office Deduction');
  body('  8. 1099-NEC Summary');
  body('  9. Sales Tax Summary');
  body('  10. Missing Documents Checklist');
  taxPdfWrap('Disclaimer: figures are drafts compiled from Office records for professional verification. Confirm categorization, depreciation, inventory valuation, payroll tax filings, and all year-end adjustments with your accountant before filing.',100).forEach(t=>body(t));

  /* 2. Profit & Loss */
  head('2. Profit & Loss Statement - '+year);
  sub('Revenue');
  if(cats(pl.revenue).length)cats(pl.revenue).forEach(([c,a])=>row(taxPdfPad(c,58)+taxPdfRight(usd(a),16)));
  else row('  No revenue recorded for '+year+'.');
  rowB(taxPdfPad('Total revenue',58)+taxPdfRight(usd(pl.totalRevenue),16));
  sub('Expenses');
  if(cats(pl.expenses).length)cats(pl.expenses).forEach(([c,a])=>row(taxPdfPad(c,58)+taxPdfRight(usd(a),16)));
  else row('  No expenses recorded for '+year+'.');
  rowB(taxPdfPad('Total expenses',58)+taxPdfRight(usd(pl.totalExpenses),16));
  rowB(taxPdfPad('Net profit (loss)',58)+taxPdfRight(usd(pl.netProfit),16));

  /* 3. Balance Sheet */
  head('3. Balance Sheet');
  sub('Assets');
  row(taxPdfPad('Cash ('+bs.cashAccounts+' bank account'+(bs.cashAccounts===1?'':'s')+')',58)+taxPdfRight(usd(bs.cash),16));
  row(taxPdfPad('Accounts receivable (unpaid invoices)',58)+taxPdfRight(usd(bs.receivables),16));
  row(taxPdfPad('Inventory ('+bs.inventoryItems+' items on hand)',58)+taxPdfRight(usd(bs.inventory),16));
  rowB(taxPdfPad('Total assets',58)+taxPdfRight(usd(bs.totalAssets),16));
  sub('Liabilities');
  row(taxPdfPad('Accounts payable (open vendor bills)',58)+taxPdfRight(usd(bs.payables),16));
  row(taxPdfPad('Loans ('+bs.loanCount+' recorded)',58)+taxPdfRight(usd(bs.loanBal),16));
  rowB(taxPdfPad('Total liabilities',58)+taxPdfRight(usd(bs.totalLiabilities),16));
  rowB(taxPdfPad('Equity (assets - liabilities)',58)+taxPdfRight(usd(bs.equity),16));
  taxPdfWrap('Compiled from Office business records (cash basis). Balances are current as of the run date - verify year-end adjustments (depreciation, accruals, payroll) with your CPA.',100).forEach(t=>body(t));

  /* 4. Cash Flow */
  head('4. Cash Flow Statement - '+year+' (direct method)');
  sub('Operating activities');
  row(taxPdfPad('Receipts from customers',58)+taxPdfRight(usd(cf.receipts),16));
  row(taxPdfPad('Payments to vendors & suppliers',58)+taxPdfRight('('+usd(cf.vendorPaid)+')',16));
  row(taxPdfPad('Payments to employees (paid payroll)',58)+taxPdfRight('('+usd(cf.payroll)+')',16));
  row(taxPdfPad('Payments to subcontractors',58)+taxPdfRight('('+usd(cf.subPay)+')',16));
  rowB(taxPdfPad('Net cash from operating activities',58)+taxPdfRight(usd(cf.operatingNet),16));
  sub('Investing activities');
  if(cf.invItems.length)cf.invItems.forEach(i=>row(taxPdfPad(i.name,58)+taxPdfRight('('+usd(i.amount)+')',16)));
  else row('  No equipment / fixed-asset purchases recorded for '+year+'.');
  rowB(taxPdfPad('Net cash from investing activities',58)+taxPdfRight('('+usd(cf.investingOut)+')',16));
  sub('Financing activities');
  row(taxPdfPad('Loan proceeds received',58)+taxPdfRight(usd(cf.loanProceeds),16));
  row(taxPdfPad('Loan payments made',58)+taxPdfRight('('+usd(cf.loanPaid)+')',16));
  rowB(taxPdfPad('Net cash from financing activities',58)+taxPdfRight(usd(cf.financingNet),16));
  rowB(taxPdfPad('Net change in cash (from activity)',58)+taxPdfRight(usd(cf.netChange),16));
  taxPdfWrap('Owner draws / contributions are not tracked separately by the Office - confirm equity movements with your CPA. Reconcile timing differences between recorded cash activity and bank statements.',100).forEach(t=>body(t));

  /* 5. Expense detail */
  head('5. Expense Detail with Receipts - '+year);
  if(data.expenses.length)data.expenses.slice(0,120).forEach(r=>{
    const missingR=String(v(r,'Receipt Required')).toLowerCase()==='yes'&&!String(v(r,'Receipt ID')||'').trim();
    row(taxPdfPad(dateOnly(v(r,'Expense Date')),11)+taxPdfPad(v(r,'Description')||'Expense',30)+taxPdfPad(v(r,'Category')||'Uncategorized',20)+taxPdfRight(usd(num(v(r,'Amount'))+num(v(r,'Tax'))),11)+(missingR?'  RECEIPT MISSING':''));
  });
  else row('  No expenses recorded for '+year+'.');
  body('Receipt images are stored with each expense in the H38 Office (Money - Expenses, and Documents).');
  if(data.expensesNeedingReceipt.length)body(data.expensesNeedingReceipt.length+' expense(s) are flagged as missing required receipts - see the Missing Documents Checklist (section 10).');

  /* 6. Mileage */
  head('6. Business Mileage Log - '+year);
  body('IRS requires date, miles, and business purpose for each trip. Total: '+m.miles.toFixed(1)+' miles across '+m.trips+' trips.');
  if(data.mileage.length)data.mileage.slice(0,120).forEach(r=>row(taxPdfPad(dateOnly(v(r,'Trip Date')),11)+taxPdfPad((v(r,'Origin')||'-')+' -> '+(v(r,'Destination')||'-'),30)+taxPdfPad(v(r,'Purpose')||'-',22)+taxPdfRight(num(v(r,'Miles')).toFixed(1),11)));
  else row('  No mileage entries recorded for '+year+'.');

  /* 7. Home office — both methods */
  head('7. Home Office Deduction - '+year);
  row(taxPdfPad('Office area',40)+ho.officeSqft+' sq ft');
  row(taxPdfPad('Total home area',40)+ho.homeSqft+' sq ft');
  if(!ho.entered){body('No home office information entered for '+year+'. Enter it in the Tax Center, Accountant Tax Packet section.');}
  sub('Simplified method'+(ho.method==='Simplified'?' (selected)':''));
  row(taxPdfPad('Office sq ft (capped at 300)',40)+ho.simplified.capped+' sq ft');
  row(taxPdfPad('Rate',40)+'$5 per sq ft');
  rowB(taxPdfPad('Simplified deduction',40)+usd(ho.simplified.deduction));
  sub('Actual method'+(ho.method==='Actual'?' (selected)':''));
  row(taxPdfPad('Business-use percentage',40)+ho.actual.pct.toFixed(1)+'%');
  row(taxPdfPad('Total home expenses entered',40)+usd(ho.actual.expenses));
  rowB(taxPdfPad('Actual-method deduction',40)+usd(ho.actual.deduction));
  body('Your CPA should confirm the method and the business-use percentage.');

  /* 8. 1099-NEC */
  head('8. 1099-NEC Summary - '+year);
  taxPdfWrap('Subcontractors paid $'+threshold1099.toLocaleString()+' or more in '+year+' generally require a Form 1099-NEC. (IRS threshold: $600 for 2025 payments, $2,000 for 2026 and later.) Confirm with your accountant.',100).forEach(t=>body(t));
  if(subs.length)subs.forEach(x=>row(taxPdfPad(x.name+(x.tin?' (TIN on file)':' (TIN MISSING)'),44)+taxPdfRight(String(x.payments),6)+taxPdfRight(usd(x.total),14)+taxPdfRight(x.total>=threshold1099?'YES':'No',6)));
  else row('  No subcontractor payments recorded for '+year+'.');

  /* 9. Sales tax */
  head('9. Sales Tax Summary - '+year);
  if(st.length)st.forEach(j=>row(taxPdfPad(j.jurisdiction,40)+taxPdfRight(String(j.invoices),6)+taxPdfRight(usd(j.taxable),14)+taxPdfRight(usd(j.collected),14)));
  else row('  No taxable sales with collected tax recorded for '+year+'.');
  if(st.length){row(taxPdfPad('Total taxable sales',40)+taxPdfPad('',6)+taxPdfRight(usd(st.reduce((s,j)=>s+j.taxable,0)),14));rowB(taxPdfPad('Total tax collected',40)+taxPdfPad('',6)+taxPdfRight(usd(st.reduce((s,j)=>s+j.collected,0)),14));}
  if(data.taxPeriods.length){
    sub('Prepared tax periods');
    data.taxPeriods.forEach(r=>row(taxPdfPad(v(r,'Jurisdiction')||'Jurisdiction',34)+taxPdfPad(dateOnly(v(r,'Period Start'))+' to '+dateOnly(v(r,'Period End')),26)+taxPdfRight(usd(v(r,'Estimated Liability')),14)));
  }else body('No tax periods were prepared in the Office for '+year+'.');
  body('No tax return is filed and no tax payment is initiated by the Office.');

  /* 10. Missing documents checklist */
  head('10. Missing Documents Checklist');
  if(miss.length)miss.forEach((x,i)=>row(taxPdfPad(String(i+1)+'. ['+x.area+']',18)+x.item));
  else body('No missing documents found — everything the Office tracks is on file.');
  L.push({t:'',font:'H',size:9.5,gap:16});
  taxPdfWrap('Prepared from H38 Business Office records on '+prepared+'. Figures are drafts for professional verification - confirm categorization, depreciation, inventory, and payroll tax filings with your accountant before filing. The Office prepares; it never files a return.',100).forEach(t=>body(t));
  L.push({t:'',font:'H',size:9.5,gap:16});
  row(taxPdfPad('Owner signature / date',37)+'   '+taxPdfPad('Accountant signature / date',37));
  row(taxPdfPad('__________________________',37)+'   '+taxPdfPad('__________________________',37));
  return {lines:L,biz,year};
}

/* ---------- Direct PDF export (no print dialog, no external library) ----------
 * Same hand-rolled PDF writer as tax-packet.js: Helvetica / Courier, US letter,
 * footer with page numbers. */

function cpaPdfString(year){
  const {lines}=cpaPdfLines(year);
  const pageW=612,pageH=792,margin=54,topY=726,bottomY=60;
  const heights=l=>Math.round(l.size*1.5)+(l.gap||0);
  const pages=[[]];let y=topY;
  for(const line of lines){const h=heights(line);if(y-h<bottomY&&pages[pages.length-1].length){pages.push([]);y=topY;}pages[pages.length-1].push({line,y});y-=h;}
  const fontFor=l=>(l.font==='C'?(l.bold?'/F4':'/F3'):(l.bold?'/F2':'/F1'));
  const contents=pages.map((items,idx)=>{
    const ops=['0.4 g','BT /F1 7.5 Tf '+margin+' 36 Td ('+taxPdfEscape('H38 Business Office - CPA Package '+year+' - Page '+(idx+1)+' of '+pages.length)+') Tj ET','0 g'];
    for(const {line,y:ly} of items){if(!line.t)continue;ops.push('BT '+fontFor(line)+' '+line.size+' Tf '+margin+' '+ly+' Td ('+taxPdfEscape(line.t)+') Tj ET');}
    return ops.join('\n');
  });
  const objects=[];
  objects[1]='<< /Type /Catalog /Pages 2 0 R >>';
  const kids=contents.map((_,i)=>String(7+i*2)+' 0 R').join(' ');
  objects[2]='<< /Type /Pages /Kids ['+kids+'] /Count '+contents.length+' >>';
  objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';
  objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>';
  objects[5]='<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>';
  objects[6]='<< /Type /Font /Subtype /Type1 /BaseFont /Courier-Bold >>';
  contents.forEach((content,i)=>{
    objects[7+i*2]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+pageW+' '+pageH+'] /Resources << /Font << /F1 3 0 R /F2 4 0 R /F3 5 0 R /F4 6 0 R >> >> /Contents '+(8+i*2)+' 0 R >>';
    objects[8+i*2]='<< /Length '+content.length+' >>\nstream\n'+content+'\nendstream';
  });
  let pdf='%PDF-1.4\n';const offsets=[0];
  for(let n=1;n<objects.length;n++){offsets[n]=pdf.length;pdf+=n+' 0 obj\n'+objects[n]+'\nendobj\n';}
  const xrefPos=pdf.length;
  pdf+='xref\n0 '+objects.length+'\n0000000000 65535 f \n';
  for(let n=1;n<objects.length;n++)pdf+=String(offsets[n]).padStart(10,'0')+' 00000 n \n';
  pdf+='trailer\n<< /Size '+objects.length+' /Root 1 0 R >>\nstartxref\n'+xrefPos+'\n%%EOF';
  return pdf;
}

function downloadCpaPackagePdf(year){
  year=year==null?cpaPackageYear():year;
  try{
    const text=cpaPdfString(year);
    const bytes=new Uint8Array(text.length);
    for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i)&0xff;
    const blob=new Blob([bytes],{type:'application/pdf'});
    const url=URL.createObjectURL(blob);
    const anchor=document.createElement('a');
    anchor.href=url;anchor.download='H38-CPA-Package-'+year+'.pdf';
    document.body.appendChild(anchor);anchor.click();anchor.remove();
    setTimeout(()=>URL.revokeObjectURL(url),4000);
    toast('CPA package PDF downloaded. Give it to your accountant for verification and filing.');
  }catch(error){
    toast('CPA package export failed: '+(error&&error.message?error.message:String(error)),true);
  }
}
window.downloadCpaPackagePdf=downloadCpaPackagePdf;

window.H38CpaPackage={
  version:'20261011-cpa-package-1',
  generate:function(year){return downloadCpaPackagePdf(year==null?cpaPackageYear():year);},
  data:cpaPackageData,
  balanceSheet:cpaBalanceSheet,
  cashFlow:cpaCashFlow,
  salesTax:cpaSalesTax,
  missingDocs:cpaMissingDocs
};

/* ---------- Wire into the Tax Center page ----------
 * RenderTaxPrep (app-19.js) is wrapped so the CPA card renders right after
 * the Accountant Tax Packet card. Same pattern as accounting-workspace.js. */

(function cpaPackageInit(){
  if(typeof window==='undefined')return;
  function install(){
    const orig=window.renderTaxPrep;
    if(typeof orig!=='function'){setTimeout(install,500);return;}
    window.renderTaxPrep=function(){
      orig.apply(this,arguments);
      try{
        const anchor=document.getElementById('h38-tax-packet');
        if(anchor&&!document.getElementById('h38-cpa-package'))anchor.insertAdjacentHTML('afterend',cpaPackageSection());
        else if(!document.getElementById('h38-cpa-package')){
          const grid=document.querySelector('#mainContent .grid');
          if(grid)grid.insertAdjacentHTML('beforeend',cpaPackageSection());
        }
        bindCpaPackage();
      }catch(e){if(typeof console!=='undefined')console.warn('CPA package section:',e&&e.message||e);}
    };
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);
  else install();
})();
;

/* --- ./reports-section.js --- */
/* H38 Office — Reports Section (v1.0)
 * Operational business reports generated from Office records:
 * Profit & Loss, Revenue by Customer, Outstanding Invoices (Aging),
 * Quote Win/Loss, Labor Summary, Year-End Tax Summary.
 * Manual-first, no AI. Date-range picker, print-friendly, CSV export.
 * Replaces the basic renderReports in app-19.js with the full version.
 */
(function(){
  'use strict';
  if(typeof window==='undefined'||typeof document==='undefined')return;
  const BUILD='20261011-reports-section-1';

  // ---------- helpers (match Office conventions) ----------
  const $=id=>document.getElementById(id);
  const t=v=>String(v==null?'':v).trim();
  const n=v=>{const x=Number(v);return Number.isFinite(x)?x:0;};
  const esc=v=>t(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n(v));
  const day=v=>t(v).slice(0,10);
  const rows=name=>Array.isArray(window.state?.snapshot?.[name])?window.state.snapshot[name]:[];
  const rec=(row,...keys)=>{for(const k of keys)if(t(row?.[k]))return t(row[k]);return '';};
  const recN=(row,...keys)=>{for(const k of keys){const x=Number(row?.[k]);if(Number.isFinite(x))return x;}return 0;};
  const inRange=(value,start,end)=>{const d=day(value);if(!d)return false;return(!start||d>=start)&&(!end||d<=end);};
  const notVoid=row=>!/VOID|DELET/i.test(t(rec(row,'Status')));
  const businessName=()=>t(window.state?.snapshot?.business?.['Business Name']||window.state?.snapshot?.business?.businessName||'Your business');

  // ---------- date ranges ----------
  function rangeFor(preset,customStart,customEnd){
    const now=new Date(),y=now.getFullYear(),m=now.getMonth();
    const iso=d=>d.toISOString().slice(0,10);
    const first=m2=>new Date(y,m2,1), last=m2=>new Date(y,m2+1,0);
    switch(preset){
      case 'this-month': return {start:iso(first(m)),end:iso(last(m)),label:'This month'};
      case 'last-month':{const lm=m===0?11:m-1,ly=m===0?y-1:y;return{start:new Date(ly,lm,1).toISOString().slice(0,10),end:new Date(ly,lm+1,0).toISOString().slice(0,10),label:'Last month'};}
      case 'this-quarter':{const q=Math.floor(m/3);return{start:iso(first(q*3)),end:iso(last(q*3+2)),label:'This quarter'};}
      case 'this-year': return {start:`${y}-01-01`,end:`${y}-12-31`,label:'This year'};
      case 'last-year': return {start:`${y-1}-01-01`,end:`${y-1}-12-31`,label:'Last year'};
      case 'custom': return {start:customStart||'',end:customEnd||'',label:'Custom range'};
      default: return {start:iso(first(m)),end:iso(last(m)),label:'This month'};
    }
  }

  // ---------- state ----------
  const S={tab:'pl',preset:'this-month',start:'',end:'',label:''};
  function currentRange(){
    const r=rangeFor(S.preset,S.start,S.end);
    return {start:r.start||S.start,end:r.end||S.end,label:r.label};
  }

  // ---------- report data builders ----------
  function plData(start,end){
    const inv=rows('invoices').filter(r=>inRange(rec(r,'Invoice Date','Created Time'),start,end)&&notVoid(r));
    const pay=rows('payments').filter(r=>inRange(rec(r,'Payment Date','Created Time'),start,end)&&notVoid(r));
    const exp=rows('expenses').filter(r=>inRange(rec(r,'Expense Date','Created Time'),start,end));
    const payroll=rows('payrollPeriods').filter(r=>inRange(rec(r,'Pay Date','Period End','Created Time'),start,end));
    const revenue=pay.reduce((s,r)=>s+recN(r,'Amount'),0);
    const invoiced=inv.reduce((s,r)=>s+recN(r,'Total'),0);
    const expenses=exp.reduce((s,r)=>s+recN(r,'Amount')+recN(r,'Tax'),0);
    const labor=payroll.reduce((s,r)=>s+recN(r,'Gross Pay'),0);
    const net=revenue-expenses-labor;
    // expenses by category
    const cats={};
    exp.forEach(r=>{const c=rec(r,'Category')||'Uncategorized';cats[c]=(cats[c]||0)+recN(r,'Amount')+recN(r,'Tax');});
    const catRows=Object.entries(cats).sort((a,b)=>b[1]-a[1]);
    return {revenue,invoiced,expenses,labor,net,catRows,invCount:inv.length,payCount:pay.length,expCount:exp.length};
  }

  function revenueByCustomer(start,end){
    const customers=rows('customers');
    const name=id=>{const c=customers.find(r=>t(rec(r,'Customer ID'))===t(id));return rec(c,'Customer Name')||'Unknown customer';};
    const pay=rows('payments').filter(r=>inRange(rec(r,'Payment Date','Created Time'),start,end)&&notVoid(r));
    const per={};
    pay.forEach(r=>{
      const inv=rows('invoices').find(i=>t(rec(i,'Invoice ID'))===t(rec(r,'Invoice ID')));
      const cid=rec(inv,'Customer ID')||rec(r,'Customer ID')||'unknown';
      per[cid]=per[cid]||{name:name(cid),total:0,count:0};
      per[cid].total+=recN(r,'Amount');per[cid].count++;
    });
    return Object.values(per).sort((a,b)=>b.total-a.total);
  }

  function arAging(){
    const today=new Date().toISOString().slice(0,10);
    const inv=rows('invoices').filter(r=>notVoid(r)&&recN(r,'Balance')>0);
    const customers=rows('customers');
    const name=id=>{const c=customers.find(r=>t(rec(r,'Customer ID'))===t(id));return rec(c,'Customer Name')||'—';};
    const buckets={'0-30':[],'31-60':[],'61-90':[],'90+':[]};
    inv.forEach(r=>{
      const due=day(rec(r,'Due Date'))||day(rec(r,'Invoice Date','Created Time'));
      const daysDue=due?Math.floor((new Date(today)-new Date(due))/86400000):0;
      const b=daysDue<=30?'0-30':daysDue<=60?'31-60':daysDue<=90?'61-90':'90+';
      buckets[b].push({number:rec(r,'Invoice Number')||rec(r,'Invoice ID'),customer:name(rec(r,'Customer ID')),due:due||'—',balance:recN(r,'Balance'),total:recN(r,'Total')});
    });
    const totals={};for(const k in buckets)totals[k]=buckets[k].reduce((s,x)=>s+x.balance,0);
    return {buckets,totals,grand:Object.values(totals).reduce((a,b)=>a+b,0)};
  }

  function winLoss(start,end){
    const quotes=rows('quotes').filter(r=>inRange(rec(r,'Created Time'),start,end));
    const won=quotes.filter(r=>/accept|approve|won/i.test(rec(r,'Status')));
    const lost=quotes.filter(r=>/declin|lost|reject|cancel/i.test(rec(r,'Status')));
    const pending=quotes.filter(r=>!/accept|approve|won|declin|lost|reject|cancel/i.test(rec(r,'Status')));
    const sent=won.length+lost.length;
    const rate=sent?Math.round(won.length/sent*100):0;
    const wonValue=won.reduce((s,r)=>s+recN(r,'Total'),0);
    const lostValue=lost.reduce((s,r)=>s+recN(r,'Total'),0);
    const pendingValue=pending.reduce((s,r)=>s+recN(r,'Total'),0);
    return {total:quotes.length,won:won.length,lost:lost.length,pending:pending.length,rate,wonValue,lostValue,pendingValue,
      detail:quotes.map(r=>({title:rec(r,'Project Title')||'Untitled quote',number:rec(r,'Quote Number')||rec(r,'Quote ID'),status:rec(r,'Status')||'Draft',total:recN(r,'Total')})).slice(0,100)};
  }

  function laborSummary(start,end){
    const time=rows('timeEntries').filter(r=>inRange(rec(r,'Start Time','Created Time'),start,end));
    const users=rows('users'),employees=rows('employees');
    const name=id=>{
      const u=users.find(r=>t(rec(r,'User ID'))===t(id))||employees.find(r=>t(rec(r,'Employee ID'))===t(id));
      return rec(u,'Display Name','Employee Name','Email')||'Unknown';
    };
    const per={};
    time.forEach(r=>{
      const id=rec(r,'User ID')||rec(r,'Employee ID')||'unknown';
      const h=recN(r,'Hours')||recN(r,'Regular Hours')+recN(r,'Overtime Hours');
      per[id]=per[id]||{name:name(id),hours:0,entries:0};
      per[id].hours+=h;per[id].entries++;
    });
    const list=Object.values(per).sort((a,b)=>b.hours-a.hours);
    const totalHours=list.reduce((s,x)=>s+x.hours,0);
    return {list,totalHours,entryCount:time.length};
  }

  function taxSummary(year){
    const start=`${year}-01-01`,end=`${year}-12-31`;
    const pl=plData(start,end);
    const exp=rows('expenses').filter(r=>inRange(rec(r,'Expense Date','Created Time'),start,end));
    const cats={};
    exp.forEach(r=>{const c=rec(r,'Category')||'Uncategorized';cats[c]=(cats[c]||0)+recN(r,'Amount')+recN(r,'Tax');});
    const catRows=Object.entries(cats).sort((a,b)=>b[1]-a[1]);
    const mileage=rows('mileageLog').filter(r=>inRange(rec(r,'Date','Created Time'),start,end));
    const miles=mileage.reduce((s,r)=>s+recN(r,'Miles','Distance'),0);
    const subs=rows('subcontractorPayments').filter(r=>inRange(rec(r,'Payment Date','Created Time'),start,end));
    const subTotal=subs.reduce((s,r)=>s+recN(r,'Amount'),0);
    return {...pl,catRows,year,miles,subTotal,subCount:subs.length};
  }

  // ---------- CSV export ----------
  function downloadCSV(filename,headers,rowsArr){
    const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;
    const csv=[headers.map(q).join(','),...rowsArr.map(r=>r.map(q).join(','))].join('\r\n');
    const blob=new Blob([csv],{type:'text/csv'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);a.download=filename;
    document.body.appendChild(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(a.href),5000);
    window.toast?.('Report downloaded as CSV.');
  }

  // ---------- print ----------
  function printReport(){
    const el=$('h38-reports-print');
    if(!el){window.toast?.('Nothing to print yet.',true);return;}
    const w=window.open('','_blank','width=900,height=700');
    if(!w){window.toast?.('Allow pop-ups to open the printable report.',true);return;}
    const r=currentRange();
    w.document.write(`<!doctype html><html><head><title>Report — ${esc(r.label)}</title><style>
      body{font:14px/1.5 system-ui,-apple-system,sans-serif;margin:32px;max-width:900px;color:#111}
      h1{font-size:22px;margin:0 0 4px}h2{font-size:17px;margin:24px 0 8px;border-bottom:2px solid #111;padding-bottom:4px}
      .meta{color:#555;margin-bottom:16px}table{width:100%;border-collapse:collapse;margin:8px 0}
      th,td{text-align:left;padding:8px 10px;border-bottom:1px solid #ddd}
      th{background:#f3f4f6;font-size:12px;text-transform:uppercase;letter-spacing:.04em}
      td.num,th.num{text-align:right}.total td{font-weight:700;border-top:2px solid #111}
      .stats{display:flex;gap:24px;flex-wrap:wrap;margin:12px 0}
      .stats div strong{display:block;font-size:20px}.stats div span{font-size:12px;color:#555}
      .foot{margin-top:32px;color:#777;font-size:12px;border-top:1px solid #ddd;padding-top:12px}
    </style></head><body>
    <h1>${esc(businessName())}</h1><div class="meta">${esc(S.reportTitle||'Business report')} · ${esc(r.label)}${r.start&&r.end?` (${esc(r.start)} to ${esc(r.end)})`:''} · Prepared ${esc(new Date().toLocaleDateString())}</div>
    ${el.innerHTML}
    <div class="foot">Prepared from H38 Office records. Review with your accountant before filing or making tax decisions.</div>
    </body></html>`);
    w.document.close();w.focus();
    setTimeout(()=>w.print(),300);
  }

  // ---------- render helpers ----------
  function stat(label,value){return `<div class="stat"><strong>${value}</strong><span>${esc(label)}</span></div>`;}
  function table(headers,rowsHtml,footHtml){
    return `<div class="h38-report-table-wrap"><table class="h38-report-table"><thead><tr>${headers.map(h=>`<th class="${/amount|total|balance|hours|rate|value/i.test(h)?'num':''}">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rowsHtml||'<tr><td colspan="99" class="muted">No records for this period.</td></tr>'}</tbody>${footHtml?`<tfoot>${footHtml}</tfoot>`:''}</table></div>`;
  }
  function numCell(v){return `<td class="num">${money(v)}</td>`;}

  // ---------- tab bodies ----------
  function bodyPL(r){
    const d=plData(r.start,r.end);
    S.reportTitle='Profit & Loss';
    const html=`
    <div class="stats">
      ${stat('Money in (payments)',money(d.revenue))}
      ${stat('Expenses',money(d.expenses))}
      ${stat('Payroll gross',money(d.labor))}
      ${stat('Net',money(d.net))}
    </div>
    ${table(['Line','Amount'],`
      <tr><td>Payments received</td>${numCell(d.revenue)}</tr>
      <tr><td>Invoices sent (billed)</td>${numCell(d.invoiced)}</tr>
      <tr><td>Expenses</td>${numCell(-d.expenses)}</tr>
      <tr><td>Payroll</td>${numCell(-d.labor)}</tr>`,
      `<tr class="total"><td>Net</td>${numCell(d.net)}</tr>`)}
    <h3>Expenses by category</h3>
    ${table(['Category','Amount'],d.catRows.map(([c,v])=>`<tr><td>${esc(c)}</td>${numCell(v)}</tr>`).join(''))}`;
    return {html,csv:()=>downloadCSV(`profit-loss-${r.start}-to-${r.end}.csv`,
      ['Line','Amount'],
      [['Payments received',d.revenue.toFixed(2)],['Invoices sent',d.invoiced.toFixed(2)],['Expenses',(-d.expenses).toFixed(2)],['Payroll',(-d.labor).toFixed(2)],['Net',d.net.toFixed(2)],
       [],['Expenses by category',''],...d.catRows.map(([c,v])=>[c,v.toFixed(2)])])};
  }

  function bodyRevenue(r){
    const list=revenueByCustomer(r.start,r.end);
    const total=list.reduce((s,x)=>s+x.total,0);
    S.reportTitle='Revenue by Customer';
    const html=`
    <div class="stats">${stat('Total received',money(total))}${stat('Paying customers',String(list.length))}</div>
    ${table(['Customer','Payments','Total'],list.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${x.count}</td>${numCell(x.total)}</tr>`).join(''),
      `<tr class="total"><td>Total</td><td class="num">${list.reduce((s,x)=>s+x.count,0)}</td>${numCell(total)}</tr>`)}`;
    return {html,csv:()=>downloadCSV(`revenue-by-customer-${r.start}-to-${r.end}.csv`,
      ['Customer','Payments','Total'],[...list.map(x=>[x.name,x.count,x.total.toFixed(2)]),['Total',list.reduce((s,x)=>s+x.count,0),total.toFixed(2)]])};
  }

  function bodyAR(){
    const d=arAging();
    S.reportTitle='Outstanding Invoices — Aging';
    const labels={'0-30':'0–30 days','31-60':'31–60 days','61-90':'61–90 days','90+':'Over 90 days'};
    const order=['0-30','31-60','61-90','90+'];
    const html=`
    <div class="stats">${stat('Total outstanding',money(d.grand))}${stat('Open invoices',String(order.reduce((s,k)=>s+d.buckets[k].length,0)))}</div>
    ${order.map(k=>`
      <h3>${labels[k]} — ${money(d.totals[k])}</h3>
      ${table(['Invoice','Customer','Due','Balance'],d.buckets[k].map(x=>`<tr><td>${esc(x.number)}</td><td>${esc(x.customer)}</td><td>${esc(x.due)}</td>${numCell(x.balance)}</tr>`).join(''))}`).join('')}`;
    return {html,csv:()=>downloadCSV(`ar-aging-${new Date().toISOString().slice(0,10)}.csv`,
      ['Bucket','Invoice','Customer','Due','Balance'],
      order.flatMap(k=>d.buckets[k].map(x=>[labels[k],x.number,x.customer,x.due,x.balance.toFixed(2)])))};
  }

  function bodyWinLoss(r){
    const d=winLoss(r.start,r.end);
    S.reportTitle='Quote Win / Loss';
    const html=`
    <div class="stats">
      ${stat('Quotes',String(d.total))}
      ${stat('Won',String(d.won))}
      ${stat('Win rate',d.rate+'%')}
      ${stat('Won value',money(d.wonValue))}
      ${stat('Lost value',money(d.lostValue))}
      ${stat('Pending value',money(d.pendingValue))}
    </div>
    ${table(['Quote','Number','Status','Total'],d.detail.map(x=>`<tr><td>${esc(x.title)}</td><td>${esc(x.number)}</td><td>${esc(x.status)}</td>${numCell(x.total)}</tr>`).join(''))}`;
    return {html,csv:()=>downloadCSV(`quote-win-loss-${r.start}-to-${r.end}.csv`,
      ['Quote','Number','Status','Total'],d.detail.map(x=>[x.title,x.number,x.status,x.total.toFixed(2)]))};
  }

  function bodyLabor(r){
    const d=laborSummary(r.start,r.end);
    S.reportTitle='Labor Summary';
    const html=`
    <div class="stats">${stat('Total hours',d.totalHours.toFixed(1))}${stat('Time entries',String(d.entryCount))}${stat('People',String(d.list.length))}</div>
    ${table(['Person','Entries','Hours'],d.list.map(x=>`<tr><td>${esc(x.name)}</td><td class="num">${x.entries}</td><td class="num">${x.hours.toFixed(1)}</td></tr>`).join(''),
      `<tr class="total"><td>Total</td><td class="num">${d.entryCount}</td><td class="num">${d.totalHours.toFixed(1)}</td></tr>`)}`;
    return {html,csv:()=>downloadCSV(`labor-summary-${r.start}-to-${r.end}.csv`,
      ['Person','Entries','Hours'],[...d.list.map(x=>[x.name,x.entries,x.hours.toFixed(1)]),['Total',d.entryCount,d.totalHours.toFixed(1)]])};
  }

  function bodyTax(){
    const year=new Date().getFullYear();
    const d=taxSummary(year);
    S.reportTitle=`Year-End Tax Summary ${year}`;
    const html=`
    <div class="notice"><strong>For your accountant.</strong> Review these numbers together before filing. The Office does not file tax returns.</div>
    <div class="stats">
      ${stat('Revenue (payments)',money(d.revenue))}
      ${stat('Expenses',money(d.expenses))}
      ${stat('Payroll',money(d.labor))}
      ${stat('Net',money(d.net))}
    </div>
    <h3>Expenses by category</h3>
    ${table(['Category','Amount'],d.catRows.map(([c,v])=>`<tr><td>${esc(c)}</td>${numCell(v)}</tr>`).join(''))}
    <h3>Other tax items</h3>
    ${table(['Item','Value'],`
      <tr><td>Business miles driven</td><td class="num">${d.miles.toFixed(1)}</td></tr>
      <tr><td>Subcontractor payments (${d.subCount})</td>${numCell(d.subTotal)}</tr>
      <tr><td>Invoices sent (billed, may include unpaid)</td>${numCell(d.invoiced)}</tr>`)}`;
    return {html,csv:()=>downloadCSV(`tax-summary-${year}.csv`,
      ['Item','Value'],
      [['Revenue (payments)',d.revenue.toFixed(2)],['Expenses',d.expenses.toFixed(2)],['Payroll',d.labor.toFixed(2)],['Net',d.net.toFixed(2)],
       [],['Expenses by category',''],...d.catRows.map(([c,v])=>[c,v.toFixed(2)]),
       [],['Business miles',d.miles.toFixed(1)],['Subcontractor payments',d.subTotal.toFixed(2)]])};
  }

  // mutable slot for the active tab's CSV exporter (kept outside the frozen export)
  let currentCsv=null;
  const TABS=[
    {id:'pl',label:'Profit & Loss'},
    {id:'revenue',label:'Revenue by Customer'},
    {id:'ar',label:'Aging'},
    {id:'winloss',label:'Win / Loss'},
    {id:'labor',label:'Labor'},
    {id:'tax',label:'Tax Summary'},
  ];

  function render(){
    const r=currentRange();
    const builders={pl:()=>bodyPL(r),revenue:()=>bodyRevenue(r),ar:()=>bodyAR(),winloss:()=>bodyWinLoss(r),labor:()=>bodyLabor(r),tax:()=>bodyTax()};
    let built;
    try{built=builders[S.tab]();}catch(e){built={html:`<div class="notice warn"><strong>Report failed to load:</strong> ${esc(e.message||e)}</div>`,csv:null};}
    currentCsv=built.csv;
    const main=$('mainContent');
    if(!main)return;
    main.innerHTML=(typeof window.pageHead==='function'?window.pageHead('Reports','Plain-language summaries from your Office records. Nothing here files anything or moves money.'):'<h1>Reports</h1>')+`
    <style>
      .h38-rep-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}
      .h38-rep-tabs button{border:1px solid #cbd5e1;background:#fff;border-radius:999px;padding:8px 14px;font-size:14px;cursor:pointer}
      .h38-rep-tabs button.active{background:#0f172a;color:#fff;border-color:#0f172a}
      .h38-rep-range{display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin:4px 0 12px}
      .h38-rep-range label{display:grid;gap:2px;font-size:13px}
      .h38-rep-range select,.h38-rep-range input{padding:8px;border:1px solid #cbd5e1;border-radius:8px;font-size:14px}
      .h38-report-table-wrap{overflow-x:auto;margin:8px 0}
      table.h38-report-table{width:100%;border-collapse:collapse;min-width:480px}
      table.h38-report-table th,table.h38-report-table td{padding:9px 10px;border-bottom:1px solid #e2e8f0;text-align:left;font-size:14px}
      table.h38-report-table th{background:#f8fafc;font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:#475569}
      table.h38-report-table td.num,table.h38-report-table th.num{text-align:right;font-variant-numeric:tabular-nums}
      table.h38-report-table tfoot td{font-weight:700;border-top:2px solid #0f172a}
      #h38-reports-print h3{margin:20px 0 6px;font-size:16px}
      .h38-rep-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
      @media(max-width:640px){
        .h38-rep-tabs button{font-size:13px;padding:7px 11px}
        table.h38-report-table th,table.h38-report-table td{padding:7px 8px;font-size:13px}
      }
    </style>
    <div class="grid"><section class="card span12">
      <div class="h38-rep-tabs" role="tablist">${TABS.map(x=>`<button type="button" role="tab" data-rep-tab="${x.id}" class="${S.tab===x.id?'active':''}" aria-selected="${S.tab===x.id}">${esc(x.label)}</button>`).join('')}</div>
      <div class="h38-rep-range">
        <label>Period
          <select id="h38-rep-preset">
            <option value="this-month"${S.preset==='this-month'?' selected':''}>This month</option>
            <option value="last-month"${S.preset==='last-month'?' selected':''}>Last month</option>
            <option value="this-quarter"${S.preset==='this-quarter'?' selected':''}>This quarter</option>
            <option value="this-year"${S.preset==='this-year'?' selected':''}>This year</option>
            <option value="last-year"${S.preset==='last-year'?' selected':''}>Last year</option>
            <option value="custom"${S.preset==='custom'?' selected':''}>Custom</option>
          </select>
        </label>
        <label style="${S.preset==='custom'?'':'display:none'}" id="h38-rep-custom-start-wrap">Start <input type="date" id="h38-rep-start" value="${esc(S.start)}"></label>
        <label style="${S.preset==='custom'?'':'display:none'}" id="h38-rep-custom-end-wrap">End <input type="date" id="h38-rep-end" value="${esc(S.end)}"></label>
        <span class="muted small" style="align-self:center">${esc(r.label)}${r.start&&r.end?`: ${esc(r.start)} → ${esc(r.end)}`:''}</span>
      </div>
      <div id="h38-reports-print">${built.html}</div>
      <div class="h38-rep-actions">
        <button type="button" id="h38-rep-print">🖨 Print</button>
        <button type="button" class="secondary" id="h38-rep-csv">⬇ Download CSV</button>
      </div>
      <p class="muted small" style="margin-top:10px">Built live from this business's Office records. Estimates only — review with your accountant before tax filing.</p>
    </section></div>`;
    // wire tabs
    main.querySelectorAll('[data-rep-tab]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.repTab;render();});
    // wire preset
    const preset=$('h38-rep-preset');
    preset.onchange=()=>{
      S.preset=preset.value;
      if(S.preset!=='custom'){render();}
      else{
        $('h38-rep-custom-start-wrap').style.display='';
        $('h38-rep-custom-end-wrap').style.display='';
        const r2=rangeFor('this-month');S.start=r2.start;S.end=r2.end;
        $('h38-rep-start').value=S.start;$('h38-rep-end').value=S.end;render();
      }
    };
    const cs=$('h38-rep-start'),ce=$('h38-rep-end');
    if(cs)cs.onchange=()=>{S.start=cs.value;render();};
    if(ce)ce.onchange=()=>{S.end=ce.value;render();};
    $('h38-rep-print').onclick=printReport;
    $('h38-rep-csv').onclick=()=>{const f=currentCsv;if(typeof f==='function')f();else window.toast?.('Nothing to download yet.',true);};
  }

  // ---------- override ----------
  // app-19.js defines a global renderReports; app-02.js resolves it per render call,
  // so replacing the global is enough. Also expose for app-19's parity path.
  try{renderReports=render;}catch(e){window.renderReports=render;}
  window.H38ReportsSection=Object.freeze({enabled:true,build:BUILD,render,printReport});
})();
;

/* --- ./route-manager.js --- */
/* ============================================================================
 * H38 Route Manager — Route planning, crew check-ins, proof of service
 * ----------------------------------------------------------------------------
 * Routes with ordered stops for any trade (plow routes, service routes,
 * delivery runs). Works WITHOUT GPS hardware:
 *
 *   1. Owner builds routes: ordered customer stops, assigned to crew
 *   2. Crew checks in per stop: Arrived -> Done (photo + timestamp)
 *   3. Owner sees green/yellow/red completion across all routes
 *   4. Proof of service: per-stop timestamps, photos, notes, shareable link
 *   5. Bouncie: if connected, live vehicle positions overlay on the route map
 *
 * POSITIONING (do not contradict in UI):
 *   - Live phone tracking is "Coming soon" — never imply it works.
 *   - Routes, check-ins, and proof-of-service are the core offering.
 *   - Bouncie integration is the live vehicle path.
 *
 * Owner Controls: id-guarded registration of 'route_management' (default OFF).
 * Data: business_records collections 'routes' and 'routeStops' via queueOperation.
 * Map: Leaflet + OpenStreetMap, loaded on demand (same pattern as gps-dispatch).
 * ========================================================================== */
(function() {
'use strict';
if (typeof window === 'undefined') return;

var BUILD = '20261011-route-manager-1';
var ROUTES_COLLECTION = 'routes';
var STOPS_COLLECTION = 'routeStops';
var FEATURE_ID = 'route_management';

var w = window;

/* ---------- helpers ---------- */
function text(v) { return String(v == null ? '' : v).trim(); }
function esc(s) {
  if (typeof w.esc === 'function') return w.esc(s);
  return text(s).replace(/[&<>"']/g, function(c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
  });
}
function v(row) {
  var keys = Array.prototype.slice.call(arguments, 1);
  if (typeof w.v === 'function') return w.v.apply(w, [row].concat(keys));
  for (var i = 0; i < keys.length; i++) {
    var k = keys[i];
    if (row && row[k] !== undefined && row[k] !== null && row[k] !== '') return row[k];
  }
  return '';
}
function num(x) {
  if (typeof w.num === 'function') return w.num(x);
  var n = Number(x); return Number.isFinite(n) ? n : 0;
}
function nowIso() {
  if (typeof w.now === 'function') return w.now();
  return new Date().toISOString();
}
function toast(msg, bad) {
  if (typeof w.toast === 'function') w.toast(msg, bad);
  else if (bad) console.warn('[RouteManager]', msg); else console.log('[RouteManager]', msg);
}
function newId(prefix) {
  if (typeof w.newId === 'function') return w.newId(prefix);
  return prefix + '-' + Math.random().toString(36).slice(2, 10).toUpperCase() + Date.now().toString(36).toUpperCase();
}
function records(name) {
  if (typeof w.records === 'function') return w.records(name) || [];
  var s = w.state || {};
  return (s.snapshot && s.snapshot[name]) || [];
}
function businessId() { return text((w.state && w.state.businessId) || ''); }
function currentUser() {
  var s = w.state || {}, u = (s.snapshot && s.snapshot.user) || {};
  return u;
}
function currentUserId() {
  var u = currentUser();
  return text(v(u, 'User ID', 'userId') || u.id || '');
}
function currentUserName() {
  var u = currentUser();
  return text(v(u, 'Name', 'Full Name', 'Display Name', 'userName') || u.name || u.email || 'Crew');
}
function isOwner() {
  try {
    var u = currentUser();
    var role = text(v(u, 'Role', 'role') || '').toLowerCase();
    return role === 'owner' || role === 'administrator' || role === 'admin';
  } catch (_) { return false; }
}

/* ---------- Owner Controls registration (id-guarded; never edit owner-controls.js) ---------- */
var FEATURE_DEF = {
  id: FEATURE_ID,
  title: 'Route management',
  desc: 'Plow/service routes with ordered stops, crew check-ins, and proof of service. Live phone tracking is coming soon — Bouncie vehicles show live when connected.',
  icon: '🗺️',
  default: false,
  category: 'Fleet'
};
function registerFeature() {
  var oc = w.H38OwnerControls;
  if (!oc || !Array.isArray(oc.FEATURES)) return false;
  var exists = oc.FEATURES.some(function(f) { return f && f.id === FEATURE_ID; });
  if (!exists) oc.FEATURES.push(FEATURE_DEF);
  return true;
}
function ocEnabled(id) {
  var oc = w.H38OwnerControls;
  try { if (oc && typeof oc.isEnabled === 'function') return oc.isEnabled(id) === true; } catch (_) {}
  return false;
}
function enabled() { return registerFeature() && ocEnabled(FEATURE_ID) && !!businessId(); }

/* ---------- styles ---------- */
var styleInjected = false;
function ensureStyle() {
  if (styleInjected || typeof document === 'undefined') return;
  styleInjected = true;
  var css = [
    '.h38-route-card{margin-bottom:16px}',
    '.h38-route-list{display:grid;gap:10px}',
    '.h38-route-item{border:1px solid var(--border,#e2e2e2);border-radius:12px;padding:14px;background:var(--card,#fff)}',
    '.h38-route-item .row-top{display:flex;justify-content:space-between;align-items:flex-start;gap:8px}',
    '.h38-route-progress{height:8px;border-radius:4px;background:#eee;margin-top:8px;overflow:hidden}',
    '.h38-route-progress>div{height:100%;border-radius:4px;background:#2e7d32;transition:width .3s}',
    '.h38-route-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}',
    '.h38-route-actions button{min-height:44px;padding:10px 14px;font-size:1em;border-radius:10px}',
    '.h38-route-map{height:340px;border-radius:12px;border:1px solid var(--border,#e2e2e2);background:#eef2f5;margin:12px 0}',
    '.h38-stop{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--border,#e2e2e2);border-radius:12px;padding:12px;margin-bottom:8px;background:var(--card,#fff)}',
    '.h38-stop-dot{flex:none;width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;font-size:.9em}',
    '.h38-stop-dot.pending{background:#9e9e9e}',
    '.h38-stop-dot.arrived{background:#f9a825}',
    '.h38-stop-dot.done{background:#2e7d32}',
    '.h38-stop-dot.missed{background:#c62828}',
    '.h38-stop-body{flex:1;min-width:0}',
    '.h38-stop-actions{display:flex;gap:8px;margin-top:8px;flex-wrap:wrap}',
    '.h38-stop-actions button{min-height:48px;padding:12px 18px;font-size:1.05em;border-radius:10px;font-weight:600}',
    '.h38-stop-checkin{background:#2e7d32;color:#fff;border:none}',
    '.h38-stop-arrived{background:#f9a825;color:#000;border:none}',
    '.h38-route-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9999;display:flex;align-items:flex-start;justify-content:center;padding:16px;overflow-y:auto}',
    '.h38-route-modal{background:#fff;border-radius:14px;padding:18px;max-width:520px;width:100%;margin:20px 0;max-height:90vh;overflow-y:auto}',
    '.h38-route-modal label{display:block;margin:10px 0 4px;font-weight:600}',
    '.h38-route-modal input,.h38-route-modal select,.h38-route-modal textarea{width:100%;min-height:44px;font-size:1em;border-radius:8px;border:1px solid #ccc;padding:8px 10px;box-sizing:border-box}',
    '.h38-route-modal .actions{display:flex;gap:8px;margin-top:16px}',
    '.h38-route-modal .actions button{min-height:48px;flex:1;font-size:1em;border-radius:10px}',
    '.h38-route-note{font-size:.9em;color:#666;margin-top:6px}',
    '.h38-stop-picker{max-height:220px;overflow-y:auto;border:1px solid #ddd;border-radius:8px;padding:6px}',
    '.h38-stop-picker label{display:flex!important;align-items:center;gap:8px;margin:4px 0!important;font-weight:400!important;min-height:44px;cursor:pointer}',
    '.h38-route-proof{background:#f5f5f5;border-radius:12px;padding:16px;margin:12px 0}',
    '.h38-route-proof h3{margin:0 0 8px}',
    '.h38-proof-link{display:flex;gap:8px;margin-top:8px}',
    '.h38-proof-link input{flex:1;min-height:44px;font-size:.9em}',
    '.h38-coming-soon-note{background:#fff8e1;border:1px solid #ffe082;border-radius:10px;padding:10px 12px;font-size:.9em;margin:12px 0}'
  ].join('\n');
  var el = document.createElement('style');
  el.setAttribute('data-h38-route-manager', '1');
  el.textContent = css;
  document.head.appendChild(el);
}

/* ---------- data layer ---------- */
function allRoutes() {
  return records(ROUTES_COLLECTION).filter(function(r) {
    return !/^(deleted|void|cancelled)$/i.test(text(v(r, 'Status')));
  });
}
function routeById(id) {
  return allRoutes().find(function(r) { return text(v(r, 'Route ID', 'id')) === text(id); }) || null;
}
function stopsForRoute(routeId) {
  return records(STOPS_COLLECTION)
    .filter(function(r) { return text(v(r, 'Route ID')) === text(routeId); })
    .sort(function(a, b) { return num(v(a, 'Stop Order', 'Order')) - num(v(b, 'Stop Order', 'Order')); });
}
function stopStatus(stop) {
  return text(v(stop, 'Status') || 'pending').toLowerCase();
}
function routeProgress(routeId) {
  var stops = stopsForRoute(routeId);
  var done = stops.filter(function(s) { return stopStatus(s) === 'done'; }).length;
  return { total: stops.length, done: done, pct: stops.length ? Math.round(done / stops.length * 100) : 0 };
}
function myRoutes() {
  var uid = currentUserId();
  var all = allRoutes();
  if (isOwner()) return all;
  return all.filter(function(r) {
    return text(v(r, 'Assigned User ID')) === uid || !text(v(r, 'Assigned User ID'));
  });
}

async function saveRoute(data) {
  var id = data.id || newId('ROUTE');
  var stamp = nowIso();
  var record = {
    'Route ID': id,
    'Business ID': businessId(),
    'Route Name': data.name,
    'Route Date': data.date || '',
    'Assigned User ID': data.assignedUserId || '',
    'Assigned Crew Name': data.assignedCrewName || '',
    'Status': data.status || 'planned',
    'Notes': data.notes || '',
    'Proof Token': data.proofToken || ('proof-' + Math.random().toString(36).slice(2, 14)),
    'Created Time': data.createdTime || stamp,
    'Record Version': 1
  };
  await w.queueOperation('SAVE_ROUTE', 'Route', id, {
    routeId: id, name: data.name, date: data.date, assignedUserId: data.assignedUserId,
    status: record['Status'], proofToken: record['Proof Token']
  }, { collection: ROUTES_COLLECTION, record: record, idKeys: ['Route ID'] });
  return id;
}

async function saveStop(routeId, data, order) {
  var id = data.id || newId('RSTOP');
  var stamp = nowIso();
  var record = {
    'Stop ID': id,
    'Business ID': businessId(),
    'Route ID': routeId,
    'Stop Order': order,
    'Customer ID': data.customerId || '',
    'Customer Name': data.customerName || '',
    'Address': data.address || '',
    'Lat': data.lat != null ? data.lat : '',
    'Lng': data.lng != null ? data.lng : '',
    'Status': data.status || 'pending',
    'Arrived At': data.arrivedAt || '',
    'Completed At': data.completedAt || '',
    'Photo': data.photo || '',
    'Checkin Lat': data.checkinLat != null ? data.checkinLat : '',
    'Checkin Lng': data.checkinLng != null ? data.checkinLng : '',
    'Notes': data.notes || '',
    'Created Time': stamp,
    'Record Version': 1
  };
  await w.queueOperation('SAVE_ROUTE_STOP', 'Route Stop', id, {
    stopId: id, routeId: routeId, order: order, status: record['Status']
  }, { collection: STOPS_COLLECTION, record: record, idKeys: ['Stop ID'] });
  return id;
}

async function updateStopStatus(stopRow, status, extra) {
  var id = text(v(stopRow, 'Stop ID'));
  var stamp = nowIso();
  var record = Object.assign({}, stopRow, { 'Status': status, 'Record Version': 1 });
  if (extra) {
    if (extra.arrivedAt) record['Arrived At'] = extra.arrivedAt;
    if (extra.completedAt) record['Completed At'] = extra.completedAt;
    if (extra.photo) record['Photo'] = extra.photo;
    if (extra.notes != null) record['Notes'] = extra.notes;
    if (extra.checkinLat != null) record['Checkin Lat'] = extra.checkinLat;
    if (extra.checkinLng != null) record['Checkin Lng'] = extra.checkinLng;
  }
  await w.queueOperation('SAVE_ROUTE_STOP', 'Route Stop', id, {
    stopId: id, status: status, at: stamp
  }, { collection: STOPS_COLLECTION, record: record, idKeys: ['Stop ID'] });
}

/* ---------- geocoding (best-effort, Nominatim, no key) ---------- */
var geoCache = {};
async function geocode(address) {
  var q = text(address);
  if (!q) return null;
  if (geoCache[q]) return geoCache[q];
  try {
    var url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(q);
    var resp = await fetch(url, { headers: { 'Accept': 'application/json' } });
    if (!resp.ok) return null;
    var data = await resp.json();
    if (data && data[0]) {
      var c = { lat: parseFloat(data[0].lat), lng: parseFloat(data[0].lon) };
      if (Number.isFinite(c.lat) && Number.isFinite(c.lng)) { geoCache[q] = c; return c; }
    }
  } catch (_) {}
  return null;
}

/* ---------- customers / crew lookups ---------- */
function allCustomers() {
  return records('customers').filter(function(c) {
    return !/^(deleted|void|archived)$/i.test(text(v(c, 'Status')));
  });
}
function customerAddress(c) {
  var parts = [
    v(c, 'Address', 'Street', 'Address Line 1'),
    v(c, 'City'), v(c, 'State'), v(c, 'ZIP', 'Zip', 'Postal Code')
  ].map(text).filter(Boolean);
  return parts.join(', ');
}
function customerName(c) {
  return text(v(c, 'Customer Name', 'Name', 'Full Name', 'Business Name')) || 'Customer';
}
function customerIdOf(c) {
  return text(v(c, 'Customer ID', 'customerId', 'id'));
}
function allCrew() {
  var users = records('users');
  if (users.length) return users;
  return records('team').concat(records('employees'));
}
function crewName(u) {
  return text(v(u, 'Name', 'Full Name', 'Display Name')) || text(v(u, 'Email', 'email')) || 'Crew';
}
function crewIdOf(u) {
  return text(v(u, 'User ID', 'userId', 'Employee ID', 'id'));
}

/* ---------- Bouncie vehicles ---------- */
function bouncieVehicles() {
  var out = [];
  records('fleetVehicles').forEach(function(veh) {
    var lat = num(v(veh, 'Latitude', 'latitude', 'Lat', 'lat'));
    var lng = num(v(veh, 'Longitude', 'longitude', 'Lng', 'lng'));
    if (lat && lng) {
      out.push({
        label: text(v(veh, 'Nickname', 'Name', 'Vehicle Name')) ||
               [v(veh, 'Year'), v(veh, 'Make'), v(veh, 'Model')].map(text).filter(Boolean).join(' ') ||
               'Vehicle',
        lat: lat, lng: lng,
        at: text(v(veh, 'Last Known At', 'last_known_at', 'Updated At'))
      });
    }
  });
  return out;
}
function hasBouncie() { return bouncieVehicles().length > 0; }

/* ---------- Leaflet (on demand) ---------- */
var leafletPromise = null;
function loadLeaflet() {
  if (leafletPromise) return leafletPromise;
  leafletPromise = new Promise(function(resolve, reject) {
    if (w.L && w.L.map) { resolve(w.L); return; }
    if (typeof document === 'undefined') { reject(new Error('No document')); return; }
    var css = document.querySelector('link[data-h38-route-leaflet]');
    if (!css) {
      css = document.createElement('link');
      css.rel = 'stylesheet';
      css.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
      css.setAttribute('data-h38-route-leaflet', '1');
      document.head.appendChild(css);
    }
    var s = document.querySelector('script[data-h38-route-leaflet]');
    if (s) {
      s.addEventListener('load', function() { w.L && w.L.map ? resolve(w.L) : reject(new Error('Leaflet failed')); }, { once: true });
      s.addEventListener('error', function() { reject(new Error('Leaflet failed')); }, { once: true });
      return;
    }
    s = document.createElement('script');
    s.src = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';
    s.setAttribute('data-h38-route-leaflet', '1');
    s.onload = function() { w.L && w.L.map ? resolve(w.L) : reject(new Error('Leaflet failed')); };
    s.onerror = function() { reject(new Error('Leaflet failed')); };
    document.head.appendChild(s);
  });
  return leafletPromise;
}

var activeMap = null;
async function renderRouteMap(nodeId, routeId) {
  var node = document.getElementById(nodeId);
  if (!node) return 'no-node';
  var stops = stopsForRoute(routeId);
  var points = stops.map(function(s, i) {
    var lat = num(v(s, 'Lat')), lng = num(v(s, 'Lng'));
    return (lat && lng) ? { stop: s, idx: i, lat: lat, lng: lng } : null;
  }).filter(Boolean);
  var vehicles = bouncieVehicles();
  if (!points.length && !vehicles.length) {
    node.innerHTML = '<div class="h38-route-note" style="padding:16px">No map positions yet. Stops appear here once addresses are geocoded; Bouncie vehicles appear when connected.</div>';
    return 'empty';
  }
  var L;
  try { L = await loadLeaflet(); }
  catch (err) {
    node.innerHTML = '<div class="h38-route-note" style="padding:16px">Map could not load (offline or blocked). The stop list below still works.</div>';
    return 'unavailable';
  }
  if (!node.isConnected) return 'detached';
  try {
    if (activeMap) { try { activeMap.remove(); } catch (_) {} activeMap = null; }
    node.innerHTML = '';
    var map = L.map(node, { zoomControl: true });
    activeMap = map;
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19, attribution: '&copy; OpenStreetMap contributors'
    }).addTo(map);
    var bounds = [];
    var statusColor = { pending: '#9e9e9e', arrived: '#f9a825', done: '#2e7d32', missed: '#c62828' };
    points.forEach(function(p) {
      var st = stopStatus(p.stop);
      var color = statusColor[st] || '#9e9e9e';
      var icon = L.divIcon({
        className: '',
        html: '<span style="display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:' + color + ';border:3px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.4);color:#fff;font-weight:700;font-size:12px">' + (p.idx + 1) + '</span>',
        iconSize: [26, 26], iconAnchor: [13, 13]
      });
      L.marker([p.lat, p.lng], { icon: icon }).addTo(map)
        .bindPopup('<strong>Stop ' + (p.idx + 1) + ': ' + esc(text(v(p.stop, 'Customer Name'))) + '</strong><br>' + esc(text(v(p.stop, 'Address'))) + '<br>Status: ' + esc(st));
      bounds.push([p.lat, p.lng]);
    });
    // Connect stops with a route line
    if (points.length > 1) {
      L.polyline(points.map(function(p) { return [p.lat, p.lng]; }), { weight: 3, opacity: 0.6, color: '#1976d2' }).addTo(map);
    }
    // Bouncie vehicles (live, when connected)
    vehicles.forEach(function(veh) {
      var icon = L.divIcon({
        className: '',
        html: '<span style="display:inline-block;width:20px;height:20px;border-radius:4px;background:#1565c0;border:2px solid #fff;box-shadow:0 1px 4px rgba(0,0,0,.4)"></span>',
        iconSize: [20, 20], iconAnchor: [10, 10]
      });
      L.marker([veh.lat, veh.lng], { icon: icon }).addTo(map)
        .bindPopup('<strong>🚚 ' + esc(veh.label) + '</strong><br>Live vehicle' + (veh.at ? '<br><small>' + esc(veh.at) + '</small>' : ''));
      bounds.push([veh.lat, veh.lng]);
    });
    if (bounds.length === 1) map.setView(bounds[0], 14);
    else map.fitBounds(bounds, { padding: [30, 30], maxZoom: 15 });
    return 'ok';
  } catch (err) {
    node.innerHTML = '<div class="h38-route-note" style="padding:16px">Map failed to render. The stop list below still works.</div>';
    return 'error';
  }
}

/* ---------- UI state ---------- */
var ui = { openRouteId: null, tab: 'routes' };

function fmtTime(iso) {
  var d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
}
function fmtDate(iso) {
  var s = text(iso).slice(0, 10);
  if (!s) return '—';
  var d = new Date(s + 'T12:00:00');
  if (Number.isNaN(d.getTime())) return s;
  return d.toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' });
}
function statusPill(st) {
  var map = { pending: 'Pending', arrived: 'On site', done: 'Done', missed: 'Missed', planned: 'Planned', active: 'Active', completed: 'Completed' };
  return '<span class="pill">' + esc(map[st] || st) + '</span>';
}

/* ---------- fleet page entry ---------- */
function fleetHook() {
  if (typeof document === 'undefined') return;
  var onFleet = text(w.state && w.state.page) === 'fleet';
  var card = document.getElementById('h38RouteManagerEntry');
  if (!onFleet || !enabled()) { if (card) card.remove(); return; }
  ensureStyle();
  var main = document.getElementById('mainContent');
  if (!main) return;
  if (!card) {
    card = document.createElement('section');
    card.className = 'card h38-route-card';
    card.id = 'h38RouteManagerEntry';
    main.prepend(card);
  }
  renderCard(card);
}

function renderCard(card) {
  var routes = myRoutes().sort(function(a, b) {
    return text(v(a, 'Route Date')).localeCompare(text(v(b, 'Route Date')));
  });
  var bouncie = hasBouncie();
  var html = '<div><span class="muted small">ROUTES</span>' +
    '<h2 style="margin:4px 0">Route management</h2>' +
    '<p class="muted">Ordered stops, crew check-ins, proof of service.' +
    (bouncie ? ' 🚚 Live Bouncie vehicles shown on maps.' : '') + '</p></div>';

  if (!bouncie) {
    html += '<div class="h38-coming-soon-note">📍 <strong>Live phone tracking — coming soon.</strong> ' +
      'Connect a tracking device like Bouncie for live vehicle positions on the map.</div>';
  }

  html += '<div class="h38-route-actions" style="margin-bottom:12px">' +
    (isOwner() ? '<button type="button" data-route-new>＋ New route</button>' : '') +
    '</div>';

  if (!routes.length) {
    html += '<p class="muted">No routes yet.' + (isOwner() ? ' Create one to get started.' : ' Your assigned routes will appear here.') + '</p>';
  } else {
    html += '<div class="h38-route-list">' + routes.map(function(r) {
      var id = text(v(r, 'Route ID'));
      var prog = routeProgress(id);
      var st = text(v(r, 'Status') || 'planned').toLowerCase();
      return '<div class="h38-route-item"><div class="row-top"><div>' +
        '<strong>' + esc(text(v(r, 'Route Name')) || 'Route') + '</strong><br>' +
        '<small class="muted">' + esc(fmtDate(v(r, 'Route Date'))) +
        (text(v(r, 'Assigned Crew Name')) ? ' · ' + esc(text(v(r, 'Assigned Crew Name'))) : '') + '</small>' +
        '</div><div>' + statusPill(st) + '</div></div>' +
        '<div class="h38-route-progress"><div style="width:' + prog.pct + '%"></div></div>' +
        '<small class="muted">' + prog.done + '/' + prog.total + ' stops done</small>' +
        '<div class="h38-route-actions">' +
        '<button type="button" data-route-open="' + esc(id) + '">Open</button>' +
        (isOwner() ? '<button type="button" data-route-proof="' + esc(id) + '">Proof link</button>' : '') +
        '</div></div>';
    }).join('') + '</div>';
  }

  card.innerHTML = html;
  bindCard(card);
}

function bindCard(card) {
  card.querySelectorAll('[data-route-new]').forEach(function(b) {
    b.addEventListener('click', function() { openRouteBuilder(null); });
  });
  card.querySelectorAll('[data-route-open]').forEach(function(b) {
    b.addEventListener('click', function() { openRouteDetail(b.getAttribute('data-route-open')); });
  });
  card.querySelectorAll('[data-route-proof]').forEach(function(b) {
    b.addEventListener('click', function() { openProofView(b.getAttribute('data-route-proof')); });
  });
}

/* ---------- route builder (owner) ---------- */
var builderStops = [];
function openRouteBuilder(routeId) {
  if (!isOwner()) { toast('Only owners can create routes.', true); return; }
  ensureStyle();
  builderStops = [];
  var existing = routeId ? routeById(routeId) : null;
  if (existing) {
    builderStops = stopsForRoute(text(v(existing, 'Route ID'))).map(function(s) {
      return {
        customerId: text(v(s, 'Customer ID')), customerName: text(v(s, 'Customer Name')),
        address: text(v(s, 'Address')), lat: num(v(s, 'Lat')) || null, lng: num(v(s, 'Lng')) || null
      };
    });
  }
  var crew = allCrew();
  var overlay = document.createElement('div');
  overlay.className = 'h38-route-overlay';
  overlay.id = 'h38RouteBuilderOverlay';
  overlay.innerHTML =
    '<div class="h38-route-modal" role="dialog" aria-label="Route builder">' +
    '<h2 style="margin-top:0">' + (existing ? 'Edit route' : 'New route') + '</h2>' +
    '<label>Route name</label><input id="rbName" value="' + esc(existing ? text(v(existing, 'Route Name')) : '') + '" placeholder="e.g. Tuesday plow route — North side">' +
    '<label>Date</label><input id="rbDate" type="date" value="' + esc(existing ? text(v(existing, 'Route Date')).slice(0, 10) : new Date().toISOString().slice(0, 10)) + '">' +
    '<label>Assign to crew</label><select id="rbCrew"><option value="">Unassigned</option>' +
    crew.map(function(u) {
      var sel = existing && text(v(existing, 'Assigned User ID')) === crewIdOf(u) ? ' selected' : '';
      return '<option value="' + esc(crewIdOf(u)) + '"' + sel + '>' + esc(crewName(u)) + '</option>';
    }).join('') + '</select>' +
    '<label>Add stops (pick customers in visit order)</label>' +
    '<div class="h38-stop-picker" id="rbPicker">' +
    allCustomers().map(function(c) {
      return '<label><input type="checkbox" data-cust="' + esc(customerIdOf(c)) + '"> ' +
        '<span><strong>' + esc(customerName(c)) + '</strong><br><small class="muted">' + esc(customerAddress(c)) + '</small></span></label>';
    }).join('') + '</div>' +
    '<div id="rbStopList" style="margin-top:8px"></div>' +
    '<div class="actions"><button type="button" data-rb-save style="background:#2e7d32;color:#fff;border:none">Save route</button>' +
    '<button type="button" data-rb-cancel class="secondary">Cancel</button></div>' +
    '<p class="h38-route-note">Stops are geocoded automatically for the map. Crew checks in with one tap per stop — no GPS hardware needed.</p>' +
    '</div>';
  document.body.appendChild(overlay);
  renderBuilderStops();

  overlay.querySelectorAll('[data-cust]').forEach(function(cb) {
    cb.addEventListener('change', function() {
      var c = allCustomers().find(function(x) { return customerIdOf(x) === cb.getAttribute('data-cust'); });
      if (!c) return;
      if (cb.checked) {
        builderStops.push({
          customerId: customerIdOf(c), customerName: customerName(c),
          address: customerAddress(c), lat: null, lng: null
        });
      } else {
        builderStops = builderStops.filter(function(s) { return s.customerId !== customerIdOf(c); });
      }
      renderBuilderStops();
    });
  });
  overlay.querySelector('[data-rb-cancel]').addEventListener('click', function() { overlay.remove(); });
  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
  overlay.querySelector('[data-rb-save]').addEventListener('click', function() { saveBuilderRoute(overlay, existing); });
  // Stop reorder buttons (event delegation)
  overlay.querySelector('#rbStopList').addEventListener('click', function(e) {
    var btn = e.target.closest('[data-stop-move],[data-stop-del]');
    if (!btn) return;
    var i = num(btn.getAttribute('data-idx'));
    if (btn.hasAttribute('data-stop-del')) { builderStops.splice(i, 1); }
    else {
      var dir = num(btn.getAttribute('data-stop-move'));
      var j = i + dir;
      if (j < 0 || j >= builderStops.length) return;
      var tmp = builderStops[i]; builderStops[i] = builderStops[j]; builderStops[j] = tmp;
    }
    renderBuilderStops();
  });
}

function renderBuilderStops() {
  var node = document.getElementById('rbStopList');
  if (!node) return;
  if (!builderStops.length) { node.innerHTML = '<p class="muted small">No stops yet — pick customers above.</p>'; return; }
  node.innerHTML = '<strong>Stops in order (' + builderStops.length + '):</strong>' +
    builderStops.map(function(s, i) {
      return '<div class="h38-stop" style="margin-top:6px"><div class="h38-stop-dot pending">' + (i + 1) + '</div>' +
        '<div class="h38-stop-body"><strong>' + esc(s.customerName) + '</strong><br><small class="muted">' + esc(s.address) + '</small></div>' +
        '<div style="display:flex;flex-direction:column;gap:4px">' +
        '<button type="button" data-stop-move="-1" data-idx="' + i + '" style="min-height:36px">▲</button>' +
        '<button type="button" data-stop-move="1" data-idx="' + i + '" style="min-height:36px">▼</button>' +
        '<button type="button" data-stop-del data-idx="' + i + '" style="min-height:36px">✕</button>' +
        '</div></div>';
    }).join('');
}

async function saveBuilderRoute(overlay, existing) {
  var name = text(overlay.querySelector('#rbName').value);
  var date = text(overlay.querySelector('#rbDate').value);
  var crewSel = overlay.querySelector('#rbCrew');
  var crewId = text(crewSel.value);
  var crewLabel = crewSel.selectedIndex > 0 ? text(crewSel.options[crewSel.selectedIndex].text) : '';
  if (!name) { toast('Give the route a name.', true); return; }
  if (!builderStops.length) { toast('Add at least one stop.', true); return; }
  try {
    toast('Saving route…');
    // Geocode stops (best effort, don't block)
    for (var i = 0; i < builderStops.length; i++) {
      var s = builderStops[i];
      if (s.lat == null && s.address) {
        var c = await geocode(s.address);
        if (c) { s.lat = c.lat; s.lng = c.lng; }
      }
    }
    var routeId;
    if (existing) {
      routeId = text(v(existing, 'Route ID'));
      await saveRoute({
        id: routeId, name: name, date: date, assignedUserId: crewId, assignedCrewName: crewLabel,
        status: text(v(existing, 'Status')) || 'planned',
        notes: text(v(existing, 'Notes')),
        proofToken: text(v(existing, 'Proof Token')),
        createdTime: text(v(existing, 'Created Time'))
      });
      // Replace stops (simplest correct approach for v1)
      var old = stopsForRoute(routeId);
      for (var k = 0; k < old.length; k++) {
        var oid = text(v(old[k], 'Stop ID'));
        await w.queueOperation('SAVE_ROUTE_STOP', 'Route Stop', oid, { stopId: oid, deleted: true }, {
          collection: STOPS_COLLECTION,
          record: Object.assign({}, old[k], { 'Status': 'deleted', 'Record Version': 1 }),
          idKeys: ['Stop ID']
        });
      }
    } else {
      routeId = await saveRoute({ name: name, date: date, assignedUserId: crewId, assignedCrewName: crewLabel, status: 'planned' });
    }
    for (var j = 0; j < builderStops.length; j++) {
      await saveStop(routeId, builderStops[j], j + 1);
    }
    toast('Route saved: ' + name);
    overlay.remove();
    fleetHook();
  } catch (err) {
    toast('Could not save route: ' + text(err && err.message || err), true);
  }
}

/* ---------- route detail ---------- */
function openRouteDetail(routeId) {
  var route = routeById(routeId);
  if (!route) { toast('Route not found.', true); return; }
  ensureStyle();
  var overlay = document.createElement('div');
  overlay.className = 'h38-route-overlay';
  overlay.innerHTML = '<div class="h38-route-modal" role="dialog" aria-label="Route detail" style="max-width:640px">' +
    '<div id="h38RouteDetailBody"></div>' +
    '<div class="actions"><button type="button" data-rd-close class="secondary">Close</button></div></div>';
  document.body.appendChild(overlay);
  overlay.querySelector('[data-rd-close]').addEventListener('click', function() {
    if (activeMap) { try { activeMap.remove(); } catch (_) {} activeMap = null; }
    overlay.remove(); fleetHook();
  });
  overlay.addEventListener('click', function(e) {
    if (e.target === overlay) {
      if (activeMap) { try { activeMap.remove(); } catch (_) {} activeMap = null; }
      overlay.remove(); fleetHook();
    }
  });
  renderRouteDetailBody(overlay, route);
}

function renderRouteDetailBody(overlay, route) {
  var body = overlay.querySelector('#h38RouteDetailBody');
  if (!body) return;
  var routeId = text(v(route, 'Route ID'));
  var stops = stopsForRoute(routeId);
  var prog = routeProgress(routeId);
  var bouncie = hasBouncie();
  var isCrewView = !isOwner();

  var html = '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">' +
    '<div><h2 style="margin:0">' + esc(text(v(route, 'Route Name')) || 'Route') + '</h2>' +
    '<small class="muted">' + esc(fmtDate(v(route, 'Route Date'))) +
    (text(v(route, 'Assigned Crew Name')) ? ' · ' + esc(text(v(route, 'Assigned Crew Name'))) : '') + '</small></div>' +
    statusPill(text(v(route, 'Status') || 'planned').toLowerCase()) + '</div>' +
    '<div class="h38-route-progress"><div style="width:' + prog.pct + '%"></div></div>' +
    '<small class="muted">' + prog.done + '/' + prog.total + ' stops done</small>' +
    '<div id="h38RouteMap" class="h38-route-map"><div class="h38-route-note" style="padding:16px">Loading map…</div></div>';

  if (bouncie) {
    html += '<p class="h38-route-note">🚚 Live Bouncie vehicle positions shown on the map.</p>';
  } else if (isOwner()) {
    html += '<div class="h38-coming-soon-note">📍 <strong>Live phone tracking — coming soon.</strong> Connect Bouncie for live vehicle positions.</div>';
  }

  html += '<div style="margin-top:8px">' + stops.map(function(s, i) {
    return renderStopRow(s, i, isCrewView);
  }).join('') + '</div>';

  if (isOwner() && stops.length) {
    html += '<div class="h38-route-actions"><button type="button" data-rd-edit>✏️ Edit route</button>' +
      '<button type="button" data-rd-proof>🔗 Proof link</button></div>';
  }

  body.innerHTML = html;
  renderRouteMap('h38RouteMap', routeId);

  // Wire check-in buttons
  body.querySelectorAll('[data-stop-arrived],[data-stop-done],[data-stop-missed]').forEach(function(btn) {
    btn.addEventListener('click', function() { handleCheckin(btn, overlay, route); });
  });
  var editBtn = body.querySelector('[data-rd-edit]');
  if (editBtn) editBtn.addEventListener('click', function() {
    if (activeMap) { try { activeMap.remove(); } catch (_) {} activeMap = null; }
    overlay.remove(); openRouteBuilder(routeId);
  });
  var proofBtn = body.querySelector('[data-rd-proof]');
  if (proofBtn) proofBtn.addEventListener('click', function() { openProofView(routeId); });
}

function renderStopRow(s, i, isCrewView) {
  var st = stopStatus(s);
  var stopId = esc(text(v(s, 'Stop ID')));
  var html = '<div class="h38-stop"><div class="h38-stop-dot ' + st + '">' + (i + 1) + '</div>' +
    '<div class="h38-stop-body"><strong>' + esc(text(v(s, 'Customer Name'))) + '</strong><br>' +
    '<small class="muted">' + esc(text(v(s, 'Address'))) + '</small>';
  if (st === 'arrived') html += '<br><small>🟡 Arrived ' + esc(fmtTime(v(s, 'Arrived At'))) + '</small>';
  if (st === 'done') {
    html += '<br><small>✅ Done ' + esc(fmtTime(v(s, 'Completed At'))) + '</small>';
    if (text(v(s, 'Notes'))) html += '<br><small>📝 ' + esc(text(v(s, 'Notes'))) + '</small>';
  }
  if (st === 'missed') html += '<br><small>❌ Marked missed</small>';
  html += '</div>';
  // Check-in buttons (crew) — owner can also check in
  if (st === 'pending') {
    html += '<div class="h38-stop-actions"><button type="button" class="h38-stop-arrived" data-stop-arrived="' + stopId + '">Arrived</button></div>';
  } else if (st === 'arrived') {
    html += '<div class="h38-stop-actions"><button type="button" class="h38-stop-checkin" data-stop-done="' + stopId + '">✓ Done</button>' +
      '<button type="button" data-stop-missed="' + stopId + '" class="secondary">Missed</button></div>';
  }
  html += '</div>';
  return html;
}

async function handleCheckin(btn, overlay, route) {
  var stopId = btn.getAttribute('data-stop-arrived') || btn.getAttribute('data-stop-done') || btn.getAttribute('data-stop-missed');
  var stop = records(STOPS_COLLECTION).find(function(r) { return text(v(r, 'Stop ID')) === text(stopId); });
  if (!stop) { toast('Stop not found.', true); return; }
  btn.disabled = true;
  try {
    if (btn.hasAttribute('data-stop-arrived')) {
      // GPS stamp (best effort — works without hardware, just records nothing extra)
      var gps = await gpsStamp();
      await updateStopStatus(stop, 'arrived', {
        arrivedAt: nowIso(),
        checkinLat: gps ? gps.lat : null, checkinLng: gps ? gps.lng : null
      });
      toast('Checked in at stop.' + (gps ? ' Location stamped.' : ''));
    } else if (btn.hasAttribute('data-stop-done')) {
      var photo = await askPhoto();
      var notes = '';
      // Quick notes prompt (non-blocking style)
      var wantNotes = confirm('Add a note for this stop? (OK = add note, Cancel = skip)');
      if (wantNotes) notes = prompt('Stop note:') || '';
      var gps2 = await gpsStamp();
      await updateStopStatus(stop, 'done', {
        completedAt: nowIso(), photo: photo,
        notes: notes,
        checkinLat: gps2 ? gps2.lat : null, checkinLng: gps2 ? gps2.lng : null
      });
      toast('Stop done.' + (photo ? ' Photo attached.' : ''));
      // If all stops done, mark route completed
      var prog = routeProgress(text(v(route, 'Route ID')));
      if (prog.done === prog.total && prog.total > 0) {
        await saveRoute({
          id: text(v(route, 'Route ID')), name: text(v(route, 'Route Name')),
          date: text(v(route, 'Route Date')), assignedUserId: text(v(route, 'Assigned User ID')),
          assignedCrewName: text(v(route, 'Assigned Crew Name')), status: 'completed',
          notes: text(v(route, 'Notes')), proofToken: text(v(route, 'Proof Token')),
          createdTime: text(v(route, 'Created Time'))
        });
        toast('🎉 Route complete!');
      }
    } else if (btn.hasAttribute('data-stop-missed')) {
      if (!confirm('Mark this stop as missed?')) { btn.disabled = false; return; }
      await updateStopStatus(stop, 'missed', { completedAt: nowIso() });
      toast('Stop marked missed.');
    }
    renderRouteDetailBody(overlay, routeById(text(v(route, 'Route ID'))));
  } catch (err) {
    toast('Check-in failed: ' + text(err && err.message || err), true);
    btn.disabled = false;
  }
}

function gpsStamp() {
  return new Promise(function(resolve) {
    try {
      if (!navigator.geolocation) return resolve(null);
      navigator.geolocation.getCurrentPosition(function(pos) {
        resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude });
      }, function() { resolve(null); }, { timeout: 8000, maximumAge: 60000 });
    } catch (_) { resolve(null); }
  });
}

function askPhoto() {
  return new Promise(function(resolve) {
    var want = confirm('Add a completion photo for proof of service?');
    if (!want) return resolve(null);
    var input = document.createElement('input');
    input.type = 'file'; input.accept = 'image/*'; input.capture = 'environment';
    var done = false;
    input.onchange = function() {
      var f = input.files && input.files[0];
      if (!f) { if (!done) { done = true; resolve(null); } return; }
      var reader = new FileReader();
      reader.onload = function() { if (!done) { done = true; resolve(String(reader.result).slice(0, 200000)); } };
      reader.onerror = function() { if (!done) { done = true; resolve(null); } };
      reader.readAsDataURL(f);
    };
    input.click();
    setTimeout(function() { if (!done) { done = true; resolve(null); } }, 60000);
  });
}

/* ---------- proof of service ---------- */
function proofUrl(route) {
  var token = text(v(route, 'Proof Token'));
  var base = w.location.origin + w.location.pathname;
  return base + '?businessKey=' + encodeURIComponent(text((w.state && w.state.businessKey) || '')) + '&routeProof=' + encodeURIComponent(token);
}

function openProofView(routeId) {
  var route = typeof routeId === 'string' ? routeById(routeId) : routeId;
  if (!route) { toast('Route not found.', true); return; }
  ensureStyle();
  var overlay = document.createElement('div');
  overlay.className = 'h38-route-overlay';
  var stops = stopsForRoute(text(v(route, 'Route ID')));
  var doneStops = stops.filter(function(s) { return stopStatus(s) === 'done'; });
  overlay.innerHTML = '<div class="h38-route-modal" role="dialog" aria-label="Proof of service" style="max-width:640px">' +
    '<div class="h38-route-proof">' +
    '<h3>✅ Proof of service</h3>' +
    '<p><strong>' + esc(text(v(route, 'Route Name'))) + '</strong><br>' +
    '<small class="muted">' + esc(fmtDate(v(route, 'Route Date'))) +
    (text(v(route, 'Assigned Crew Name')) ? ' · Crew: ' + esc(text(v(route, 'Assigned Crew Name'))) : '') + '</small></p>' +
    '<p>' + doneStops.length + ' of ' + stops.length + ' stops completed.</p>' +
    stops.map(function(s, i) {
      var st = stopStatus(s);
      var icon = st === 'done' ? '✅' : st === 'arrived' ? '🟡' : st === 'missed' ? '❌' : '⚪';
      var line = '<div style="margin:8px 0">' + icon + ' <strong>Stop ' + (i + 1) + ': ' + esc(text(v(s, 'Customer Name'))) + '</strong><br>' +
        '<small class="muted">' + esc(text(v(s, 'Address'))) + '</small>';
      if (st === 'done') {
        line += '<br><small>Arrived ' + esc(fmtTime(v(s, 'Arrived At'))) + ' → Done ' + esc(fmtTime(v(s, 'Completed At'))) + '</small>';
        if (text(v(s, 'Notes'))) line += '<br><small>📝 ' + esc(text(v(s, 'Notes'))) + '</small>';
        if (text(v(s, 'Photo'))) line += '<br><img src="' + text(v(s, 'Photo')) + '" style="max-width:100%;border-radius:8px;margin-top:6px" alt="Proof photo">';
      }
      return line + '</div>';
    }).join('') +
    '<div class="proof-link-row" style="margin-top:12px"><label><strong>Shareable proof link</strong></label>' +
    '<div class="h38-proof-link"><input id="h38ProofLinkInput" readonly value="' + esc(proofUrl(route)) + '">' +
    '<button type="button" data-proof-copy style="min-height:44px">Copy</button></div>' +
    '<p class="h38-route-note">Anyone with this link can view the completion summary. ' +
    'Tip: print this page (Ctrl/Cmd+P) for a paper copy.</p></div>' +
    '</div>' +
    '<div class="actions"><button type="button" data-proof-close class="secondary">Close</button>' +
    '<button type="button" data-proof-print>🖨️ Print</button></div></div>';
  document.body.appendChild(overlay);
  overlay.querySelector('[data-proof-close]').addEventListener('click', function() { overlay.remove(); });
  overlay.addEventListener('click', function(e) { if (e.target === overlay) overlay.remove(); });
  overlay.querySelector('[data-proof-copy]').addEventListener('click', function() {
    var input = overlay.querySelector('#h38ProofLinkInput');
    input.select();
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(input.value).then(function() { toast('Proof link copied.'); });
      } else { document.execCommand('copy'); toast('Proof link copied.'); }
    } catch (_) { toast('Copy the link manually.', true); }
  });
  overlay.querySelector('[data-proof-print]').addEventListener('click', function() { w.print(); });
}

/* ---------- ?routeProof= deep link ---------- */
function checkProofDeepLink() {
  try {
    var params = new URLSearchParams(w.location.search);
    var token = params.get('routeProof');
    if (!token) return false;
    var route = allRoutes().find(function(r) { return text(v(r, 'Proof Token')) === text(token); });
    if (!route || !enabled()) return false;
    // Render proof view once the app shell is ready
    var iv = setInterval(function() {
      if (!document.getElementById('mainContent')) return;
      clearInterval(iv);
      setTimeout(function() { openProofView(text(v(route, 'Route ID'))); }, 800);
    }, 500);
    setTimeout(function() { clearInterval(iv); }, 15000);
    return true;
  } catch (_) { return false; }
}

/* ---------- boot ---------- */
var booted = false;
function start() {
  if (booted) return;
  booted = true;
  registerFeature();
  // Watch for fleet page renders
  if (typeof MutationObserver !== 'undefined') {
    new MutationObserver(function() { fleetHook(); })
      .observe(document.documentElement, { childList: true, subtree: true });
  }
  fleetHook();
  // Deep link (after data loads)
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() { setTimeout(checkProofDeepLink, 2500); }, { once: true });
  } else {
    setTimeout(checkProofDeepLink, 2500);
  }
  w.H38RouteManager = Object.freeze({
    build: BUILD,
    enabled: enabled,
    openRouteDetail: openRouteDetail,
    openRouteBuilder: openRouteBuilder,
    openProofView: openProofView,
    allRoutes: allRoutes,
    stopsForRoute: stopsForRoute,
    routeProgress: routeProgress,
    hasBouncie: hasBouncie,
    FEATURE: FEATURE_DEF
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', start, { once: true });
} else {
  start();
}
})();
;

