async function ingest(raw){const r=typeof raw==='string'?JSON.parse(raw):raw;if(!r||t(r.captureSessionId)!==state.visit.sessionId)throw Error('Camera returned the wrong site visit.');for(const m of Array.isArray(r.measurements)?r.measurements:[]){const id=t(m.id)||uid('SITE-MEASURE'),source=ALLOWED_NATIVE_SOURCES.includes(t(m.source))?t(m.source):(device().platform==='ios'?'ARKIT_POINT_TO_POINT':'ARCORE_POINT_TO_POINT'),rec={'Site Measurement ID':id,'Capture Session ID':state.visit.sessionId,'Business ID':business(),'Quote ID':state.visit.quoteId,'Sequence':state.measurements.length+1,'Label':t(m.label||`Measurement ${state.measurements.length+1}`),'Measurement Type':t(m.type||'Length'),'Value':n(m.value),'Unit':t(m.unit||'in'),'Source':source,'Confidence':Math.max(0,Math.min(1,n(m.confidence||.65))),'Verification Status':t(m.verificationStatus||'DEVICE_CAPTURED'),'Start Point':m.startPoint||{},'End Point':m.endPoint||{},'Confirmed By':user(),'Notes':t(m.notes||'Device captured. Check critical work with tape or laser.'),'Created Time':now(),'Updated Time':now(),'Record Version':1};await queue(MEASURES,'Site Measurement',id,rec,['Site Measurement ID','measurementId']);if(!state.visit.measurementIds.includes(id))state.visit.measurementIds.push(id)}await saveDraft();await load();toast('Measurement saved locally.');render()}
async function manual(ev){ev.preventDefault();try{await session();const f=ev.currentTarget,total=Math.max(0,n(f.feet.value))*12+Math.max(0,n(f.inches.value));if(!total)throw Error('Enter a measurement greater than zero.');const checked=f.checked.checked,id=uid('SITE-MEASURE'),rec={'Site Measurement ID':id,'Capture Session ID':state.visit.sessionId,'Business ID':business(),'Quote ID':state.visit.quoteId,'Sequence':state.measurements.length+1,'Label':t(f.label.value).trim()||`Measurement ${state.measurements.length+1}`,'Measurement Type':'Length','Value':total,'Unit':'in','Source':checked?'MANUAL_LASER':'MANUAL_ENTRY','Confidence':checked?1:.8,'Verification Status':checked?'FIELD_MEASURED':'UNVERIFIED','Start Point':{},'End Point':{},'Confirmed By':user(),'Notes':t(f.measurementNotes.value).trim(),'Created Time':now(),'Updated Time':now(),'Record Version':1};await queue(MEASURES,'Site Measurement',id,rec,['Site Measurement ID','measurementId']);state.visit.measurementIds.push(id);await saveDraft();await load();toast(`${feet(total,'in')} saved locally.`);render()}catch(e){toast(e.message||e,true)}}
async function image(file){if(!file.type.startsWith('image/'))return file;try{const b=await createImageBitmap(file),scale=Math.min(1,1920/Math.max(b.width,b.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(b.width*scale));c.height=Math.max(1,Math.round(b.height*scale));c.getContext('2d').drawImage(b,0,0,c.width,c.height);b.close?.();const blob=await new Promise(r=>c.toBlob(r,'image/jpeg',.84));return blob?new File([blob],file.name.replace(/\.[^.]+$/,'.jpg'),{type:'image/jpeg',lastModified:file.lastModified}):file}catch(_){return file}}
