async function photos(files){try{await session();const list=Array.from(files||[]).slice(0,12);for(const original of list){const file=await image(original),id=uid('ATTACH'),payload={id,attachmentId:id,businessId:business(),relatedRecordType:'Site Visit',relatedRecordId:state.visit.visitId,fileName:file.name,mimeType:file.type||'image/jpeg',fileSize:file.size,captureTime:now(),visibility:'Internal',base64Data:await b64(file)};await window.H38DB.put('attachments',Object.assign({},payload,{syncStatus:'PENDING'}));await window.queueOperation('SAVE_ATTACHMENT','Attachment',id,payload,null,false);if(!state.visit.attachmentIds.includes(id))state.visit.attachmentIds.push(id)}await saveDraft();await pending();toast(`${list.length} photo${list.length===1?'':'s'} saved locally.`);render();if(navigator.onLine)syncSoon()}catch(e){toast(e.message||e,true)}}
async function notes(value,announce){state.visit.notes=t(value);await saveDraft();if(!state.visit.sessionId){if(announce)toast('Notes saved locally.');return}const id=`${state.visit.visitId}-NOTES`,rec={'Job Note ID':id,'Business ID':business(),'Quote ID':state.visit.quoteId,'Capture Session ID':state.visit.sessionId,'Note Type':'Field Visit','Body':state.visit.notes,'Status':'Internal Draft','Created By':user(),'Created Time':state.visit.createdAt,'Updated Time':now(),'Record Version':1};await queue(NOTES,'Field Note',id,rec,['Job Note ID','jobNoteId']);if(announce)toast('Notes saved locally.')}
async function attach(){try{await notes(state.visit.notes,false);const q=quote(state.visit.quoteId);if(locked(q))throw Error('This quote is locked.');const ms=state.measurements.map(r=>`${val(r,'Label','label')}: ${feet(val(r,'Value','value'),val(r,'Unit','unit'))} · ${val(r,'Verification Status','verificationStatus')}`),summary=[`H38 Field Visit: ${state.visit.visitId}`,`Project type: ${state.visit.projectType}`,`Measurements: ${ms.length?ms.join('; '):'none'}`,`Site photos: ${state.visit.attachmentIds.length}`,state.visit.notes?`Field notes: ${state.visit.notes}`:'','Camera measurements remain DEVICE_CAPTURED until checked. Verify critical dimensions before ordering, permits, fabrication, or construction.'].filter(Boolean).join('\n');const updated=Object.assign({},q,{'Quote ID':state.visit.quoteId,'Business ID':business(),'Customer ID':state.visit.customerId,'Project Title':state.visit.projectTitle,'Scope':state.visit.scope||val(q,'Scope','scope'),'Measurement Notes':[t(val(q,'Measurement Notes','measurementNotes')),summary].filter(Boolean).join('\n\n'),'Site Visit ID':state.visit.visitId,'Site Scanner Session ID':state.visit.sessionId,'Site Visit Review Status':'OWNER_REVIEWED_FOR_DRAFT_ATTACHMENT','Status':t(val(q,'Status','status')||'Draft'),'Updated Time':now(),'Record Version':n(val(q,'Record Version','recordVersion')||1)+1});await queue('quotes','Quote',state.visit.quoteId,updated,['Quote ID','quoteId']);state.visit.status='ATTACHED_TO_DRAFT_QUOTE';await saveDraft();toast(navigator.onLine?'Visit attached to draft quote. Sync is running.':'Visit attached locally and will sync when service returns.');render()}catch(e){toast(e.message||e,true)}}
