window.H38_FIELD_VISIT_CORE={state,TYPES,t,n,$,esc,rows,val,rid,business,user,quote,locked,customerName,feet,device,toast,status,pending,syncSoon,saveDraft,restore,blank,load,context,camera,ingest,manual,photos,notes,attach,dismissARFallback,voiceDimensions:function(){return window.H38VoiceDimensions&&window.H38VoiceDimensions.record();},setRender:fn=>state.render=fn};
