  const cust=['<option value="">Choose customer</option>',...activeCustomers().map(r=>{const id=rid(r,'Customer ID','customerId');return`<option value="${esc(id)}" ${id===cid?'selected':''}>${esc(val(r,'Customer Name','customerName'))}</option>`})].join('');
  const qs=['<option value="">New draft quote</option>',...rows('quotes').filter(r=>!cid||rid(r,'Customer ID','customerId')===cid).map(r=>{const id=rid(r,'Quote ID','quoteId');return`<option value="${esc(id)}" ${id===S.visit.quoteId?'selected':''}>${esc(val(r,'Quote Number','quoteNumber')||id)} — ${esc(val(r,'Project Title','projectTitle')||'Quote')}</option>`})].join('');
