async function makeSureSynced(videoAttachmentId,audioAttachmentId){if(!navigator.onLine)throw Error('Walkthrough notes will process automatically when this phone is online.');await session(false);await window.H38_FIELD_VISIT_VIDEO?.syncPending?.();await window.H38_FIELD_VISIT_VOICE_CAPTURE?.syncPending?.();const waitingBefore=await window.H38_FIELD_VISIT_RECOVERY?.waitingOperations?.()||[];if(waitingBefore.length)await window.H38_FIELD_VISIT_RECOVERY?.syncNow?.();for(const attachmentId of [videoAttachmentId,audioAttachmentId].filter(Boolean)){const local=await window.H38DB?.get('attachments',attachmentId);if(local&&text(local.syncStatus).toUpperCase()!=='SYNCED')throw Error('The walkthrough is still saving privately. H38 will create the notes automatically when sync finishes.')}const waiting=await window.H38_FIELD_VISIT_RECOVERY?.waitingOperations?.()||[];if(waiting.length)throw Error('The Site Visit is still syncing. H38 will create the walkthrough notes automatically when it finishes.')}
async function requestTranscript(videoAttachmentId,audioAttachmentId,forceRefresh=false){const auth=await session(forceRefresh),v=visit(),response=await fetch(`${cfg.url}/functions/v1/h38-walkthrough-transcription`,{method:'POST',mode:'cors',cache:'no-store',credentials:'omit',headers:{authorization:`Bearer ${auth.session.access_token}`,apikey:cfg.publishableKey,'content-type':'application/json','x-client-info':'h38-walkthrough-video-notes-v4'},body:JSON.stringify({businessId:v.businessId||window.state?.businessId,captureSessionId:v.sessionId,quoteId:v.quoteId||'',attachmentId:videoAttachmentId,audioAttachmentId:audioAttachmentId||''})}),payload=await response.json().catch(()=>({}));return{response,payload}}
function editableText(s){const parts=[];(s.cleanNotes||[]).forEach(x=>parts.push(`Work: ${x}`));(s.customerRequests||[]).forEach(x=>parts.push(`Customer request: ${x}`));(s.siteConditions||[]).forEach(x=>parts.push(`Site condition: ${x}`));(s.unknowns||[]).forEach(x=>parts.push(`Follow-up: ${x}`));(s.spokenMeasurements||[]).forEach(m=>parts.push(`Spoken measurement (verify): ${text(m.label)||'Measurement'} — ${text(m.valueText)||text(m.statement)}`));return parts.join('\n')}
function applyComplete(payload,videoAttachmentId,audioAttachmentId){const s=voice(),v=visit(),notes=payload.notes||{};s.status='COMPLETE';s.message='Professional walkthrough notes ready.';s.attachmentId=videoAttachmentId;s.audioAttachmentId=text(payload.audioAttachmentId||audioAttachmentId);s.transcript=text(payload.transcript);s.cleanNotes=Array.isArray(notes.cleanNotes)?notes.cleanNotes:[];s.customerRequests=Array.isArray(notes.customerRequests)?notes.customerRequests:[];s.siteConditions=Array.isArray(notes.siteConditions)?notes.siteConditions:[];s.unknowns=Array.isArray(notes.unknowns)?notes.unknowns:[];s.spokenMeasurements=Array.isArray(notes.spokenMeasurements)?notes.spokenMeasurements:[];v.walkthroughTranscript=s.transcript;v.walkthroughVoiceNotes=s.cleanNotes;v.walkthroughSpokenMeasurements=s.spokenMeasurements;v.walkthroughMeasurementCandidates=s.spokenMeasurements.map(m=>({...m,source:'Walkthrough video narration',verificationStatus:SPOKEN_VERIFICATION,fieldVerified:false}));v.walkthroughProfessionalNotes={summary:s.cleanNotes,customerRequests:s.customerRequests,siteConditions:s.siteConditions,unknowns:s.unknowns,spokenMeasurements:s.spokenMeasurements,spokenMeasurementVerification:SPOKEN_VERIFICATION};if(!text(v.walkthroughEditableNotes).trim())v.walkthroughEditableNotes=editableText(s);v.walkthroughTranscriptStatus='COMPLETE';v.walkthroughTranscriptAttachmentId=videoAttachmentId;v.walkthroughVoiceAudioAttachmentId=s.audioAttachmentId}
async function runEnsure(force=false){const v=visit(),s=voice(),videoAttachmentId=latestAttachment();if(!v||!s||!videoAttachmentId||!v.sessionId)return true;let audioAttachmentId=latestAudioAttachment(videoAttachmentId);if(!audioAttachmentId){const local=await window.H38DB?.get('attachments',videoAttachmentId);const file=local?.blobData;if(file instanceof Blob){try{audioAttachmentId=await window.H38_FIELD_VISIT_VOICE_CAPTURE?.ensureFromVideo?.(file,videoAttachmentId)||''}catch(error){console.warn('Same-video audio preparation:',error?.message||error)}}}if(audioKnownUnavailable(videoAttachmentId)&&!audioAttachmentId){s.status='NO_AUDIO';s.attachmentId=videoAttachmentId;s.audioAttachmentId='';s.message='This walkthrough is not accepted because microphone audio is required.';await persist();return true}if(!navigator.onLine)return false;if(!force&&s.status==='COMPLETE'&&s.attachmentId===videoAttachmentId)return true;if(!force&&s.status==='NO_AUDIO'&&s.attachmentId===videoAttachmentId)return true;if(!force&&s.status==='FAILED'&&s.attachmentId===videoAttachmentId){if(recoveryAttempted.has(videoAttachmentId))return true;recoveryAttempted.add(videoAttachmentId)}s.attachmentId=videoAttachmentId;s.audioAttachmentId=audioAttachmentId;s.status='SYNCING';s.message=audioAttachmentId?'Saving the walkthrough audio before creating notes…':'Preparing the saved walkthrough microphone audio…';await persist();try{await makeSureSynced(videoAttachmentId,audioAttachmentId);s.status='TRANSCRIBING';s.message='Turning what you said in the walkthrough into editable field notes…';await persist();let attempt=await requestTranscript(videoAttachmentId,audioAttachmentId,false);if(attempt.response.status===401)attempt=await requestTranscript(videoAttachmentId,audioAttachmentId,true);if(!attempt.response.ok||attempt.payload.status!=='PASS'){const message=attempt.payload.message||`Walkthrough note processing failed (${attempt.response.status}).`;if(attempt.payload.errorCode==='NO_USABLE_AUDIO'||/no usable microphone audio/i.test(message)){s.status='NO_AUDIO';s.message='This walkthrough is not accepted because usable microphone audio was not found. Record it again.';await persist();C.toast(s.message,true);return true}throw Error(message)}applyComplete(attempt.payload,videoAttachmentId,audioAttachmentId);await persist();C.toast('Editable field notes were created from what you said in the walkthrough.');return true}catch(error){s.status='FAILED';s.message=text(error?.message||error);await persist();C.toast(s.message,true);return true}}
async function ensure(force=false){if(running&&runningPromise)return runningPromise;running=true;runningPromise=runEnsure(force).finally(()=>{running=false;runningPromise=null});return runningPromise}
function list(items,empty='None identified.'){return Array.isArray(items)&&items.length?`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:`<p>${esc(empty)}</p>`}
function captureCard(){const s=voice(),id=latestAttachment();if(!s||!id)return'';if(['WAITING','SYNCING','TRANSCRIBING'].includes(s.status))return`<section id="fieldVoiceStatus" class="field-card field-voice-card"><div><strong>📝 Notes from walkthrough video</strong><small>${esc(s.message||'Preparing professional field notes…')}</small></div></section>`;if(s.status==='FAILED')return`<section id="fieldVoiceStatus" class="field-card field-voice-card"><div><strong>⚠ Walkthrough notes need another try</strong><small>${esc(s.message)}</small></div><button id="fieldVoiceRetry" class="field-secondary" type="button">Retry walkthrough notes</button></section>`;if(s.status==='NO_AUDIO')return`<section id="fieldVoiceStatus" class="field-card field-voice-card field-voice-warning"><div><strong>⚠ Walkthrough not accepted</strong><small>${esc(s.message)} H38 will not continue with video only.</small></div></section>`;if(s.status==='COMPLETE')return`<section id="fieldVoiceStatus" class="field-card field-voice-card"><div><strong>✓ Spoken walkthrough notes ready</strong><small>${s.cleanNotes.length} summary note${s.cleanNotes.length===1?'':'s'} · ${s.customerRequests.length} customer request${s.customerRequests.length===1?'':'s'} · ${s.spokenMeasurements.length} measurement candidate${s.spokenMeasurements.length===1?'':'s'}</small></div></section>`;return''}
function notesCard(){const s=voice(),v=visit();if(!s||s.status!=='COMPLETE')return'';const spoken=(s.spokenMeasurements||[]).map(m=>`${text(m.label)||'Spoken measurement'}: ${text(m.valueText)||text(m.statement)} — verify with ARCore, laser or tape`);return`<section id="fieldVoiceNotes" class="field-card field-voice-notes"><div class="field-voice-title"><span>📝</span><div><h2>Walkthrough field notes</h2><small>Created from what you said in the same walkthrough video. Edit and save anything you want to keep.</small></div></div><label><strong>Editable saved notes</strong><textarea id="fieldWalkthroughEditableNotes" rows="9">${esc(text(v?.walkthroughEditableNotes)||editableText(s))}</textarea></label><button id="fieldSaveWalkthroughNotes" class="field-primary" type="button">Save Walkthrough Notes</button><div><strong>Spoken measurement candidates</strong>${list(spoken,'No measurements were spoken in the walkthrough.')}<small>Plain video does not contain ARCore depth geometry. These become field measurements only after ARCore, laser or tape verification.</small></div>${s.transcript?`<details><summary>Original spoken transcript — internal evidence</summary><p class="field-voice-transcript">${esc(s.transcript)}</p></details>`:''}</section>`}
function decorate(){const app=document.getElementById('h38FieldVisitApp');if(!app)return;app.querySelector('#fieldVoiceStatus')?.remove();app.querySelector('#fieldVoiceNotes')?.remove();const stage=app.querySelector('[data-field-walkthrough-stage]');if(stage&&!visit()?.walkthroughSkipped)stage.insertAdjacentHTML('afterend',captureCard());else{const actions=app.querySelector('.field-capture-actions');if(actions&&latestAttachment())actions.insertAdjacentHTML('beforebegin',captureCard())}const notes=app.querySelector('#fieldNotes')?.closest('.field-card');if(notes)notes.insertAdjacentHTML('beforebegin',notesCard());app.querySelector('#fieldVoiceRetry')?.addEventListener('click',()=>{recoveryAttempted.delete(latestAttachment());void ensure(true)});app.querySelector('#fieldSaveWalkthroughNotes')?.addEventListener('click',async()=>{const v=visit(),box=document.getElementById('fieldWalkthroughEditableNotes');if(!v||!box)return;v.walkthroughEditableNotes=text(box.value);await C.saveDraft?.();C.toast('Walkthrough notes saved to this Site Visit.');});if(latestAttachment())schedule(250)}
function schedule(delay=500){clearTimeout(timer);timer=setTimeout(()=>void ensure(false),delay)}
function install(){if(C.state.__voiceNotesWrapped)return;const base=C.state.render;if(typeof base!=='function')return;C.state.__voiceNotesWrapped=true;C.setRender(function(){base();decorate()});decorate()}
window.addEventListener('online',()=>schedule(100));setInterval(()=>{if(C.state.open&&navigator.onLine&&latestAttachment())schedule(0)},5000);
const style=document.createElement('style');style.textContent='.field-voice-card,.field-voice-notes{display:grid;gap:.7rem;border:1px solid #c8dce8;background:#f8fbfd}.field-voice-warning{border-color:#d9b66f;background:#fffaf0}.field-voice-card div{display:grid;gap:.2rem}.field-voice-card small,.field-voice-notes small{color:#52616d}.field-voice-title{display:flex!important;gap:.65rem!important;align-items:flex-start}.field-voice-title>span{font-size:1.35rem}.field-voice-title h2{margin:0}.field-voice-notes>div:not(.field-voice-title){display:grid;gap:.3rem;padding-top:.55rem;border-top:1px solid #dce8ef}.field-voice-notes textarea{width:100%;min-height:170px;box-sizing:border-box;font:inherit;line-height:1.4;padding:.7rem;border:1px solid #9fb7c5;border-radius:.55rem;background:#fff}.field-voice-notes ul{margin:.15rem 0 .15rem 1.2rem;padding:0;display:grid;gap:.3rem}.field-voice-transcript{white-space:pre-wrap;line-height:1.45}';document.head.appendChild(style);
