function identity(v){return{businessId:text(v?.businessId||C.business()),id:text(v?.id),visitId:text(v?.visitId||v?.siteVisitId||v?.['Site Visit ID']),sessionId:text(v?.sessionId||v?.captureSessionId||v?.['Capture Session ID']),quoteId:text(v?.quoteId||v?.['Quote ID']),customerId:text(v?.customerId||v?.['Customer ID'])};}
