async function auth(){const api=shared?.ensure?.();if(!api)throw Error('The secure Business Office connection is not ready.');const result=await api.auth.getSession();if(result.error)throw result.error;const session=result.data?.session;if(!session?.user)throw Error('Sign in again before deleting synced evidence.');return{api,user:session.user};}
