async function removePendingOperations(tokens){const wanted=unique(tokens);if(!wanted.length)return 0;const rows=await window.H38DB.all('operations');let removed=0;for(const row of rows){const status=text(row?.syncStatus||row?.status).toUpperCase();if(['SYNCED','COMPLETE','COMPLETED'].includes(status))continue;let hay='';try{hay=JSON.stringify(row);}catch(_){}if(wanted.some(token=>hay.includes(token))){await window.H38DB.remove('operations',row.id);removed++;}}await C.pending?.();return removed;}
