async function serverDeletePhotos(task,{logAction=true}={}){const ids=unique(task.attachmentIds||[task.attachmentId]);if(!ids.length)return;const businessId=text(task.businessId||C.business()),{api,user}=await auth(),rows=await findDocumentRows(api,businessId,ids),keys=unique(rows.map(row=>row.record_key)),paths=unique([task.storagePath,...rows.map(row=>text(row.payload?.['Storage Path']||row.payload?.storagePath))]);if(paths.length){const removed=await api.storage.from('business-office-files').remove(paths);if(removed.error)throw removed.error;}if(keys.length){const deleted=await api.from('business_records').delete().eq('business_id',businessId).eq('collection','documents').in('record_key',keys);if(deleted.error)throw deleted.error;}dropSnapshotDocuments([...ids,...keys]);if(logAction)await proof(api,user,businessId,'DELETE_SITE_VISIT_PHOTO',{visitId:text(task.visitId),attachmentIds:ids,documentKeys:keys,storagePaths:paths});}
