function safeId(value){return text(value).replace(/[^A-Za-z0-9._:-]+/g,'-').slice(0,180);}
async function deletePhoto(id){const v=arrays();if(!v||!id)return;const isFrame=v.walkthroughFrameIds.includes(id),isReplaced=v.replacedWalkthroughFrameIds.includes(id);if(!confirm(`Delete this ${isFrame||isReplaced?'walkthrough photo':'photo'} from the Site Visit?`))return;const local=await window.H38DB.get('attachments',id);v.attachmentIds=v.attachmentIds.filter(x=>x!==id);v.walkthroughFrameIds=v.walkthroughFrameIds.filter(x=>x!==id);v.replacedWalkthroughFrameIds=v.replacedWalkthroughFrameIds.filter(x=>x!==id);await C.saveDraft?.();await removePendingOperations([id]);await window.H38DB.remove('attachments',id);dropSnapshotDocuments([id]);const task={businessId:text(v.businessId||C.business()),visitId:text(v.visitId),attachmentId:id,storagePath:text(local?.storagePath),createdAt:now()};if(navigator.onLine){try{await serverDeletePhotos(task);C.toast('Photo deleted from this Site Visit and private storage.');}catch(error){await saveTombstone(PHOTO_TOMBSTONE,task);C.toast(`Photo removed here. Secure delete will retry automatically: ${error?.message||error}`,true);}}else{await saveTombstone(PHOTO_TOMBSTONE,task);C.toast('Photo removed from this draft. Secure delete will finish when online.');}C.state.render?.();}
async function softDeleteVisitRecords(api,user,v){const i=identity(v);if(!i.sessionId&&!i.visitId)return;for(const collection of ['siteCaptureSessions','siteMeasurements','jobNotes']){const{data,error}=await api.from('business_records').select('record_key,payload').eq('business_id',i.businessId).eq('collection',collection).limit(500);if(error)throw error;const keys=(data||[]).filter(row=>{const p=row.payload||{},session=text(p['Capture Session ID']||p.captureSessionId),visitId=text(p['Site Visit ID']||p.siteVisitId),key=text(row.record_key);return(i.sessionId&&(session===i.sessionId||key===i.sessionId))||(i.visitId&&(visitId===i.visitId||key===`${i.visitId}-NOTES`));}).map(row=>row.record_key);if(keys.length){const changed=await api.from('business_records').update({record_status:'deleted',updated_by:user.id,updated_at:now()}).eq('business_id',i.businessId).eq('collection',collection).in('record_key',keys);if(changed.error)throw changed.error;}}}
async function serverDeleteDraft(task){const v=task.visit||task,{api,user}=await auth(),i=identity(v),ids=unique(task.attachmentIds||await localRelatedAttachmentIds(v));if(ids.length)await serverDeletePhotos({businessId:i.businessId,visitId:i.visitId,attachmentIds:ids},{logAction:false});await softDeleteVisitRecords(api,user,v);await proof(api,user,i.businessId,'DELETE_SITE_VISIT_DRAFT',{visitId:i.visitId,captureSessionId:i.sessionId,quoteId:i.quoteId,customerId:i.customerId,attachmentIds:ids,linkedQuoteDeleted:false,linkedCustomerDeleted:false});}
