function voiceData(){const v=visit(),session=sessionRecord(),local=v?.walkthroughVoice||{};const sessionStatus=text(value(session,'Walkthrough Transcript Status','walkthroughTranscriptStatus')).toUpperCase();const localStatus=text(local.status).toUpperCase();const status=sessionStatus==='COMPLETE'?'COMPLETE':(localStatus||sessionStatus||((v?.videoAttachmentIds||[]).length?'WAITING':''));const cleanNotes=unique([...(Array.isArray(local.cleanNotes)?local.cleanNotes:[]),...(Array.isArray(value(session,'Walkthrough Voice Notes','walkthroughVoiceNotes'))?value(session,'Walkthrough Voice Notes','walkthroughVoiceNotes'):[])]);const requests=unique([...(Array.isArray(local.customerRequests)?local.customerRequests:[]),...(Array.isArray(value(session,'Walkthrough Customer Requests','walkthroughCustomerRequests'))?value(session,'Walkthrough Customer Requests','walkthroughCustomerRequests'):[])]);const conditions=unique([...(Array.isArray(local.siteConditions)?local.siteConditions:[]),...(Array.isArray(value(session,'Walkthrough Site Conditions','walkthroughSiteConditions'))?value(session,'Walkthrough Site Conditions','walkthroughSiteConditions'):[])]);const unknowns=unique([...(Array.isArray(local.unknowns)?local.unknowns:[]),...(Array.isArray(value(session,'Walkthrough Unknowns','walkthroughUnknowns'))?value(session,'Walkthrough Unknowns','walkthroughUnknowns'):[])]);const spoken=Array.isArray(value(session,'Walkthrough Spoken Measurements','walkthroughSpokenMeasurements'))?value(session,'Walkthrough Spoken Measurements','walkthroughSpokenMeasurements'):(Array.isArray(v?.walkthroughMeasurementCandidates)?v.walkthroughMeasurementCandidates:[]);return{status,cleanNotes,requests,conditions,unknowns,spoken,transcript:text(value(session,'Walkthrough Transcript','walkthroughTranscript')||v?.walkthroughTranscript||''),message:text(local.message)}}
