function dimensionSignatures(raw){const source=typeof raw==='string'?raw:[raw?.label,raw?.valueText,raw?.statement,raw?.detail,raw?.request].map(text).join(' '),out=[];const re=/(\d+(?:\.\d+)?)\s*(?:(?:ft|feet|foot|in|inch(?:es)?|["'])\s*)?(?:x|×|by)\s*(\d+(?:\.\d+)?)\s*(?:ft|feet|foot|in|inch(?:es)?|["'])?/gi;let match;while((match=re.exec(source)))out.push([Number(match[1]),Number(match[2])].sort((a,b)=>a-b).map(String).join('x'));return Array.from(new Set(out))}
