function cleanLabel(raw){return text(raw).toLowerCase().replace(/\b(?:verify|measure|measurement|measurements|field|dimension|dimensions|required|needed|need|confirm|record|walkthrough|estimate|estimated)\b/g,' ').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim()}
function labelsMatch(a,b){const x=cleanLabel(a),y=cleanLabel(b);if(!x||!y)return false;if(x===y)return true;if(Math.min(x.length,y.length)>=8&&(x.includes(y)||y.includes(x)))return true;const xa=new Set(x.split(' ').filter(t=>t.length>2)),ya=new Set(y.split(' ').filter(t=>t.length>2)),common=[...xa].filter(t=>ya.has(t));return common.length>=2||(xa.size===1&&ya.size===1&&common.length===1)}
