async function completeMeasurementRequest(request,row){const v=visit();if(!v)return;if(!Array.isArray(v.walkthroughCompletedMeasurements))v.walkthroughCompletedMeasurements=[];const raw=text(request?.request||request?.label),label=arMeasurementLabel(request),measurementId=text(value(row,'Site Measurement ID','measurementId'));if(!v.walkthroughCompletedMeasurements.some(done=>text(done?.sessionId)===text(v.sessionId)&&cleanLabel(done?.request)===cleanLabel(raw)))v.walkthroughCompletedMeasurements.push({request:raw,label,source:text(request?.source),measurementId,sessionId:text(v.sessionId),completedAt:new Date().toISOString()});if(cleanLabel(v.pendingMeasurementRequest)===cleanLabel(raw)){v.pendingMeasurementRequest='';v.pendingMeasurementLabel='';v.pendingMeasurementSource=''}await C.saveDraft?.();window.dispatchEvent(new CustomEvent('h38:walkthrough-measurements-updated',{detail:{sessionId:text(v.sessionId),measurementId,request:raw}}));decorate(true)}
async function completeScopeConfirmation(item,answer){const v=visit();if(!v)return;const question=text(item?.request||item).trim(),cleanAnswer=text(answer).trim();if(!question||!cleanAnswer)throw Error('Enter the scope answer first.');if(!Array.isArray(v.walkthroughScopeConfirmations))v.walkthroughScopeConfirmations=[];if(!v.walkthroughScopeConfirmations.some(done=>text(done?.sessionId)===text(v.sessionId)&&cleanLabel(done?.question)===cleanLabel(question)))v.walkthroughScopeConfirmations.push({question,answer:cleanAnswer,sessionId:text(v.sessionId),completedAt:new Date().toISOString()});const note=`Scope confirmation: ${question} → ${cleanAnswer}`,existing=text(v.notes).trim();if(!existing.includes(note))await C.notes?.(existing?`${existing}\n${note}`:note,false);else await C.saveDraft?.();window.dispatchEvent(new CustomEvent('h38:walkthrough-scope-updated',{detail:{sessionId:text(v.sessionId),question,answer:cleanAnswer}}));decorate(true)}
