async function completePhotoRequest(request,attachmentId){const v=visit(),raw=text(request).trim(),id=text(attachmentId).trim();if(!v||!raw)throw Error('H38 could not identify the requested photo.');if(!id||!Array.isArray(v.attachmentIds)||!v.attachmentIds.map(text).includes(id))throw Error('The requested photo is not attached to this Site Visit.');if(!Array.isArray(v.walkthroughCompletedPhotoRequests))v.walkthroughCompletedPhotoRequests=[];if(!v.walkthroughCompletedPhotoRequests.some(done=>text(done?.sessionId)===text(v.sessionId)&&cleanLabel(done?.request)===cleanLabel(raw)))v.walkthroughCompletedPhotoRequests.push({request:raw,attachmentId:id,sessionId:text(v.sessionId),completedAt:new Date().toISOString()});await C.saveDraft?.();window.dispatchEvent(new CustomEvent('h38:walkthrough-photo-completed',{detail:{sessionId:text(v.sessionId),request:raw,attachmentId:id}}));decorate(true);return true}
function videoEstimates(){const out=[];for(const row of sessionMeasurements().filter(r=>text(value(r,'Source','source')).toUpperCase()==='CAMERA_ESTIMATE')){const label=text(value(row,'Label','label')||'Video estimate');if(verifiedMeasurementForLabel(label))continue;if(out.some(x=>labelsMatch(x.label,label)))continue;out.push({measurementId:text(value(row,'Site Measurement ID','measurementId')),label,value:Number(value(row,'Value','value')||0),unit:text(value(row,'Unit','unit')||'in'),confidence:Number(value(row,'Confidence','confidence')||0),reference:text(value(row,'Video Reference Label','videoReferenceLabel')),verification:text(value(row,'Verification Status','verificationStatus')||'UNVERIFIED')})}return out}
