function measurementRequests(review,voice){const verified=verifiedSignatures(voice),estimates=videoEstimates(),out=[];for(const estimate of estimates)out.push({label:estimate.label,detail:`${displayEstimate(estimate)} · ${Math.round(estimate.confidence*100)}% camera estimate`,source:'CAMERA_ESTIMATE',request:`Verify ${estimate.label} — walkthrough estimate ${displayEstimate(estimate)} (${Math.round(estimate.confidence*100)}% confidence) with Android AR, laser, or tape.`});for(const item of voice.spoken||[]){const spokenLabel=text(item.label||item.valueText||'Spoken measurement');if(isVerified(item)||verifiedMeasurementForLabel(spokenLabel)||materialSpec([item?.label,item?.valueText,item?.statement].map(text).join(' ')))continue;out.push({label:spokenLabel,detail:text(item.valueText||item.statement||''),source:'SPOKEN_IN_WALKTHROUGH',request:`Verify ${spokenLabel} ${text(item.valueText||'')} with Android AR, laser, or tape.`})}for(const raw of review?.missingMeasurements||[]){const item=text(raw).trim();if(!item||materialSpec(item)||scopeDecision(item)||verifiedMeasurementForLabel(item))continue;const sigs=dimensionSignatures(item);if(sigs.length&&sigs.every(sig=>verified.has(sig)))continue;if(estimates.some(e=>labelsMatch(e.label,item)))continue;out.push({label:item.split(/[.;]/)[0].slice(0,120),detail:'',source:'VIDEO_REVIEW_TARGET',request:item})}const seen=[];return out.filter(item=>{if(measurementCompleted(item))return false;const key=(cleanLabel(item.label)+'|'+cleanLabel(item.request));if(seen.includes(key))return false;seen.push(key);return true}).slice(0,10)}
