function reviewEvidenceKey(){const v=visit();if(!v)return'';return[v.sessionId,(v.videoAttachmentIds||[]).join(','),(v.walkthroughFrameIds||[]).join(','),(v.attachmentIds||[]).join(','),text(v.walkthroughTranscript).length,(v.walkthroughVoiceNotes||[]).join('|')].join('|')}
async function persist(){const s=localAi();if(!s)return;s.updatedAt=new Date().toISOString();await C.saveDraft?.()}
