function list(items,max=6){return items?.length?`<ul>${items.slice(0,max).map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p class="h38-guided-empty">None yet.</p>'}
function processingState(v,s,voice,review){if(!v||(v.videoAttachmentIds||[]).length<1)return{working:false,message:''};if(['FAILED','NO_AUDIO'].includes(voice.status)||s?.status==='FAILED')return{working:false,message:''};if(voice.status!=='COMPLETE')return{working:true,message:'H38 is turning walkthrough audio into notes…'};if(!review||['WAITING','SYNCING','ANALYZING'].includes(text(s?.status).toUpperCase()))return{working:true,message:text(s?.message||'H38 is reviewing walkthrough frames and notes…')};return{working:false,message:''}}
