function showAttention(marker){const i=identity(marker),key=attentionKey(marker);let node=document.getElementById('h38SiteVisitCleanupAttention');if(!node){node=document.createElement('section');node.id='h38SiteVisitCleanupAttention';node.className='h38-site-cleanup-attention';const host=document.querySelector('.business-bar')||document.body;host.insertAdjacentElement('afterend',node);}node.innerHTML=`<div><strong>Site Visit cleanup needs attention</strong><span>Automatic cleanup stopped after ${MAX_ATTEMPTS} verified failures. The deleted visit is hidden, but some private evidence may still remain on the server.</span><small>${text(marker.lastCleanupError||'Secure cleanup could not be verified.')}</small></div><button type="button" data-h38-retry-site-cleanup>Retry cleanup</button>`;node.querySelector('[data-h38-retry-site-cleanup]')?.addEventListener('click',()=>void retryStopped(marker));if(lastAttentionKey!==key){lastAttentionKey=key;toast('Deleted Site Visit cleanup stopped after repeated verification failures. Use “Retry cleanup” after the server/session issue is repaired.',true);}}
async function stopMarker(marker,error){const stopped={...marker,kind:STOPPED,cleanupAttempts:MAX_ATTEMPTS,lastCleanupError:text(error?.message||error),cleanupStoppedAt:new Date().toISOString(),cleanupAuthorityBuild:BUILD};await saveMarker(marker,stopped);showAttention(stopped);return stopped;}
