function printQuote(){let popup=null;try{popup=window.open('','_blank');}catch(ignore){}if(!popup){show('Allow pop-ups for Highway 38, then press Print / Save PDF again.',true);return;}popup.document.open();popup.document.write(printHtml());popup.document.close();popup.focus();show('The printable quote opened separately. Press Print / Save PDF in that window.',false);}
let pending=null;
