async function openSend(){try{hammer('Preparing quote email','Refreshing the secure session and exact saved revision');await validSession();pending=current();validate(pending);const d=sendDialog();d.querySelector('#h38FinalSendSummary').innerHTML=`<p><strong>${pending.customerName}</strong><br>${pending.customerEmail}</p><p>${pending.quoteNumber} · Revision ${pending.revision}<br><strong>${new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(pending.total)}</strong></p>`;d.querySelector('#h38FinalSendConfirm').checked=false;d.querySelector('#h38FinalSendButton').disabled=true;d.showModal();show('Review the exact revision and confirm sending.',false);}catch(error){show(error.message||String(error),true);}finally{stopHammer();}}
async function deliver(){const d=sendDialog(),button=d.querySelector('#h38FinalSendButton');button.disabled=true;button.textContent='Sending securely…';d.close();hammer('Sending quote email','Locking this exact revision and creating secure customer access');try{const live=current();if(!pending||live.quoteId!==pending.quoteId||live.revision!==pending.revision||Math.abs(live.total-pending.total)>0.01)throw new Error('The quote changed after review. Reopen Approve & Send and review the current revision.');const session=await validSession(),response=await fetch(`${cfg.url}/functions/v1/h38-quote-delivery`,{method:'POST',headers:{authorization:`Bearer ${session.access_token}`,apikey:cfg.publishableKey,'content-type':'application/json','x-client-info':'h38-quote-delivery-final-v1'},body:JSON.stringify({action:'deliverQuote',businessId:window.state?.businessId||'',quoteId:pending.quoteId,expectedRevision:pending.revision,expectedTotal:pending.total,confirmOwnerReview:true})});let payload={};try{payload=await response.json();}catch(ignore){}if(!response.ok||payload.status!=='PASS')throw new Error(payload.message||`Quote delivery failed (${response.status}).`);show(payload.message||`Quote sent securely to ${pending.customerEmail}.`,false);await window.loadBusiness?.(window.state.businessId,true);window.renderQuotes?.();}catch(error){show(`${error.message||String(error)} Nothing was sent.`,true);}finally{stopHammer();button.disabled=false;button.textContent='Confirm Send';pending=null;}}
document.addEventListener('click',event=>{const print=event.target?.closest?.('#printQuoteButton');if(print){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation?.();printQuote();return;}const send=event.target?.closest?.('#h38ApproveSendQuoteButton');if(send&&!send.disabled){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation?.();void openSend();}},true);
window.H38_QUOTE_DELIVERY_FINAL_FIX=Object.freeze({enabled:true,build:BUILD,androidStandalonePrint:true,automaticSessionRefresh:true,exactRevisionSend:true,automaticSending:false});
