function removeUnavailableRoutes(){const pages=allowed();if(!pages.size)return;document.querySelectorAll('#mainContent [data-page]').forEach(node=>{const target=text(node.dataset.page),ok=!target||pages.has(target);node.hidden=!ok;if(ok)node.removeAttribute('aria-hidden');else node.setAttribute('aria-hidden','true');});document.querySelectorAll('#mainContent a[href="#"],#mainContent a[href=""]').forEach(link=>{if(link.id||Object.keys(link.dataset||{}).length||link.getAttribute('role'))return;link.hidden=true;});}
let scheduled=false;function run(){scheduled=false;style();groupMore();if(page()==='work')return;polishToday();polishQuoteHistory();polishField();removeUnavailableRoutes();}
