  const markup=`<div class="h38-more-sheet"><div class="h38-more-head"><div><strong>More</strong><small>Tools grouped by what you are trying to do.</small></div><button type="button" data-close-more aria-label="Close">x</button></div><button type="button" class="h38-more-search" data-h38-more-search><span aria-hidden="true"></span><strong>Search Office</strong><small>Customers, properties, jobs, quotes, invoices, files, equipment and people</small></button><div class="h38-more-groups">${groups.map(([title,items])=>`<section class="h38-more-group"><h3>${html(title)}</h3><div class="h38-more-grid">${items.map(key=>`<button type="button" data-more-page="${html(key)}" data-h38-more-icon="${html(key)}"><span>${pageIcon(key)}</span><strong>${html(pageLabel(key))}</strong></button>`).join('')}</div></section>`).join('')}</div></div>`;
