function ensureDialog(){if(createDialog?.isConnected)return createDialog;createDialog=document.createElement('dialog');createDialog.className='h38-meeting-dialog';createDialog.id='h38MeetingDialog';createDialog.addEventListener('click',event=>{if(event.target.closest('[data-dialog-cancel]')){event.preventDefault();createDialog.close();}});document.body.appendChild(createDialog);return createDialog;}
function occurredFrom(date,time){if(!date)return now();const raw=`${date}T${time||'12:00'}:00`;const d=new Date(raw);return Number.isFinite(d.getTime())?d.toISOString():now();}
function showStartDialog(defaults={}){const dialog=ensureDialog();dialog.innerHTML=`<form method="dialog" id="h38StartMeetingForm"><div><h2>Start Meeting</h2><p>Start the meeting record first. Recording is optional and never starts automatically.</p></div><label>Meeting type<select name="meetingType">${typeOptions(defaults.meetingType||'Customer Meeting')}</select></label><label>Customer / company<select name="customerId">${customerOptions(defaults.customerId||'')}</select></label><label>Title<input name="title" value="${html(defaults.title||'')}" placeholder="Optional — notes on the meeting type"></label><label>Participants<input name="participants" value="${html((defaults.participantNames||[]).join(', '))}" placeholder="Names, separated by commas"></label><div class="h38-meeting-warning">Recording begins only after you intentionally tap <strong>Start recording</strong>. Use appropriate consent for your location and situation.</div><div class="actions"><button type="button" class="secondary" data-dialog-cancel>Cancel</button><button type="submit" class="primary">Create meeting</button></div></form>`;dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();try{const data=new FormData(event.currentTarget),type=text(data.get('meetingType')),customer=text(data.get('customerId')),participants=text(data.get('participants')).split(',').map(x=>x.trim()).filter(Boolean),meeting=await createMeeting({meetingType:type,customerId:customer,title:text(data.get('title'))||`${type}${customer?` — ${customerName(customer)}`:''}`,participantNames:participants,status:'In Progress'});dialog.close();selectedMeetingId=meetingId(meeting);openMeetingsPage();}catch(error){notify(error?.message||String(error),true);}};dialog.showModal();}
function showPastDialog(defaults={}){const dialog=ensureDialog(),d=new Date(),date=d.toISOString().slice(0,10);dialog.innerHTML=`<form method="dialog" id="h38PastConversationForm"><div><h2>Add Past Conversation</h2><p>Recording is not required. Type what you remember or create the record and dictate your recollection.</p></div><div class="h38-inline"><label>Approximate date<input type="date" name="date" value="${html(defaults.date||date)}"></label><label>Approximate time<input type="time" name="time" value="${html(defaults.time||'')}"></label></div><label>Conversation type<select name="meetingType">${typeOptions(defaults.meetingType||'Past Conversation')}</select></label><label>Customer / company<select name="customerId">${customerOptions(defaults.customerId||'')}</select></label><label>Person / participants<input name="participants" value="${html((defaults.participantNames||[]).join(', '))}" placeholder="Optional"></label><label>What do you remember?<textarea name="recollection" placeholder="Talked to Jim yesterday at his garage. He wants the south wall insulated…"></textarea></label><label>Optional note<input name="note" placeholder="Anything else you want kept exactly as typed"></label><div class="h38-meeting-warning">Recollections are stored as recollections. H38 will not present them as recorded evidence or verified measurements.</div><div class="actions"><button type="button" class="secondary" data-dialog-cancel>Cancel</button><button type="button" id="h38DictatePast" class="secondary">Create & dictate recollection</button><button type="submit" class="primary">Save recollection</button></div></form>`;const form=dialog.querySelector('form');async function createFromForm(dictate){try{const data=new FormData(form),recollection=text(data.get('recollection'),12000);if(!dictate&&!recollection)throw Error('Type a recollection, or use Create & dictate recollection.');const customer=text(data.get('customerId')),participants=text(data.get('participants')).split(',').map(x=>x.trim()).filter(Boolean),type=text(data.get('meetingType'))||'Past Conversation',segment=recollection?{segmentId:uid('SEG'),kind:'recollection',sourceType:'TYPED_RECOLLECTION',text:recollection,verificationStatus:'RECALLED_NOT_VERIFIED',createdAt:now()}:null,meeting=await createMeeting({meetingType:type,customerId:customer,title:`${type}${customer?` — ${customerName(customer)}`:''}`,participantNames:participants,occurredAt:occurredFrom(text(data.get('date')),text(data.get('time'))),approximateOccurredAt:true,status:'Review'},segment);const note=text(data.get('note'));if(note){meeting.manualNotes=[{noteId:uid('NOTE'),text:note,sourceType:'TYPED_RECOLLECTION',verificationStatus:'RECALLED_NOT_VERIFIED',createdAt:now()}];meeting.segments.push({segmentId:uid('SEG'),kind:'note',sourceType:'TYPED_RECOLLECTION',text:note,verificationStatus:'RECALLED_NOT_VERIFIED',createdAt:now()});meeting.sourceTypes=Array.from(new Set([...(meeting.sourceTypes||[]),'TYPED_RECOLLECTION']));await persistMeeting(meeting,'MEETING_RECOLLECTION_ADDED');}dialog.close();selectedMeetingId=meetingId(meeting);openMeetingsPage();if(dictate)await startRecording(meeting,'DICTATED_RECOLLECTION');else if(navigator.onLine)void organizeMeeting(meetingId(meeting));return meeting;}catch(error){notify(error?.message||String(error),true);return null;}}
form.onsubmit=event=>{event.preventDefault();void createFromForm(false);};dialog.querySelector('#h38DictatePast').onclick=()=>void createFromForm(true);dialog.showModal();}

function openMeetingsPage(){if(typeof window.openPage==='function')window.openPage('meetings');else renderMeetings();}
function notify(message,bad=false){if(typeof window.toast==='function')window.toast(message,bad);else console[bad?'error':'log'](message);}
function renderMeetings(){const main=document.getElementById('mainContent');if(!main)return;if(selectedMeetingId){const meeting=findMeeting(selectedMeetingId);if(meeting){renderMeetingReview(main,meeting);return;}selectedMeetingId='';}const rows=allMeetings(),openItems=actualMeetings().filter(row=>(Array.isArray(row.followUps)&&row.followUps.length)||(Array.isArray(row.actionItems)&&row.actionItems.length)||(Array.isArray(row.unknowns)&&row.unknowns.length));main.innerHTML=`<header class="page-head"><div><h1>Meetings</h1><p>Business conversations become structured memory. Recording is useful evidence, never a prerequisite.</p></div><div class="page-tools h38-meeting-actions"><button type="button" id="h38StartMeeting" class="primary">Start Meeting</button><button type="button" id="h38AddPastConversation" class="secondary">Add Past Conversation</button></div></header><div class="h38-meeting-grid"><section class="card"><h2>Recent conversations</h2><div class="h38-meeting-list">${rows.length?rows.map(meetingRowHtml).join(''):'<div class="h38-meeting-empty">No conversations yet. Start a meeting or add a past conversation.</div>'}</div></section><section class="card"><h2>Needs follow-up</h2>${openItems.length?openItems.slice(0,12).map(row=>`<div class="h38-meeting-note-line"><button type="button" class="link" data-meeting-open="${html(meetingId(row))}">${html(title(row))}</button><small>${html((row.unknowns||[]).length)} unknowns · ${html((row.actionItems||[]).length)} actions · ${html((row.followUps||[]).length)} follow-ups</small></div>`).join(''):'<p class="muted">No unresolved meeting follow-ups.</p>'}<div class="notice"><strong>Owner control:</strong> H38 can organize and prepare. It never sends messages, promises pricing, schedules work, approves quotes, purchases, or pays from a meeting summary.</div></section></div>`;main.querySelector('#h38StartMeeting').onclick=()=>showStartDialog();main.querySelector('#h38AddPastConversation').onclick=()=>showPastDialog();main.querySelectorAll('[data-meeting-open]').forEach(button=>button.onclick=()=>{selectedMeetingId=button.dataset.meetingOpen;renderMeetings();});}
function meetingRowHtml(row){const sources=meetingSources(row),status=text(value(row,'Status','status'))||'Open';return`<div class="h38-meeting-row"><div class="h38-meeting-row-top"><div><h3>${html(title(row))}</h3><p>${html(dateLabel(occurred(row)))}${customerId(row)?` · ${html(customerName(customerId(row)))}`:''}</p></div><span class="pill">${html(status)}</span></div><div>${sources.length?sources.map(sourceBadge).join(' '):sourceBadge('IMPORTED_NOTE')}</div>${text(row.summary)?`<p>${html(text(row.summary,360))}</p>`:''}<button type="button" class="secondary" data-meeting-open="${html(meetingId(row))}">Open meeting</button></div>`;}
function provenance(item){const source=text(item?.sourceType),status=text(item?.verificationStatus);return`<div class="h38-meeting-provenance">${html(sourceLabel(source))}${status?` · ${html(status.replaceAll('_',' '))}`:''}${item?.sourceReferenceId?` · ${html(item.sourceReferenceId)}`:''}</div>`;}
function sourcedList(items,key='text'){return Array.isArray(items)&&items.length?`<ul>${items.map(item=>`<li>${html(text(item?.[key],2400))}${provenance(item)}</li>`).join('')}</ul>`:'<p class="muted">None recorded.</p>';}
function reportValues(items,...keys){return(Array.isArray(items)?items:[]).map(item=>{if(typeof item==='string')return text(item,2400);for(const key of keys){const found=text(item?.[key],2400);if(found)return found;}return'';}).filter(Boolean);}
function meetingReportDocumentId(row){return`MEETING-REPORT-${meetingId(row).replace(/[^A-Za-z0-9-]+/g,'-').slice(0,120)}`;}
function meetingDocuments(row){const id=meetingId(row);return records('documents').filter(doc=>text(value(doc,'Meeting ID','meetingId'))===id||(text(value(doc,'Source Type','sourceType')).toLowerCase()==='meeting'&&text(value(doc,'Source ID','sourceId'))===id));}
function reportSection(label,items){return`<section><h2>${html(label)}</h2>${items.length?`<ul>${items.map(item=>`<li>${html(item)}</li>`).join('')}</ul>`:'<p>None recorded.</p>'}</section>`;}
function meetingReportHtml(row){const discussed=[text(row.summary,6000),...reportValues(row.customerRequests,'text'),...reportValues(row.siteConditions,'text')].filter(Boolean),decisions=reportValues(row.decisions,'text'),addedWork=reportValues(row.customerRequests,'text'),commitments=reportValues(row.commitments,'detail','text'),actions=reportValues(row.actionItems,'action','text'),unresolved=[...reportValues(row.unknowns,'text'),...reportValues(row.questionsToAsk,'text')],followUps=reportValues(row.followUps,'text','action'),participants=(Array.isArray(row.participantNames)?row.participantNames:[]).map(x=>text(x)).filter(Boolean);return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${html(title(row))} — Meeting Report</title><style>body{font:16px/1.5 system-ui,sans-serif;max-width:850px;margin:32px auto;padding:0 22px;color:#142638}header{border-bottom:3px solid #173f5f;margin-bottom:24px}h1{margin-bottom:4px}h2{font-size:1.1rem;margin:24px 0 8px}ul{padding-left:24px}.notice{padding:14px;background:#f4f7fa;border-left:4px solid #d39024}.approval{margin-top:34px;border-top:1px solid #8b98a3;padding-top:20px}.lines{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:36px}.line{border-top:1px solid #263746;padding-top:5px}@media print{body{margin:0}.notice{break-inside:avoid}}</style></head><body><header><p>Highway 38 Solutions · Business Office</p><h1>${html(title(row))}</h1><p>${html(meetingType(row))} · ${html(dateLabel(occurred(row)))}</p>${participants.length?`<p><strong>Participants:</strong> ${html(participants.join(', '))}</p>`:''}</header><div class="notice"><strong>Owner review required.</strong> This report records the discussion. Added work, pricing, commitments, and customer approval are not final until intentionally reviewed and approved.</div>${reportSection('What was discussed',discussed)}${reportSection('Requested or added work',addedWork)}${reportSection('Decisions',decisions)}${reportSection('Commitments',commitments)}${reportSection('Action items',actions)}${reportSection('Still unresolved',unresolved)}${reportSection('Follow-ups',followUps)}<section class="approval"><h2>Approval / acknowledgement</h2><p>Approve only the specifically described work, price, and terms after review.</p><div class="lines"><div class="line">Customer / participant signature and date</div><div class="line">Highway 38 owner approval and date</div></div></section></body></html>`;}
function meetingReportHtmlV2(row){
  const customer=[customerName(customerId(row)),text(row.customerEmail),text(row.customerPhone)].filter(Boolean),property=[text(row.propertyAddress),text(row.billingAddress)].filter(Boolean),measurements=reportValues(row.measurements,'statement','valueText','text'),evidence=reportValues(row.attachments,'fileName','text');
  return meetingReportHtml(row)
    .replace('<h2>What was discussed</h2>','<h2>Meeting Summary</h2>')
    .replace('<h2>Requested or added work</h2>','<h2>Work Requested</h2>')
    .replace('<h2>Still unresolved</h2>','<h2>Open Questions</h2>')
    .replace('<h2>Follow-ups</h2>','<h2>Follow-Up</h2>')
    .replace('<section class="approval">',`${reportSection('Customer Information',customer)}${reportSection('Property / Job Information',property)}${reportSection('Measurements / Details',measurements)}${reportSection('Additional Work Discussed',reportValues(row.customerRequests,'text'))}${reportSection('Customer Commitments',reportValues(row.customerCommitments,'detail','text'))}${reportSection('H38 Commitments',reportValues(row.commitments,'detail','text'))}${reportSection('Quote / Change Requirements',reportValues(row.quoteRequirements,'text','detail'))}${reportSection('Attached Evidence',evidence)}<section class="approval">`);
}
async function ensureMeetingReport(row){const id=meetingId(row),attachmentId=meetingReportDocumentId(row),blob=new Blob([meetingReportHtmlV2(row)],{type:'text/html'}),safeTitle=title(row).replace(/[^A-Za-z0-9._-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,100)||'meeting',item={id:attachmentId,attachmentId,businessId:office().businessId,relatedRecordType:'Meeting',relatedRecordId:id,meetingId:id,meetingSegmentId:'MEETING-REPORT',fileName:`${safeTitle}-meeting-report.html`,mimeType:'text/html',fileSize:blob.size,captureTime:now(),visibility:'Internal',meetingAttachment:true,meetingAudio:false,meetingReport:true,evidenceProvenance:'STRUCTURED_MEETING_REPORT',evidenceType:'Meeting Report',syncStatus:'PENDING',blobData:blob};await window.H38DB.put('attachments',item);row.meetingReportDocumentId=attachmentId;row['Meeting Report Document ID']=attachmentId;await persistMeeting(row,'MEETING_REPORT_PREPARED');if(navigator.onLine)await uploadMeetingAttachment(item);return attachmentId;}
function bindMeetingDocumentButtons(main,row){const byId=new Map(meetingDocuments(row).map(doc=>[text(value(doc,'Document ID','documentId')),doc]));main.querySelectorAll('[data-h38-meeting-document]').forEach(button=>button.onclick=()=>{const doc=byId.get(button.dataset.h38MeetingDocument);if(!doc){notify('This meeting file is still syncing. Try again in a moment.',true);return;}const opener=window.H38_OFFICE_SCALE_WORKFLOW?.openDocument;if(typeof opener!=='function'){notify('The secure file opener is still loading. Try again.',true);return;}void opener(doc).catch(error=>notify(error?.message||String(error),true));});}
function beforeVisitContext(customer){if(!customer)return null;const history=actualMeetings().filter(row=>customerId(row)===customer).sort((a,b)=>new Date(occurred(b)||0)-new Date(occurred(a)||0)),last=history[0],unknowns=[],actions=[],requests=[];for(const row of history.slice(0,4)){for(const item of row.unknowns||[])if(text(item?.text))unknowns.push(text(item.text));for(const item of row.actionItems||[])if(text(item?.action))actions.push(text(item.action));for(const item of row.customerRequests||[])if(text(item?.text))requests.push(text(item.text));}const quotes=records('quotes').filter(row=>text(value(row,'Customer ID','customerId'))===customer).sort((a,b)=>new Date(value(b,'Updated Time','updatedAt')||0)-new Date(value(a,'Updated Time','updatedAt')||0)),jobs=records('jobs').filter(row=>text(value(row,'Customer ID','customerId'))===customer).sort((a,b)=>new Date(value(b,'Updated Time','updatedAt')||0)-new Date(value(a,'Updated Time','updatedAt')||0));return{lastMeeting:last,unknowns:Array.from(new Set(unknowns)).slice(0,5),actions:Array.from(new Set(actions)).slice(0,5),requests:Array.from(new Set(requests)).slice(0,4),quote:quotes[0]||null,job:jobs[0]||null};}
function beforeVisitHtml(customer){const ctx=beforeVisitContext(customer);if(!ctx||(!ctx.lastMeeting&&!ctx.quote&&!ctx.job))return'';const q=ctx.quote,j=ctx.job;return`<section class="h38-before-visit"><h3>Before Visit</h3>${ctx.lastMeeting?`<p><strong>Last conversation</strong>${html(title(ctx.lastMeeting))} · ${html(dateLabel(occurred(ctx.lastMeeting)))}</p>`:''}${ctx.requests.length?`<strong>Recent requests</strong><ul>${ctx.requests.map(x=>`<li>${html(x)}</li>`).join('')}</ul>`:''}${ctx.unknowns.length?`<strong>Still unresolved</strong><ul>${ctx.unknowns.map(x=>`<li>${html(x)}</li>`).join('')}</ul>`:''}${ctx.actions.length?`<strong>Open actions</strong><ul>${ctx.actions.map(x=>`<li>${html(x)}</li>`).join('')}</ul>`:''}${q?`<p><strong>Quote</strong>${html(text(value(q,'Quote Number','quoteNumber','Quote ID','quoteId')))} — ${html(text(value(q,'Status','status'))||'Draft')}</p>`:''}${j?`<p><strong>Job</strong>${html(text(value(j,'Project Title','projectTitle','Job Number','jobNumber')))} — ${html(text(value(j,'Status','status')))}</p>`:''}</section>`;}
function renderMeetingReview(main,row){const legacy=isLegacy(row),sources=meetingSources(row),segments=Array.isArray(row.segments)?row.segments:[],transcript=text(row.transcript)||segments.map(s=>text(s.transcript||s.text)).filter(Boolean).join('\n\n'),customer=customerId(row),documents=meetingDocuments(row);main.innerHTML=`<header class="page-head"><div><button type="button" id="h38MeetingBack" class="link">← Meetings</button><h1>${html(title(row))}</h1><p>${html(meetingType(row))} · ${html(dateLabel(occurred(row)))}${customer?` · ${html(customerName(customer))}`:''}</p><div>${sources.map(sourceBadge).join(' ')}</div></div><div class="page-tools h38-meeting-actions">${legacy?'':`<button type="button" id="h38MeetingRecord" class="primary">${segments.some(s=>sourceType(s)==='RECORDED_AUDIO')?'Continue recording':'Start recording'}</button><button type="button" id="h38MeetingFinish" class="secondary">Finish & organize</button>`}${customer?'<button type="button" id="h38MeetingFollowup" class="secondary">Start follow-up meeting</button>':''}<button type="button" id="h38MeetingQuote" class="secondary">Use in Quote</button></div></header><div class="h38-meeting-review">${beforeVisitHtml(customer)}${legacy?'<div class="notice">Historical Site Visit projection. Existing Site Visit data remains unchanged.</div>':''}<section><h2>Summary</h2>${text(row.summary)?`<p>${html(row.summary)}</p>`:'<p class="muted">Structured summary not ready yet. Original notes and evidence remain below.</p>'}</section><section><h3>Customer / Participant Requests</h3>${sourcedList(row.customerRequests)}</section><section><h3>Decisions</h3>${sourcedList(row.decisions)}</section><section><h3>Commitments</h3>${Array.isArray(row.commitments)&&row.commitments.length?`<ul>${row.commitments.map(item=>`<li><strong>${html(text(item.who)||'Participant')}:</strong> ${html(text(item.detail))}${provenance(item)}</li>`).join('')}</ul>`:'<p class="muted">None recorded.</p>'}</section><section><h3>Site Conditions</h3>${sourcedList(row.siteConditions)}</section><section><h3>Measurements</h3>${Array.isArray(row.measurements)&&row.measurements.length?`<ul>${row.measurements.map(item=>`<li><strong>${html(text(item.label)||'Measurement')}:</strong> ${html(text(item.valueText)||text(item.statement))}${provenance(item)}</li>`).join('')}</ul>`:'<p class="muted">None recorded.</p>'}</section><section><h3>Unknowns</h3>${sourcedList(row.unknowns)}</section><section><h3>Action Items</h3>${sourcedList(row.actionItems,'action')}</section><section><h3>Questions for Next Meeting</h3>${sourcedList(row.questionsToAsk)}</section><section><h3>Follow-ups</h3>${sourcedList(row.followUps)}</section><section><h3>Meeting report & evidence</h3>${documents.length?`<div class="h38-meeting-list">${documents.map(doc=>`<div class="h38-meeting-note-line"><strong>${html(value(doc,'File Name','fileName')||'Meeting file')}</strong><small>${html(value(doc,'Evidence Type','evidenceType','Mime Type','mimeType'))}</small><button type="button" class="secondary" data-h38-meeting-document="${html(value(doc,'Document ID','documentId'))}">Open file</button></div>`).join('')}</div>`:'<p class="muted">Finish & organize to create the meeting report. Recordings and photos appear here after private online sync.</p>'}</section><section><h3>Source timeline</h3>${segments.length?segments.map(segment=>`<div class="h38-meeting-note-line">${sourceBadge(sourceType(segment))} <strong>${html(text(segment.category||segment.kind)||'Segment')}</strong>${text(segment.transcript||segment.text)?`<p>${html(text(segment.transcript||segment.text,4000))}</p>`:''}</div>`).join(''):'<p class="muted">No source segments.</p>'}</section>${transcript?`<section><h3>Transcript / recollection</h3><div class="h38-meeting-transcript">${html(transcript)}</div></section>`:''}<section><h3>Linked records</h3><div class="h38-meeting-link-grid">${customer?`<span>Customer: ${html(customerName(customer))}</span>`:''}${quoteId(row)?`<span>Quote: ${html(quoteId(row))}</span>`:''}${jobId(row)?`<span>Job: ${html(jobId(row))}</span>`:''}${text(row.siteVisitId)?`<span>Site Visit: ${html(row.siteVisitId)}</span>`:''}${!customer&&!quoteId(row)&&!jobId(row)&&!row.siteVisitId?'<span>Business-only meeting</span>':''}</div></section></div>`;main.querySelector('#h38MeetingBack').onclick=()=>{selectedMeetingId='';renderMeetings();};if(!legacy){main.querySelector('#h38MeetingRecord').onclick=()=>void startRecording(row,'RECORDED_AUDIO');main.querySelector('#h38MeetingFinish').onclick=()=>void finishMeeting(row);}if(customer)main.querySelector('#h38MeetingFollowup').onclick=()=>showStartDialog({meetingType:'Follow-up Visit',customerId:customer,title:`Follow-up — ${customerName(customer)}`});main.querySelector('#h38MeetingQuote').onclick=()=>useInQuote(row);bindMeetingDocumentButtons(main,row);}

function quoteContext(row){return{meetingId:meetingId(row),meetingType:meetingType(row),occurredAt:occurred(row),sourceTypes:meetingSources(row),summary:text(row.summary,5000),customerRequests:Array.isArray(row.customerRequests)?row.customerRequests:[],decisions:Array.isArray(row.decisions)?row.decisions:[],commitments:Array.isArray(row.commitments)?row.commitments:[],siteConditions:Array.isArray(row.siteConditions)?row.siteConditions:[],measurements:Array.isArray(row.measurements)?row.measurements:[],unknowns:Array.isArray(row.unknowns)?row.unknowns:[],sourceReferences:Array.isArray(row.sourceReferences)?row.sourceReferences:[],ownerReviewStatus:text(row.ownerReviewStatus)||'REQUIRED',provenanceRequired:true};}
function useInQuote(row){const q=office().quote||(office().quote={quoteId:'',lines:[]});q.meetingContext=quoteContext(row);if(customerId(row))q.customerId=customerId(row);if(quoteId(row))q.quoteId=quoteId(row);window.H38_MEETING_QUOTE_CONTEXT=q.meetingContext;if(typeof window.openPage==='function')window.openPage('quotes');if(quoteId(row)&&typeof window.openQuote==='function')setTimeout(()=>window.openQuote(quoteId(row)),20);notify('Meeting context is available to Quote Builder with provenance. Nothing was sent or approved.');}

async function organizeMeeting(id){if(!id)return null;if(!navigator.onLine){const row=findMeeting(id);if(row){row.pendingOrganization=true;applyMeetingSnapshot(row);}notify('Meeting is saved. H38 will organize it and create the report after reconnecting.');return null;}try{await ensureServerMeeting(id);let result;try{if(!window.H38_AI_HANDOFF)throw Object.assign(Error('AI handoff helper not loaded.'),{code:'HANDOFF_NOT_DEPLOYED'});notify('Hank is organizing…');result=await window.H38_AI_HANDOFF.runTask('organize_notes',{businessId:office().businessId,meetingId:id});}catch(kitError){const kitMsg=String(kitError?.message||kitError||'');const kitUnavailable=kitError?.code==='HANDOFF_NOT_DEPLOYED'||/timed out|(?:Kit|Hank) could not complete|handoff/i.test(kitMsg);if(!kitUnavailable)throw kitError;notify('Hank is unavailable — using built-in AI instead.');result=await callFunction('h38-conversation-organize',{businessId:office().businessId,meetingId:id});}const fresh=result.meeting||await refreshMeeting(id);if(fresh){fresh.pendingOrganization=false;applyMeetingSnapshot(fresh);try{await ensureMeetingReport(fresh);notify('Meeting organized. The private report is ready to open.');}catch(reportError){notify(`Meeting organized. Report upload is queued: ${reportError?.message||reportError}`,true);}}if(selectedMeetingId===id&&office().page==='meetings')renderMeetings();return fresh;}catch(error){notify(`Meeting source is safe. Organization needs attention: ${error?.message||error}`,true);return null;}}
async function finishMeeting(row){const hadRecording=recording?.meetingId===meetingId(row);if(hadRecording)await finishRecording('meeting-finish');const current=findMeeting(meetingId(row))||row;if(isLegacy(current))return;current.status='Review';current['Status']='Review';current.ownerReviewStatus='REQUIRED';if(!hadRecording){await persistMeeting(current,'MEETING_UPDATED');await organizeMeeting(meetingId(current));}else await refreshMeeting(meetingId(current));selectedMeetingId=meetingId(current);renderMeetings();}

function preferredMime(){if(!window.MediaRecorder)return'';for(const mime of ['audio/webm;codecs=opus','audio/webm','audio/mp4'])if(!MediaRecorder.isTypeSupported||MediaRecorder.isTypeSupported(mime))return mime;return'';}
function localAttachmentId(){return uid('MEETING-AUDIO');}
async function checkpointRecording(final=false){if(!recording||!window.H38DB?.put)return;const blob=new Blob(recording.chunks,{type:recording.mime||'audio/webm'});if(!blob.size)return;await window.H38DB.put('attachments',{id:recording.attachmentId,attachmentId:recording.attachmentId,businessId:office().businessId,relatedRecordType:'Meeting',relatedRecordId:recording.meetingId,meetingId:recording.meetingId,meetingSegmentId:recording.segmentId,fileName:`conversation-${recording.segmentId}.${recording.mime.includes('mp4')?'m4a':'webm'}`,mimeType:recording.mime||'audio/webm',fileSize:blob.size,captureTime:recording.startedAt,visibility:'Internal',meetingAttachment:true,meetingAudio:true,evidenceProvenance:recording.sourceType,evidenceType:recording.sourceType==='DICTATED_RECOLLECTION'?'Dictated Recollection Audio':'Conversation Audio',syncStatus:final?'PENDING_AUDIO':'LOCAL_RECORDING',blobData:blob});recording.localBytes=blob.size;}
function stopTracks(){try{recording?.stream?.getTracks?.().forEach(track=>track.stop());}catch(_){};}
function formatElapsed(ms){const total=Math.max(0,Math.floor(ms/1000)),m=Math.floor(total/60),s=total%60;return`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
function renderRecordingDock(){let dock=document.getElementById('h38MeetingRecordingDock');if(!recording){dock?.remove();clearInterval(recordingTimer);recordingTimer=null;return;}if(!dock){dock=document.createElement('div');dock.id='h38MeetingRecordingDock';dock.className='h38-recording-dock';document.body.appendChild(dock);}dock.innerHTML=`<div class="h38-recording-head"><div class="h38-recording-live"><span class="h38-recording-dot"></span><span>${html(recording.sourceType==='DICTATED_RECOLLECTION'?'Listening — Dictated recollection':`Listening — ${meetingType(findMeeting(recording.meetingId)||{})}`)}</span></div><span class="h38-recording-time" id="h38MeetingRecordingTime">${formatElapsed(Date.now()-new Date(recording.startedAt).getTime())}</span></div><div class="h38-meeting-quick-source"><button type="button" data-meeting-note="Note">+ Note</button><button type="button" data-meeting-note="Important">+ Important</button><button type="button" data-meeting-note="Customer Request">+ Customer Request</button><button type="button" data-meeting-note="Measurement">+ Measurement</button><button type="button" id="h38MeetingPhoto">+ Photo</button></div><div class="h38-recording-actions"><button type="button" id="h38MeetingPause" class="secondary">${recording.paused?'Resume':'Pause'}</button><button type="button" id="h38MeetingStop" class="primary">Finish Conversation</button></div>`;dock.querySelectorAll('[data-meeting-note]').forEach(button=>button.onclick=()=>void quickNote(button.dataset.meetingNote));dock.querySelector('#h38MeetingPhoto').onclick=()=>void chooseMeetingPhoto(recording.meetingId);dock.querySelector('#h38MeetingPause').onclick=togglePause;dock.querySelector('#h38MeetingStop').onclick=()=>void finishRecording('meeting-finish');clearInterval(recordingTimer);recordingTimer=setInterval(()=>{const node=document.getElementById('h38MeetingRecordingTime');if(node&&recording)node.textContent=formatElapsed(Date.now()-new Date(recording.startedAt).getTime());},1000);}
async function startRecording(row,source='RECORDED_AUDIO'){const id=meetingId(row);if(!id||isLegacy(row))return;if(recording){if(recording.meetingId===id)return;notify('Finish the current conversation recording before starting another.',true);return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('This device cannot record meeting audio in Business Office.',true);return;}if(source==='RECORDED_AUDIO'&&!window.confirm('Start visible meeting recording now? Make sure recording is appropriate and you have any consent required for this conversation.'))return;try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false}),mime=preferredMime(),options=mime?{mimeType:mime}:{},recorder=new MediaRecorder(stream,options),attachmentId=localAttachmentId(),segmentId=uid('SEG'),current=findMeeting(id)||row,segment={segmentId,kind:'audio',sourceType:source,audioAttachmentId:attachmentId,transcriptionStatus:'PENDING',verificationStatus:source==='DICTATED_RECOLLECTION'?'RECALLED_NOT_VERIFIED':'RECORDED_NOT_INDEPENDENTLY_VERIFIED',createdAt:now()};current.segments=Array.isArray(current.segments)?current.segments:[];current.segments.push(segment);current.sourceTypes=Array.from(new Set([...(current.sourceTypes||[]),source]));current.status='In Progress';current['Status']='In Progress';await persistMeeting(current,source==='DICTATED_RECOLLECTION'?'MEETING_RECOLLECTION_ADDED':'MEETING_UPDATED');recording={meetingId:id,segmentId,attachmentId,sourceType:source,recorder,stream,mime:recorder.mimeType||mime||'audio/webm',chunks:[],startedAt:now(),paused:false,localBytes:0};recorder.ondataavailable=event=>{if(event.data?.size){recording?.chunks.push(event.data);void checkpointRecording(false).catch(error=>console.warn('[H38 meeting checkpoint]',error?.message||error));}};recorder.start(2000);renderRecordingDock();notify('Meeting recording is visible and active. Audio checkpoints are staying on this device.');}catch(error){stopTracks();recording=null;renderRecordingDock();notify(error?.message||'Microphone recording could not start.',true);}}
async function finishRecording(reason='manual'){if(!recording)return null;const active=recording,recorder=active.recorder;try{if(recorder&&recorder.state!=='inactive'){await new Promise(resolve=>{recorder.addEventListener('stop',resolve,{once:true});recorder.stop();});}await checkpointRecording(true);const row=findMeeting(active.meetingId);if(row){const segment=(row.segments||[]).find(s=>text(s.segmentId)===active.segmentId);if(segment){segment.recordingStatus='SAVED_LOCAL';segment.finishedAt=now();segment.audioAttachmentId=active.attachmentId;}row.sourceTypes=Array.from(new Set([...(row.sourceTypes||[]),active.sourceType]));if(reason==='meeting-finish'){row.status='Review';row['Status']='Review';}await persistMeeting(row,'MEETING_UPDATED');}notify(reason==='walkthrough-handoff'?'Conversation segment saved on this device. Opening walkthrough…':'Conversation audio saved on this device.');}finally{stopTracks();recording=null;renderRecordingDock();}if(navigator.onLine){if(reason==='meeting-finish')await syncPendingMeetingAttachments();else void syncPendingMeetingAttachments();}return active;}
function togglePause(){if(!recording)return;try{if(recording.recorder.state==='recording'){recording.recorder.pause();recording.paused=true;}else if(recording.recorder.state==='paused'){recording.recorder.resume();recording.paused=false;}renderRecordingDock();}catch(error){notify(error?.message||String(error),true);}}
async function quickNote(category){if(!recording)return;const note=window.prompt(`${category}:`,'');if(!text(note))return;const row=findMeeting(recording.meetingId);if(!row)return;const segment={segmentId:uid('SEG'),kind:'manual-note',category,sourceType:'LIVE_TYPED_NOTE',text:text(note,6000),verificationStatus:'SOURCE_NOTE',createdAt:now(),highPriority:true};row.segments=Array.isArray(row.segments)?row.segments:[];row.segments.push(segment);row.manualNotes=Array.isArray(row.manualNotes)?row.manualNotes:[];row.manualNotes.push({noteId:uid('NOTE'),category,text:segment.text,sourceType:'LIVE_TYPED_NOTE',createdAt:segment.createdAt,highPriority:true});row.sourceTypes=Array.from(new Set([...(row.sourceTypes||[]),'LIVE_TYPED_NOTE']));await persistMeeting(row,'MEETING_NOTE_ADDED');notify(`${category} saved. AI organization will not overwrite the original note.`);}

async function chooseMeetingPhoto(id){const input=document.createElement('input');input.type='file';input.accept='image/*';input.capture='environment';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{await saveMeetingFile(id,file,'ATTACHMENT','Meeting Photo');notify('Photo saved with this meeting.');}catch(error){notify(error?.message||String(error),true);}};input.click();}
async function saveMeetingFile(id,file,source='ATTACHMENT',evidenceType='Attachment'){const row=findMeeting(id);if(!row)throw Error('Meeting record is unavailable.');const attachmentId=uid('MEETING-FILE'),segmentId=uid('SEG'),item={id:attachmentId,attachmentId,businessId:office().businessId,relatedRecordType:'Meeting',relatedRecordId:id,meetingId:id,meetingSegmentId:segmentId,fileName:text(file.name,220)||`meeting-file-${Date.now()}`,mimeType:text(file.type,120)||'application/octet-stream',fileSize:file.size,captureTime:now(),visibility:'Internal',meetingAttachment:true,meetingAudio:false,evidenceProvenance:source,evidenceType,syncStatus:'PENDING',blobData:file};await window.H38DB.put('attachments',item);row.attachments=Array.isArray(row.attachments)?row.attachments:[];row.attachments.push(attachmentId);row.segments=Array.isArray(row.segments)?row.segments:[];row.segments.push({segmentId,kind:'attachment',sourceType:source,attachmentId,fileName:item.fileName,mimeType:item.mimeType,createdAt:item.captureTime});row.sourceTypes=Array.from(new Set([...(row.sourceTypes||[]),source]));await persistMeeting(row,'MEETING_UPDATED');if(navigator.onLine)void syncPendingMeetingAttachments();return attachmentId;}
