function visit(){return window.H38_FIELD_VISIT_CORE?.state?.open===true?window.H38_FIELD_VISIT_CORE.state.visit:null;}
function meetingForVisit(v){if(!v)return null;return actualMeetings().find(row=>(text(row.siteVisitId)&&text(row.siteVisitId)===text(v.visitId))||(text(row.siteCaptureSessionId)&&text(row.siteCaptureSessionId)===text(v.sessionId)))||null;}
