function renderVisitDock(){let dock=document.getElementById('h38MeetingVisitDock');const v=visit();if(!v||recording){dock?.remove();return;}const row=meetingForVisit(v);if(!dock){dock=document.createElement('div');dock.id='h38MeetingVisitDock';dock.className='h38-meeting-visit-dock';document.body.appendChild(dock);}dock.innerHTML=`<button type="button" id="h38VisitAssistantButton" class="primary">${row?'Resume Conversation':'Start Visit Assistant'}</button>${row?`<button type="button" id="h38VisitMeetingOpen" class="secondary">Meeting</button>`:''}`;dock.querySelector('#h38VisitAssistantButton').onclick=()=>void startVisitAssistant();if(row)dock.querySelector('#h38VisitMeetingOpen').onclick=()=>{selectedMeetingId=meetingId(row);openMeetingsPage();};void syncWalkthroughSegment();}
