function currentConversation(){return rows('conversations').find(r=>text(val(r,'Conversation ID'))===conversationId);}
async function startTest(customerId=''){sessionId=uid('RECEPTIONIST-TEST');conversationId=sessionId;sessionCustomer=customerId;const stamp=now(),record={'Conversation ID':conversationId,'Business ID':state().businessId,'Customer ID':customerId,'Conversation Type':'AI Receptionist Test','Subject':`Receptionist test · ${stamp.slice(0,16).replace('T',' ')}`,'Channel':'AI_RECEPTIONIST_TEST','Status':'Test only','Participant IDs JSON':JSON.stringify([state().snapshot?.user?.userId||'']),'Created Time':stamp,'Updated Time':stamp,'Record Version':1,'External Action Occurred':false};await save('conversations','Conversation',conversationId,record,['Conversation ID']);updateLocal('conversations',conversationId,record,'Conversation ID');const log=communicationLog({customerId,title:'AI receptionist test session',channel:'AI Receptionist Test',outcome:'Test only — no call answered',summary:'A staff member started this simulated test. No telephone call was placed or received.'});await saveLog(log);return record;}
