function profileForAi(speechVoice){const c=config(),selectedCustomer=rows('customers').find(r=>text(val(r,'Customer ID','customerId'))===sessionCustomer),isH38=/highway\s*38|h38/i.test(businessName());return{businessName:businessName(),greeting:c.greeting,businessHours:c.businessHours,serviceArea:c.serviceArea,services:c.services,faqs:c.faqs,routing:c.routing,afterHours:c.afterHours,allowedActions:c.allowedActions,voice:c.voice,speechVoice:speechVoice==='cedar'?'cedar':'marin',existingAccountSelected:!!selectedCustomer,h38ServicePolicy:isH38?'For snow plowing and lawn mowing, a new property requires a site visit before quote or service; a verified existing account can be scheduled without a new site visit.':'',officeLocalTime:new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date()),officeTimeZone:Intl.DateTimeFormat().resolvedOptions().timeZone||'',customerName:selectedCustomer?.['Customer Name']||'',authorizedBillingContext:billingContext()};}
function billingContext(){if(!sessionCustomer||!window.H38_CUSTOMER_360?.canViewMoney?.(state()))return'';const invoices=rows('invoices').filter(r=>text(val(r,'Customer ID'))===sessionCustomer&&Number(val(r,'Balance Due','Balance'))>0);if(!invoices.length)return'No open invoice balance was found in the supplied authorized Office snapshot.';return invoices.slice(0,5).map(r=>`${text(val(r,'Invoice Number'))||'Invoice'}: open balance ${Number(val(r,'Balance Due','Balance')).toFixed(2)}; status ${text(val(r,'Status'))||'unknown'}`).join('\n');}
async function askReceptionist(question){question=text(question);if(!question||busy)return;busy=true;const form=document.getElementById('receptionistForm'),speechVoice=form?.elements?.speechVoice?.value==='cedar'?'cedar':'marin';state().receptionistSpeechVoice=speechVoice;try{if(!conversationId)await startTest(form?.elements?.customerId?.value||'');await storeTurn('user',question);const result=await state().bridge.request('aiAsk',{businessId:state().businessId,question,pageKey:'messages',context:{source:'ai-receptionist-test',shell:state().shell||'office',pageKey:'messages',pageLabel:'Communications · receptionist test',experienceMode:'receptionist_test',receptionistProfile:profileForAi(speechVoice)},aiConversationId:conversationId});const answer=text(result.answer);if(!answer)throw new Error('AI did not return a response.');await storeTurn('assistant',answer);state().receptionistDraft=(state().receptionistDraft||[]).concat([{role:'user',body:question},{role:'assistant',body:answer}]);const oldAudio=state().receptionistAudioUrl;if(oldAudio&&oldAudio.startsWith('blob:'))URL.revokeObjectURL(oldAudio);state().receptionistAudioUrl='';state().receptionistSpeechStatus=result.speechStatus||'unavailable';state().receptionistSpeechVoice=speechVoice;render();if(result.speechAudioBase64)speakTestReply(result.speechAudioBase64,result.speechVoice||speechVoice);}catch(error){window.toast?.(`Receptionist test could not reach the existing AI route: ${error.message||error}`,true);}finally{busy=false;}}
