  if(/(?:raise|change|set|make).*(?:plow|snow|mow|lawn|service).*(?:rate|price|\$| to )/.test(q))return true;
  if(/(?:raise|increase|change).*?(?:plow|snow|mow|lawn).*?[0-9]+(?:\.[0-9]+)?\s*%/.test(q))return true;
